pub enum CliResult {
    Help(String),
    Version(String),
    Parsed(Options),
    Err(String),
}

fn usage_line(prog: &str) -> String {
    format!("Usage: {prog} [OPTIONS] [INPUT]...")
}

fn z_usage_line(kind: &str) -> String {
    match kind {
        "z" => "Usage: solar [OPTIONS]".to_string(),
        _ => format!("Usage: solar {kind}"),
    }
}

fn err_block(msg: &str, usage: Option<&str>, more: &str) -> String {
    let mut s = format!("error: {msg}\n\n");
    if let Some(u) = usage {
        s.push_str(u);
        s.push_str("\n\n");
    }
    s.push_str(more);
    s.push_str("\n\n");
    s
}

fn main_err_block(msg: &str, prog: &str, usage: Option<&str>, more: &str) -> String {
    let mut s = format!("error: {msg}\n\n");
    if let Some(u) = usage {
        s.push_str(u);
        s.push_str("\n\n");
    }
    s.push_str(more);
    s.push_str("\n\n");
    let _ = prog;
    s
}

