fn jaro_winkler(a: &str, b: &str) -> f64 {
    let ac: Vec<char> = a.chars().collect();
    let bc: Vec<char> = b.chars().collect();
    if ac.is_empty() || bc.is_empty() {
        return 0.0;
    }
    let max_len = ac.len().max(bc.len());
    let search_range = (max_len / 2).saturating_sub(1);
    let mut b_consumed = vec![false; bc.len()];
    let mut matches = 0usize;
    let mut transpositions = 0usize;
    let mut b_match_index = 0usize;
    for (i, &a_elem) in ac.iter().enumerate() {
        let min_bound = i.saturating_sub(search_range);
        let max_bound = (i + search_range + 1).min(bc.len());
        if min_bound >= max_bound {
            continue;
        }
        for j in min_bound..max_bound {
            if a_elem == bc[j] && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1;
                if j < b_match_index {
                    transpositions += 1;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let m = matches as f64;
    let mut jaro = (m / ac.len() as f64 + m / bc.len() as f64 + (m - transpositions as f64) / m)
        / 3.0;
    if jaro > 0.7 {
        let prefix_len = ac
            .iter()
            .zip(bc.iter())
            .take_while(|(a_elem, b_elem)| a_elem == b_elem)
            .count()
            .min(4);
        jaro += 0.1 * prefix_len as f64 * (1.0 - jaro);
    }
    jaro
}

fn did_you_mean(v: &str, candidates: &[&str]) -> Option<String> {
    let mut best: Option<(f64, &str)> = None;
    for c in candidates {
        let conf = jaro_winkler(v, c);
        if conf > 0.7 {
            match best {
                Some((bc, _)) if bc >= conf => {}
                _ => best = Some((conf, c)),
            }
        }
    }
    best.map(|(_, c)| c.to_string())
}

fn strip_long(a: &str) -> (&str, Option<&str>) {
    match a.split_once('=') {
        Some((n, v)) => (n, Some(v)),
        None => (a, None),
    }
}

pub fn parse(args: &[String]) -> CliResult {
    let prog: String = std::env::args()
        .next()
        .map(|a| {
            let p = std::path::Path::new(&a);
            p.file_name()
                .map(|f| f.to_string_lossy().to_string())
                .unwrap_or_else(|| a.clone())
        })
        .unwrap_or_else(|| NAME.to_string());
    let mut opts = Options::default();
    let mut i = 0usize;
    let mut only_inputs = false;
    let mut seen: Vec<&str> = vec![];
    let dup = |seen: &mut Vec<&str>, name: &str| -> Option<String> {
        if seen.contains(&name) {
            return Some(main_err_block(
                &format!("the argument '{name}' cannot be used multiple times"),
                &prog,
                Some(&usage_line(&prog)),
                "For more information, try '--help'.",
            ));
        }
        seen.push(name);
        None
    };
    let long_names: Vec<&str> = vec![
        "threads",
        "jobs",
        "evm-version",
        "stop-after",
        "out-dir",
        "emit",
        "base-path",
        "include-path",
        "allow-paths",
        "color",
        "verbose",
        "pretty-json",
        "pretty-json-err",
        "error-format",
        "error-format-human",
        "diagnostic-width",
        "no-warnings",
        "help",
        "version",
    ];
    while i < args.len() {
        let a = &args[i];
        if only_inputs {
            opts.inputs.push(a.clone());
            i += 1;
            continue;
        }
        if a == "--" {
            only_inputs = true;
            i += 1;
            continue;
        }
        if a == "-h" || a == "--help" {
            return CliResult::Help(long_help(&prog));
        }
        if a == "-V" {
            return CliResult::Version(short_version());
        }
        if a == "--version" {
            return CliResult::Version(long_version());
        }
        if a.starts_with("--") {
            let (name, inline_val) = strip_long(&a[2..]);
            let known = long_names.contains(&name);
            if !known {
                if let Some(sug) = did_you_mean(name, &long_names) {
                    let usage = match sug.as_str() {
                        "threads" | "jobs" => format!("Usage: {prog} --threads <THREADS> <INPUT>..."),
                        "evm-version" => format!("Usage: {prog} --evm-version <EVM_VERSION> <INPUT>..."),
                        "stop-after" => format!("Usage: {prog} --stop-after <STOP_AFTER> <INPUT>..."),
                        "out-dir" => format!("Usage: {prog} --out-dir <OUT_DIR> <INPUT>..."),
                        "emit" => format!("Usage: {prog} --emit <EMIT> <INPUT>..."),
                        "base-path" => format!("Usage: {prog} --base-path <BASE_PATH> <INPUT>..."),
                        "include-path" => format!("Usage: {prog} --include-path <INCLUDE_PATH> <INPUT>..."),
                        "allow-paths" => format!("Usage: {prog} --allow-paths <ALLOW_PATHS> <INPUT>..."),
                        "color" => format!("Usage: {prog} --color <COLOR> <INPUT>..."),
                        "verbose" => format!("Usage: {prog} --verbose <INPUT>..."),
                        "pretty-json" => format!("Usage: {prog} --pretty-json <INPUT>..."),
                        "pretty-json-err" => format!("Usage: {prog} --pretty-json-err <INPUT>..."),
                        "error-format" => format!("Usage: {prog} --error-format <ERROR_FORMAT> <INPUT>..."),
                        "error-format-human" => format!("Usage: {prog} --error-format-human <VALUE> <INPUT>..."),
                        "diagnostic-width" => format!("Usage: {prog} --diagnostic-width <WIDTH> <INPUT>..."),
                        "no-warnings" => format!("Usage: {prog} --no-warnings <INPUT>..."),
                        _ => usage_line(&prog),
                    };
                    let msg = format!(
                        "unexpected argument '--{name}' found\n\n  tip: a similar argument exists: '--{sug}'"
                    );
                    return CliResult::Err(main_err_block(&msg, &prog, Some(&usage), "For more information, try '--help'."));
                }
                let msg = format!(
                    "unexpected argument '--{name}' found\n\n  tip: to pass '--{name}' as a value, use '-- --{name}'"
                );
                return CliResult::Err(main_err_block(&msg, &prog, Some(&usage_line(&prog)), "For more information, try '--help'."));
            }
            match name {
                "help" => return CliResult::Help(long_help(&prog)),
                "version" => return CliResult::Version(long_version()),
                "verbose" => {
                    if let Some(e) = dup(&mut seen, "--verbose") {
                        return CliResult::Err(e);
                    }
                    opts.verbose = true;
                }
                "pretty-json" => {
                    if let Some(e) = dup(&mut seen, "--pretty-json") {
                        return CliResult::Err(e);
                    }
                    opts.pretty_json = true;
                }
                "pretty-json-err" => {
                    if let Some(e) = dup(&mut seen, "--pretty-json-err") {
                        return CliResult::Err(e);
                    }
                    opts.pretty_json_err = true;
                }
                "no-warnings" => {
                    if let Some(e) = dup(&mut seen, "--no-warnings") {
                        return CliResult::Err(e);
                    }
                    opts.no_warnings = true;
                }
                _ => {
                    let value = match inline_val {
                        Some(v) => v.to_string(),
                        None => {
                            if i + 1 >= args.len() {
                                let possible = match name {
                                    "evm-version" => format!("  [possible values: {}]", EVM_VERSIONS.join(", ")),
                                    "stop-after" => format!("  [possible values: {}]", STAGES.join(", ")),
                                    "emit" => format!("  [possible values: {}]", EMITS.join(", ")),
                                    "color" => format!("  [possible values: {}]", COLORS.join(", ")),
                                    "error-format" => format!("  [possible values: {}]", ERROR_FORMATS.join(", ")),
                                    "error-format-human" => format!("  [possible values: {}]", HUMAN_STYLES.join(", ")),
                                    _ => String::new(),
                                };
                                let shown = match name {
                                    "threads" => "--threads <THREADS>",
                                    "jobs" => "--threads <THREADS>",
                                    "evm-version" => "--evm-version <EVM_VERSION>",
                                    "stop-after" => "--stop-after <STOP_AFTER>",
                                    "out-dir" => "--out-dir <OUT_DIR>",
                                    "emit" => "--emit <EMIT>",
                                    "base-path" => "--base-path <BASE_PATH>",
                                    "include-path" => "--include-path <INCLUDE_PATH>",
                                    "allow-paths" => "--allow-paths <ALLOW_PATHS>",
                                    "color" => "--color <COLOR>",
                                    "error-format" => "--error-format <ERROR_FORMAT>",
                                    "error-format-human" => "--error-format-human <VALUE>",
                                    "diagnostic-width" => "--diagnostic-width <WIDTH>",
                                    _ => "--unknown",
                                };
                                let mut msg =
                                    format!("a value is required for '{shown}' but none was supplied\n");
                                if !possible.is_empty() {
                                    msg.push_str(&possible);
                                    msg.push('\n');
                                }
                                return CliResult::Err(main_err_block(&msg, &prog, None, "For more information, try '--help'."));
                            }
                            i += 1;
                            args[i].clone()
                        }
                    };
                    match name {
                        "threads" | "jobs" => {
                            if let Some(e) = dup(&mut seen, "--threads <THREADS>") {
                                return CliResult::Err(e);
                            }
                            match value.parse::<usize>() {
                                Ok(v) => opts.threads = v,
                                Err(_) => {
                                    let msg = format!("invalid value '{value}' for '--threads <THREADS>': invalid digit found in string");
                                    return CliResult::Err(main_err_block(&msg, &prog, None, "For more information, try '--help'."));
                                }
                            }
                        }
                        "evm-version" => {
                            if let Some(e) = dup(&mut seen, "--evm-version <EVM_VERSION>") {
                                return CliResult::Err(e);
                            }
                            if let Some(v) = EVM_VERSIONS.iter().position(|s| *s == value) {
                                opts.evm_version = [EvmVersion::Homestead, EvmVersion::TangerineWhistle, EvmVersion::SpuriousDragon, EvmVersion::Byzantium, EvmVersion::Constantinople, EvmVersion::Petersburg, EvmVersion::Istanbul, EvmVersion::Berlin, EvmVersion::London, EvmVersion::Paris, EvmVersion::Shanghai, EvmVersion::Cancun, EvmVersion::Prague, EvmVersion::Osaka][v];
                            } else {
                                let msg = format!("invalid value '{value}' for '--evm-version <EVM_VERSION>'\n  [possible values: {}]", EVM_VERSIONS.join(", "));
                                return CliResult::Err(main_err_block(&msg, &prog, None, "For more information, try '--help'."));
                            }
                        }
                        "stop-after" => {
                            if let Some(e) = dup(&mut seen, "--stop-after <STOP_AFTER>") {
                                return CliResult::Err(e);
                            }
                            if let Some(v) = STAGES.iter().position(|s| *s == value) {
                                opts.stop_after = Some([Stage::Parsing, Stage::Lowering, Stage::Analysis][v]);
                            } else {
                                let msg = format!("invalid value '{value}' for '--stop-after <STOP_AFTER>'\n  [possible values: {}]", STAGES.join(", "));
                                return CliResult::Err(main_err_block(&msg, &prog, None, "For more information, try '--help'."));
                            }
                        }
                        "out-dir" => {
                            if let Some(e) = dup(&mut seen, "--out-dir <OUT_DIR>") {
                                return CliResult::Err(e);
                            }
                            opts.out_dir = Some(PathBuf::from(value));
                        }
                        "emit" => {
                            for part in value.split(',') {
                                match part {
                                    "abi" => opts.emit.push(Emit::Abi),
                                    "hashes" => opts.emit.push(Emit::Hashes),
                                    _ => {
                                        let msg = format!("invalid value '{part}' for '--emit <EMIT>'\n  [possible values: {}]", EMITS.join(", "));
                                        return CliResult::Err(main_err_block(&msg, &prog, None, "For more information, try '--help'."));
                                    }
                                }
                            }
                        }
                        "base-path" => {
                            if let Some(e) = dup(&mut seen, "--base-path <BASE_PATH>") {
                                return CliResult::Err(e);
                            }
                            opts.base_path = PathBuf::from(value);
                        }
                        "include-path" => opts.include_paths.push(PathBuf::from(value)),
                        "allow-paths" => {
                            for part in value.split(',') {
                                opts.allow_paths.push(PathBuf::from(part));
                            }
                        }
                        "color" => {
                            if let Some(e) = dup(&mut seen, "--color <COLOR>") {
                                return CliResult::Err(e);
                            }
                            opts.color = match value.as_str() {
                                "auto" => Color::Auto,
                                "always" => Color::Always,
                                "never" => Color::Never,
                                _ => {
                                    let msg = format!("invalid value '{value}' for '--color <COLOR>'\n  [possible values: {}]", COLORS.join(", "));
                                    return CliResult::Err(main_err_block(&msg, &prog, None, "For more information, try '--help'."));
                                }
                            };
                        }
                        "error-format" => {
                            if let Some(e) = dup(&mut seen, "--error-format <ERROR_FORMAT>") {
                                return CliResult::Err(e);
                            }
                            opts.error_format = match value.as_str() {
                                "human" => ErrorFormat::Human,
                                "json" => ErrorFormat::Json,
                                "rustc-json" => ErrorFormat::RustcJson,
                                _ => {
                                    let msg = format!("invalid value '{value}' for '--error-format <ERROR_FORMAT>'\n  [possible values: {}]", ERROR_FORMATS.join(", "));
                                    return CliResult::Err(main_err_block(&msg, &prog, None, "For more information, try '--help'."));
                                }
                            };
                        }
                        "error-format-human" => {
                            if let Some(e) = dup(&mut seen, "--error-format-human <VALUE>") {
                                return CliResult::Err(e);
                            }
                            opts.human_style = match value.as_str() {
                                "ascii" => HumanStyle::Ascii,
                                "unicode" => HumanStyle::Unicode,
                                "short" => HumanStyle::Short,
                                _ => {
                                    let msg = format!("invalid value '{value}' for '--error-format-human <VALUE>'\n  [possible values: {}]", HUMAN_STYLES.join(", "));
                                    return CliResult::Err(main_err_block(&msg, &prog, None, "For more information, try '--help'."));
                                }
                            };
                        }
                        "diagnostic-width" => {
                            if let Some(e) = dup(&mut seen, "--diagnostic-width <WIDTH>") {
                                return CliResult::Err(e);
                            }
                            match value.parse::<usize>() {
                                Ok(v) => opts.diagnostic_width = Some(v),
                                Err(_) => {
                                    let msg = format!("invalid value '{value}' for '--diagnostic-width <WIDTH>': invalid digit found in string");
                                    return CliResult::Err(main_err_block(&msg, &prog, None, "For more information, try '--help'."));
                                }
                            }
                        }
                        _ => {}
                    }
                }
            }
            i += 1;
            continue;
        }
        if a.starts_with('-') && a.len() > 1 && a != "-" {
            // short flags, possibly grouped, possibly with an attached value
            let chars: Vec<char> = a[1..].chars().collect();
            let mut k = 0usize;
            while k < chars.len() {
                match chars[k] {
                    'h' => return CliResult::Help(long_help(&prog)),
                    'V' => return CliResult::Version(short_version()),
                    'v' => {
                        if let Some(e) = dup(&mut seen, "--verbose") {
                            return CliResult::Err(e);
                        }
                        opts.verbose = true;
                        k += 1;
                    }
                    'Z' => {
                        let mut rest: String = chars[k + 1..].iter().collect();
                        if rest.is_empty() {
                            if i + 1 >= args.len() {
                                return CliResult::Err(main_err_block(
                                    "a value is required for '-Z <FLAG>' but none was supplied",
                                    &prog,
                                    None,
                                    "For more information, try '--help'.",
                                ));
                            }
                            i += 1;
                            rest = args[i].clone();
                        }
                        match handle_z(&rest) {
                            Ok(z) => {
                                apply_z(&mut opts, z, &rest);
                            }
                            Err(e) => {
                                let mut out = main_err_block(&e.msg, &prog, e.usage.as_deref(), "For more information, try '-Zhelp'.");
                                if !e.only_z {
                                    out.push_str(&main_err_block("", &prog, Some(&usage_line(&prog)), "For more information, try '--help'."));
                                }
                                return CliResult::Err(out);
                            }
                        }
                        k = chars.len();
                    }
                    'j' => {
                        let rest: String = chars[k + 1..].iter().collect();
                        let val = if rest.is_empty() {
                            if i + 1 >= args.len() {
                                return CliResult::Err(main_err_block("a value is required for '--threads <THREADS>' but none was supplied", &prog, None, "For more information, try '--help'."));
                            }
                            i += 1;
                            args[i].clone()
                        } else {
                            rest
                        };
                        if let Some(e) = dup(&mut seen, "--threads <THREADS>") {
                            return CliResult::Err(e);
                        }
                        match val.parse::<usize>() {
                            Ok(v) => opts.threads = v,
                            Err(_) => {
                                let msg = format!("invalid value '{val}' for '--threads <THREADS>': invalid digit found in string");
                                return CliResult::Err(main_err_block(&msg, &prog, None, "For more information, try '--help'."));
                            }
                        }
                        k = chars.len();
                    }
                    'I' => {
                        let rest: String = chars[k + 1..].iter().collect();
                        let val = if rest.is_empty() {
                            if i + 1 >= args.len() {
                                return CliResult::Err(main_err_block("a value is required for '--include-path <INCLUDE_PATH>' but none was supplied", &prog, None, "For more information, try '--help'."));
                            }
                            i += 1;
                            args[i].clone()
                        } else {
                            rest
                        };
                        opts.include_paths.push(PathBuf::from(val));
                        k = chars.len();
                    }
                    c => {
                        let msg = format!(
                            "unexpected argument '-{c}' found\n\n  tip: to pass '-{c}' as a value, use '-- -{c}'"
                        );
                        return CliResult::Err(main_err_block(&msg, &prog, Some(&usage_line(&prog)), "For more information, try '--help'."));
                    }
                }
            }
            i += 1;
            continue;
        }
        opts.inputs.push(a.clone());
        i += 1;
    }
    CliResult::Parsed(opts)
}

struct ZErr {
    msg: String,
    usage: Option<String>,
    only_z: bool,
}

fn handle_z(arg: &str) -> Result<(), ZErr> {
    let err = |msg: String, usage: Option<String>, only_z: bool| Err(ZErr { msg, usage, only_z });
    if arg == "help" {
        return Ok(());
    }
    let (name, value) = match arg.split_once('=') {
        Some((n, v)) => (n, Some(v)),
        None => (arg, None),
    };
    let known = Z_FLAGS.iter().any(|(n, _)| *n == name);
    if !known {
        return err(
            format!(" unexpected argument '-Z{name}' found"),
            Some(z_usage_line("z")),
            false,
        );
    }
    let needs_value = Z_FLAGS.iter().find(|(n, _)| *n == name).unwrap().1;
    match (needs_value, value) {
        (false, Some(v)) => err(
            format!(" unexpected value '{v}' for '-Z{name}' found; no more were expected"),
            Some(z_usage_line(&format!("-Z{name}"))),
            false,
        ),
        (true, None) => err(
            format!(" equal sign is needed when assigning values to '-Zdump=<KIND[=PATHS...]>'"),
            Some(z_usage_line("z")),
            false,
        ),
        _ => Ok(()),
    }
}

fn apply_z(opts: &mut Options, _res: (), arg: &str) {
    if arg == "help" {
        return;
    }
    let (name, value) = match arg.split_once('=') {
        Some((n, v)) => (n, Some(v)),
        None => (arg, None),
    };
    match name {
        "ui-testing" => opts.z.ui_testing = true,
        "track-diagnostics" => opts.z.track_diagnostics = true,
        "parse-yul" => opts.z.parse_yul = true,
        "no-resolve-imports" => opts.z.no_resolve_imports = true,
        "dump" => {
            let v = value.unwrap_or("");
            let (kind, _paths) = match v.split_once('=') {
                Some((k, p)) => (k, p),
                None => (v, ""),
            };
            match kind {
                "ast" => opts.z.dump_ast = true,
                "hir" => opts.z.dump_hir = true,
                _ => {}
            }
        }
        "ast-stats" => opts.z.ast_stats = true,
        "span-visitor" => opts.z.span_visitor = true,
        "print-max-storage-sizes" => opts.z.print_max_storage_sizes = true,
        "typeck" => opts.z.typeck = true,
        _ => {}
    }
}

pub fn z_dump_help_value_error(value: &str) -> String {
    main_err_block(
        &format!(" invalid value '{value}' for '-Zdump=<KIND[=PATHS...]>'"), 
        None,
        "For more information, try '-Zhelp'.",
    )
}
