pub fn z_help() -> String {
    let mut s = String::new();
    s.push_str("error: List of all unstable flags.\n");
    s.push_str("WARNING: these are completely unstable, and may change at any time!\n\n");
    s.push_str("Options:\n");
    let mut row = |name: &str, help: &str| {
        s.push_str(&format!("      {name}\n"));
        for line in help.lines() {
            s.push_str(&format!("          {line}\n"));
        }
        s.push('\n');
    };
    row("-Zui-testing", "Enables UI testing mode");
    row("-Ztrack-diagnostics", "Prints a note for every diagnostic that is emitted with the creation and emission location.\n\nThis is enabled by default on debug builds.");
    row("-Zparse-yul", "Enables parsing Yul files for testing");
    row("-Zno-resolve-imports", "Disables import resolution");
    row("-Zdump=<KIND[=PATHS...]>", "Print additional information about the compiler's internal state.\n\nValid kinds are `ast` and `hir`.");
    row("-Zast-stats", "Print AST stats");
    row("-Zspan-visitor", "Run the span visitor after parsing");
    row("-Zprint-max-storage-sizes", "Print contracts' max storage sizes");
