    row("-Zhelp", "Print help");
    s.push_str("Usage: solar [OPTIONS] [INPUT]...\n\n");
    s.push_str("For more information, try '--help'.\n");
    s
}

pub fn long_version() -> String {
    let mut s = String::new();
    s.push_str(&format!("{NAME} Version: {VERSION}\n"));
    s.push_str(&format!("Commit SHA: {COMMIT}\n"));
    s.push_str(&format!("Build Timestamp: {TIMESTAMP}\n"));
