/// Total display width of a string.
pub fn str_width(s: &str) -> usize {
    s.chars().map(char_width).sum()
}

/// Renders a character for diagnostics: control characters are replaced by
/// their control picture, tabs by spaces, etc.
pub fn render_char(c: char) -> String {
    let cp = c as u32;
    if cp == 0x09 {
        "    ".to_string()
    } else if cp < 0x20 || (0x7f..=0x9f).contains(&cp) {
        let mut buf = [0u8; 4];
        let picture = char::from_u32(0x2400 + cp).unwrap_or(c);
        buf[..] = [0u8; 4];
        let mut out = String::new();
        out.push(picture);
        out
    } else if cp == 0x7f {
        "\u{2407}".to_string()
    } else {
        c.to_string()
    }
}
