//! Solidity lexer.

use crate::span::{Span, char_width, render_char};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum TokenKind {
    Ident,
    Keyword,
    /// integer literal (possibly with a unit suffix)
    Integer,
    /// rational literal
    Rational,
    /// string literal
    Str,
    /// hex string literal
    HexStr,
    /// unicode string literal
    UnicodeStr,
    /// punctuation
    Punct,
    Eof,
}

#[derive(Clone, Debug)]
pub struct Token {
    pub span: Span,
    pub kind: TokenKind,
    /// for Ident / Keyword / Punct: the text
    pub text: String,
    /// decoded value for strings
    pub value: Option<String>,
}

impl Token {
    pub fn is_kw(&self, kw: &str) -> bool {
        self.kind == TokenKind::Keyword && self.text == kw
    }
    pub fn is_punct(&self, p: &str) -> bool {
        self.kind == TokenKind::Punct && self.text == p
    }
    /// The `found ...` description used in diagnostics.
    pub fn describe(&self) -> String {
        match self.kind {
            TokenKind::Eof => "`<eof>`".to_string(),
            TokenKind::Ident => format!("`{}`", self.text),
            TokenKind::Keyword => format!("keyword `{}`", self.text),
            TokenKind::Integer => "`<integer>`".to_string(),
            TokenKind::Rational => "`<rational>`".to_string(),
            TokenKind::Str => "`<string>`".to_string(),
            TokenKind::HexStr => "`<hex string>`".to_string(),
            TokenKind::UnicodeStr => "`<unicode string>`".to_string(),
            TokenKind::Punct => format!("`{}`", self.text),
        }
    }
}

