                    // merge with previous number literal
                    let mut last = self.tokens.pop().unwrap();
                    last.span.end = self.pos as u32;
                    self.tokens.push(last);
                    continue;
                }
                self.push(start, kind, text, None);
                continue;
            }
            // punctuation
            if let Some(p) = PUNCT3.iter().find(|p| self.starts_with(p)) {
                self.pos += 3;
                self.push(start, TokenKind::Punct, p.to_string(), None);
                continue;
            }
            if let Some(p) = PUNCT2.iter().find(|p| self.starts_with(p)) {
                self.pos += 2;
                self.push(start, TokenKind::Punct, p.to_string(), None);
                continue;
            }
            if b"(){}[],.;:=?+-*/%<>!&|^~".contains(&(c as u8)) {
                self.pos += 1;
                self.push(start, TokenKind::Punct, c.to_string(), None);
                continue;
            }
            // unknown token
            self.pos += c.len_utf8();
            let desc = describe_unknown_char(c);
            // coalesce repeated identical unknown tokens
            match last_unknown {
                Some((ch, s0, e0)) if ch == c => {
                    self.diags.pop();
                    let span = Span::new(self.file, s0, self.pos);
                    self.diags.push(LexDiag {
                        msg: desc.clone(),
                        span,
                        note: Some(("character repeats once more".to_string(), span)),
                        help: None,
                        is_warning: false,
                    });
                    last_unknown = None;
                }
                _ => {
                    self.diags.push(LexDiag {
                        msg: desc.clone(),
                        span: Span::new(self.file, start, self.pos),
                        note: None,
                        help: None,
                        is_warning: false,
                    });
                    last_unknown = Some((c, start, self.pos));
                }
            }
