                if digit_start.is_none() {
                    digit_start = Some(end);
                }
                count += 1;
                last_was_digit = true;
                end += 1;
            } else if ch == '_' {
                if count == 0 || !last_was_digit {
                    underscores.push(end);
                }
                underscores.push(end);
                last_was_digit = false;
                end += 1;
