                if !valid {
                    break;
                }
                saw_exp = true;
                end += 1;
                let mut prev_digit = false;
                while end < self.bytes.len() {
                    let ch2 = self.src[end..].chars().next().unwrap();
                    if ch2.is_ascii_digit() {
                        prev_digit = true;
                        end += 1;
                    } else if ch2 == '_' && prev_digit {
                        end += 1;
                        prev_digit = false;
                    } else {
                        break;
                    }
                }
                break;
            } else {
                break;
            }
        }
        self.pos = end;
        if count == 0 && !saw_dot {
            self.diags.push(LexDiag {
                msg: "no valid digits found for number".to_string(),
                span: Span::new(self.file, start, end),
                note: None,
                help: None,
                is_warning: false,
            });
        } else if count > 78 {
            self.diags.push(LexDiag {
                msg: "integer part too large".to_string(),
                span: Span::new(self.file, start, end),
                note: None,
                help: None,
                is_warning: false,
            });
        }
        // underscores must be between digits
        let mut bad_underscore = false;
        for (i, &u) in underscores.iter().enumerate() {
            let before = self.src[..u].chars().last();
            let after = self.src[u + 1..].chars().next();
            let ok = matches!(before, Some(c) if c.is_ascii_digit())
                && matches!(after, Some(c) if c.is_ascii_digit());
            if !ok {
                bad_underscore = true;
            }
            if i + 1 < underscores.len() && underscores[i + 1] == u + 1 {
                bad_underscore = true;
            }
        }
        let _ = bad_underscore;
        let text = self.src[start..end].to_string();
        let kind = if saw_dot || saw_exp {
            TokenKind::Rational
        } else {
            TokenKind::Integer
        };
        self.push(start, kind, text, None);
        // try to consume a unit suffix
        for u in UNITS {
            if self.starts_with(u) {
                let after = self.src[start + (end - start) + u.len()..].chars().next();
                let is_ident_like = match after {
                    Some(c) if c.is_ascii_alphanumeric() || c == '_' || c == '$' => true,
                    _ => false,
                };
                if !is_ident_like {
                    self.pos = start + (end - start) + u.len();
                    let mut last = self.tokens.pop().unwrap();
                    last.span.end = self.pos as u32;
                    self.tokens.push(last);
                    break;
                }
            }
        }
    }

    fn lex_string(&mut self, start: usize, is_unicode: bool, _raw: bool) {
        let quote = self.peek(0) as char;
        self.pos += 1;
        let mut value = String::new();
        let mut closed = false;
        let mut unicode_error: Option<(usize, usize)> = None;
        while !self.at_end() {
            let ch = self.src[self.pos..].chars().next().unwrap();
            if ch == '\n' {
                break;
            }
            if ch == '\r' {
                break;
            }
            if ch == quote {
                self.pos += 1;
                closed = true;
                break;
            }
            if ch == '\\' {
                let esc_start = self.pos;
                self.pos += 1;
                if self.at_end() {
                    break;
                }
                let e = self.src[self.pos..].chars().next().unwrap();
                match e {
                    'n' => {
                        value.push('\n');
                        self.pos += 1;
                    }
                    'r' => {
                        value.push('\r');
                        self.pos += 1;
                    }
                    't' => {
                        value.push('\t');
                        self.pos += 1;
                    }
                    'b' => {
                        value.push('\u{8}');
                        self.pos += 1;
                    }
                    'f' => {
                        value.push('\u{c}');
                        self.pos += 1;
                    }
                    'v' => {
                        value.push('\u{b}');
                        self.pos += 1;
                    }
                    '0' => {
                        value.push('\0');
                        self.pos += 1;
                    }
                    'a' => {
                        value.push('\u{7}');
                        self.pos += 1;
                    }
                    '\\' | '\'' | '"' => {
                        value.push(e);
                        self.pos += 1;
                    }
                    'x' => {
                        self.pos += 1;
                        let mut hex = String::new();
                        while let Some(c) = self.src[self.pos..].chars().next() {
                            if c.is_ascii_hexdigit() && hex.len() < 2 {
                                hex.push(c);
                                self.pos += 1;
                            } else {
                                break;
                            }
                        }
                        if hex.len() != 2 {
                            self.diags.push(LexDiag {
                                msg: "invalid hex escape".to_string(),
                                span: Span::new(self.file, esc_start, self.pos),
                                note: None,
                                help: None,
                                is_warning: false,
                            });
                            value.push('\u{0}');
                        } else {
                            let byte = u8::from_str_radix(&hex, 16).unwrap();
                            value.push(byte as char);
                        }
                    }
                    'u' => {
                        self.pos += 1;
                        let mut hex = String::new();
                        while let Some(c) = self.src[self.pos..].chars().next() {
                            if c.is_ascii_hexdigit() && hex.len() < 4 {
                                hex.push(c);
                                self.pos += 1;
                            } else {
                                break;
                            }
                        }
                        match u32::from_str_radix(&hex, 16).ok().and_then(char::from_u32) {
                            Some(c) if hex.len() == 4 => value.push(c),
                            _ => {
                                self.diags.push(LexDiag {
                                    msg: "invalid unicode escape".to_string(),
                                    span: Span::new(self.file, esc_start, self.pos),
                                    note: None,
                                    help: None,
                                    is_warning: false,
                                });
                            }
                        }
                    }
                    c2 => {
                        self.diags.push(LexDiag {
                            msg: "unknown character escape".to_string(),
                            span: Span::new(self.file, esc_start, self.pos + c2.len_utf8()),
                            note: None,
                            help: None,
                            is_warning: false,
                        });
                        value.push('\\');
                        value.push(c2);
                        self.pos += c2.len_utf8();
                    }
                }
                continue;
            }
            // regular character
            if char_width(ch) == 2 || (ch as u32) > 0x7f {
                if !is_unicode && unicode_error.is_none() {
                    unicode_error = Some((self.pos, self.pos + ch.len_utf8()));
                }
            }
            value.push(ch);
            self.pos += ch.len_utf8();
        }
        let end = self.pos;
        if !closed {
            self.diags.push(LexDiag {
                msg: "unterminated string".to_string(),
                span: Span::new(self.file, start, end),
                note: None,
                help: None,
                is_warning: false,
            });
            self.diags.push(LexDiag {
                msg: "unescaped newline".to_string(),
                span: Span::new(self.file, start, end),
                note: None,
                help: None,
                is_warning: false,
            });
            self.pos = end;
        }
        if let Some((s, e)) = unicode_error {
            self.diags.push(LexDiag {
                msg: "unicode characters are not allowed in string literals; use a `unicode\"...\"` literal instead".to_string(),
                span: Span::new(self.file, s, e),
                note: None,
                help: None,
                is_warning: false,
            });
        }
        let kind = if is_unicode {
            TokenKind::UnicodeStr
        } else {
            TokenKind::Str
        };
        let text = self.src[start..end].to_string();
        self.push(start, kind, text, Some(value));
    }

    fn lex_hex_string(&mut self, start: usize) {
        let quote = self.peek(0) as char;
        self.pos += 1;
        let mut value = String::new();
        let mut closed = false;
        while !self.at_end() {
            let ch = self.src[self.pos..].chars().next().unwrap();
            if ch == '\n' || ch == '\r' {
                break;
            }
            if ch == quote {
                self.pos += 1;
                closed = true;
                break;
            }
            if ch.is_ascii_hexdigit() {
                value.push(ch);
                self.pos += 1;
            } else {
                self.pos += ch.len_utf8();
            }
        }
        let end = self.pos;
        if !closed {
            self.diags.push(LexDiag {
                msg: "unterminated string".to_string(),
                span: Span::new(self.file, start, end),
                note: None,
                help: None,
                is_warning: false,
            });
        }
        let text = self.src[start..end].to_string();
        self.push(start, TokenKind::HexStr, text, Some(value));
    }
}

pub fn describe_unknown_char(c: char) -> String {
    let cp = c as u32;
    if cp < 0x20 || cp == 0x7f {
        format!("unknown start of token: \\u{{{:x}}}", cp)
    } else if (0x80..=0x10FFFF).contains(&cp) {
        format!("unknown start of token: \\u{{{:x}}}", cp)
    } else {
        format!("unknown start of token: {}", render_char(c))
    }
}
