//! Solidity lexer.

use crate::span::{Span, char_width, render_char};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum TokenKind {
    Ident,
    Keyword,
    /// integer literal (possibly with a unit suffix)
    Integer,
    /// rational literal
    Rational,
    /// string literal
    Str,
    /// hex string literal
    HexStr,
    /// unicode string literal
    UnicodeStr,
    /// punctuation
    Punct,
    Eof,
}

#[derive(Clone, Debug)]
pub struct Token {
    pub span: Span,
    pub kind: TokenKind,
    /// for Ident / Keyword / Punct: the text
    pub text: String,
    /// decoded value for strings
    pub value: Option<String>,
}

impl Token {
    pub fn is_kw(&self, kw: &str) -> bool {
        self.kind == TokenKind::Keyword && self.text == kw
    }
    pub fn is_punct(&self, p: &str) -> bool {
        self.kind == TokenKind::Punct && self.text == p
    }
    /// The `found ...` description used in diagnostics.
    pub fn describe(&self) -> String {
        match self.kind {
            TokenKind::Eof => "`<eof>`".to_string(),
            TokenKind::Ident => format!("`{}`", self.text),
            TokenKind::Keyword => format!("keyword `{}`", self.text),
            TokenKind::Integer => "`<integer>`".to_string(),
            TokenKind::Rational => "`<rational>`".to_string(),
            TokenKind::Str => "`<string>`".to_string(),
            TokenKind::HexStr => "`<hex string>`".to_string(),
            TokenKind::UnicodeStr => "`<unicode string>`".to_string(),
            TokenKind::Punct => format!("`{}`", self.text),
        }
    }
}

/// A doc comment attached to the following item.
#[derive(Clone, Debug)]
pub struct DocComment {
    pub span: Span,
    pub text: String,
}

pub struct Lexed {
    pub tokens: Vec<Token>,
    pub docs: Vec<(usize, Vec<DocComment>)>,
}

/// Known Solidity keywords. Everything else that matches an identifier is an
/// identifier.
const KEYWORDS: &[&str] = &[
    "abstract", "address", "after", "alias", "anonymous", "apply", "as", "assembly", "at", "auto",
    "bool", "break", "byte", "bytes", "calldata", "case", "catch", "constant", "constructor",
    "continue", "contract", "copyof", "default", "define", "delete", "do", "else", "emit", "enum",
    "error", "event", "external", "fallback", "false", "final", "fixed", "for", "from", "function",
    "global", "hex", "if", "immutable", "implements", "import", "in", "indexed", "inline",
    "interface", "internal", "is", "layout", "let", "library", "mapping", "match", "memory",
    "modifier", "mutable", "new", "null", "of", "override", "partial", "payable", "pragma",
    "private", "promise", "pure", "public", "receive", "reference", "relocatable", "return",
    "returns", "revert", "sealed", "sequential", "permanent", "static", "storage", "supports",
    "switch", "transient", "try", "true", "type", "typedef", "typeof", "unicode", "unchecked",
    "var", "view", "virtual", "while",
    // elementary type names
    "int", "uint", "bytes1", "bytes2", "bytes3", "bytes4", "bytes5", "bytes6", "bytes7", "bytes8",
    "bytes9", "bytes10", "bytes11", "bytes12", "bytes13", "bytes14", "bytes15", "bytes16",
    "bytes17", "bytes18", "bytes19", "bytes20", "bytes21", "bytes22", "bytes23", "bytes24",
    "bytes25", "bytes26", "bytes27", "bytes28", "bytes29", "bytes30", "bytes31", "bytes32",
    "int8", "int16", "int24", "int32", "int40", "int48", "int56", "int64", "int72", "int80",
    "int88", "int96", "int104", "int112", "int120", "int128", "int136", "int144", "int152",
    "int160", "int168", "int176", "int184", "int192", "int200", "int208", "int216", "int224",
    "int232", "int240", "int248", "int256",
    "uint8", "uint16", "uint24", "uint32", "uint40", "uint48", "uint56", "uint64", "uint72",
    "uint80", "uint88", "uint96", "uint104", "uint112", "uint120", "uint128", "uint136",
    "uint144", "uint152", "uint160", "uint168", "uint176", "uint184", "uint192", "uint200",
    "uint208", "uint216", "uint224", "uint232", "uint240", "uint248", "uint256",
    "ufixed128x18", "ufixed128x80", "ufixed256x18", "ufixed256x80", "ufixed8x0", "fixed128x18",
    "fixed128x80", "fixed256x18", "fixed256x80",
];

const UNITS: &[&str] = &[
    "wei", "gwei", "szabo", "finney", "ether", "seconds", "minutes", "hours", "days", "weeks",
    "years",
];

const PUNCT3: &[&str] = &["**=", ">>>="];
const PUNCT2: &[&str] = &[
    "**", "++", "--", "<<", ">>", "&&", "||", "==", "!=", "<=", ">=", "+=", "-=", "*=", "/=", "%=",
    "&=", "|=", "^=", "<<=", ">>=", "=>", "->", "?:",
];

pub struct Lexer<'a> {
    src: &'a str,
    bytes: &'a [u8],
    file: u32,
    pos: usize,
    pub tokens: Vec<Token>,
    pub docs: Vec<(usize, Vec<DocComment>)>,
    /// diagnostics produced while lexing, as (message, span) pairs plus extra flags
    pub diags: Vec<LexDiag>,
}

#[derive(Clone, Debug)]
pub struct LexDiag {
    pub msg: String,
    pub span: Span,
    pub note: Option<(String, Span)>,
    pub help: Option<(String, Span)>,
    pub is_warning: bool,
}

impl<'a> Lexer<'a> {
    pub fn new(src: &'a str, file: u32) -> Lexer<'a> {
        Lexer {
            src,
            bytes: src.as_bytes(),
            file,
            pos: 0,
            tokens: vec![],
            docs: vec![],
            diags: vec![],
        }
    }

    fn peek(&self, off: usize) -> u8 {
        *self.bytes.get(self.pos + off).unwrap_or(&0)
    }
    fn at_end(&self) -> bool {
        self.pos >= self.bytes.len()
    }
    fn rest(&self) -> &str {
        &self.src[self.pos..]
    }
    fn starts_with(&self, s: &str) -> bool {
        self.rest().starts_with(s)
    }
    fn push(&mut self, start: usize, kind: TokenKind, text: String, value: Option<String>) {
        let span = Span::new(self.file, start, self.pos);
        self.tokens.push(Token { span, kind, text, value });
    }

    /// Lexes the whole input.
    pub fn run(&mut self) {
        let mut pending_docs: Vec<DocComment> = vec![];
        let mut last_unknown: Option<(char, usize, usize)> = None;
        while !self.at_end() {
            let start = self.pos;
            let c = self.src[self.pos..].chars().next().unwrap();
            // whitespace
            if c.is_whitespace() && c != '\n' && !c.is_control() {
                self.pos += c.len_utf8();
                continue;
            }
            if c == '\n' {
                self.pos += 1;
                continue;
            }
            if c == '\r' && self.peek(1) == b'\n' {
                self.pos += 2;
                continue;
            }
            if c == '\r' {
                self.pos += 1;
                continue;
            }
            // line comment
            if self.starts_with("//") {
                let is_doc = self.starts_with("///");
                self.pos += 2;
                while !self.at_end() && self.peek(0) != b'\n' {
                    self.pos += 1;
                }
                let span = Span::new(self.file, start, self.pos);
                if is_doc {
                    let text = self.src[start + 3..self.pos].trim_end().to_string();
                    pending_docs.push(DocComment { span, text });
                }
                continue;
            }
            // block comment
            if self.starts_with("/*") {
                let is_doc = self.starts_with("/**") && !self.starts_with("/**/");
                self.pos += 2;
                let mut terminated = false;
                while !self.at_end() {
                    if self.peek(0) == b'*' && self.peek(1) == b'/' {
                        self.pos += 2;
                        terminated = true;
                        break;
                    }
                    self.pos += 1;
                }
                if !terminated {
                    self.diags.push(LexDiag {
                        msg: "unterminated comment".to_string(),
                        span: Span::new(self.file, start, self.bytes.len()),
                        note: None,
                        help: None,
                        is_warning: false,
                    });
                    self.pos = self.bytes.len();
                }
                let span = Span::new(self.file, start, self.pos);
                if is_doc {
                    let text = self.src[start..self.pos].to_string();
                    pending_docs.push(DocComment { span, text });
                }
                continue;
            }
            // string literal
            if c == '"' || c == '\'' {
                self.lex_string(start, false, false);
                continue;
            }
            if self.starts_with("hex\"") || self.starts_with("hex'") {
                self.pos += 3;
                self.lex_hex_string(start);
                continue;
            }
            if self.starts_with("unicode\"") || self.starts_with("unicode'") {
                self.pos += 7;
                self.lex_string(start, true, false);
                continue;
            }
            // numbers
            if c.is_ascii_digit() || (c == '.' && self.peek(1).is_ascii_digit()) {
                self.lex_number(start);
                continue;
            }
            // identifiers / keywords
            if c.is_ascii_alphabetic() || c == '_' || c == '$' {
                let mut end = self.pos;
                while end < self.bytes.len() {
                    let ch = self.src[end..].chars().next().unwrap();
                    if ch.is_ascii_alphanumeric() || ch == '_' || ch == '$' {
                        end += ch.len_utf8();
                    } else {
                        break;
                    }
                }
                let text = self.src[start..end].to_string();
                self.pos = end;
                let kind = if KEYWORDS.contains(&text.as_str()) {
                    TokenKind::Keyword
                } else {
                    TokenKind::Ident
                };
                // unit suffix for numbers: handled in lex_number
                if kind == TokenKind::Ident
                    && !self.tokens.is_empty()
                    && self.tokens.last().unwrap().kind == TokenKind::Integer
                    && UNITS.contains(&text.as_str())
                {
                    // merge with previous number literal
                    let mut last = self.tokens.pop().unwrap();
                    last.span.end = self.pos as u32;
                    self.tokens.push(last);
                    continue;
                }
                self.push(start, kind, text, None);
                continue;
            }
            // punctuation
            if let Some(p) = PUNCT3.iter().find(|p| self.starts_with(p)) {
                self.pos += 3;
                self.push(start, TokenKind::Punct, p.to_string(), None);
                continue;
            }
            if let Some(p) = PUNCT2.iter().find(|p| self.starts_with(p)) {
                self.pos += 2;
                self.push(start, TokenKind::Punct, p.to_string(), None);
                continue;
            }
            if b"(){}[],.;:=?+-*/%<>!&|^~".contains(&(c as u8)) {
                self.pos += 1;
                self.push(start, TokenKind::Punct, c.to_string(), None);
                continue;
            }
            // unknown token
            self.pos += c.len_utf8();
            let desc = describe_unknown_char(c);
            // coalesce repeated identical unknown tokens
            match last_unknown {
                Some((ch, s0, e0)) if ch == c => {
                    self.diags.pop();
                    let span = Span::new(self.file, s0, self.pos);
                    self.diags.push(LexDiag {
                        msg: desc.clone(),
                        span,
                        note: Some(("character repeats once more".to_string(), span)),
                        help: None,
                        is_warning: false,
                    });
                    last_unknown = None;
                }
                _ => {
                    self.diags.push(LexDiag {
                        msg: desc.clone(),
                        span: Span::new(self.file, start, self.pos),
                        note: None,
                        help: None,
                        is_warning: false,
                    });
                    last_unknown = Some((c, start, self.pos));
                }
            }
        }
        let end = self.bytes.len();
        self.tokens.push(Token {
            span: Span::new(self.file, end, end),
            kind: TokenKind::Eof,
            text: String::new(),
            value: None,
        });
        if !pending_docs.is_empty() {
            self.docs.push((self.tokens.len() - 1, pending_docs));
        }
    }

    fn lex_number(&mut self, start: usize) {
        let mut end = self.pos;
        let mut saw_dot = false;
        let mut saw_exp = false;
        let is_hex = self.peek(0) == b'0' && (self.peek(1) | 32) == b'x';
        if is_hex {
            end = start + 2;
            let mut digit_start: Option<usize> = None;
            let mut digit_count = 0usize;
            let mut cur = end;
            while cur < self.bytes.len() {
                let ch = self.src[cur..].chars().next().unwrap();
                if ch == '_' {
                    if cur == end {
                        cur += 1;
                        continue;
                    }
                    cur += 1;
                    continue;
                }
                if ch.is_ascii_hexdigit() {
                    if digit_start.is_none() {
                        digit_start = Some(cur);
                    }
                    digit_count += 1;
                    cur += 1;
                } else {
                    break;
                }
            }
            end = cur;
            self.pos = end;
            if digit_count == 0 {
                self.diags.push(LexDiag {
                    msg: "no valid digits found for number".to_string(),
                    span: Span::new(self.file, start, end),
                    note: None,
                    help: None,
                    is_warning: false,
                });
            } else if digit_count > 64 {
                self.diags.push(LexDiag {
                    msg: "integer part too large".to_string(),
                    span: Span::new(self.file, start, end),
                    note: None,
                    help: None,
                    is_warning: false,
                });
            }
            let text = self.src[start..end].to_string();
            self.push(start, TokenKind::Integer, text, None);
            return;
        }
        // decimal
        let mut digit_start: Option<usize> = None;
        let mut count = 0usize;
        let mut underscores: Vec<usize> = vec![];
        let mut last_was_digit = false;
        while end < self.bytes.len() {
            let ch = self.src[end..].chars().next().unwrap();
            if ch.is_ascii_digit() {
                if digit_start.is_none() {
                    digit_start = Some(end);
                }
                count += 1;
                last_was_digit = true;
                end += 1;
            } else if ch == '_' {
                if count == 0 || !last_was_digit {
                    underscores.push(end);
                }
                underscores.push(end);
                last_was_digit = false;
                end += 1;
            } else if ch == '.' && !saw_dot && !saw_exp {
                saw_dot = true;
                end += 1;
            } else if (ch == 'e' || ch == 'E') && !saw_exp {
                // exponent only if followed by a digit or sign+digits
                let nxt = self.src[end + 1..].chars().next();
                let valid = match nxt {
                    Some(d) if d.is_ascii_digit() => true,
                    Some(s @ ('+' | '-')) => {
                        let after = self.src[end + 1 + s.len_utf8()..].chars().next();
                        matches!(after, Some(d) if d.is_ascii_digit())
                    }
                    _ => false,
                };
                if !valid {
                    break;
                }
                saw_exp = true;
                end += 1;
                let mut prev_digit = false;
                while end < self.bytes.len() {
                    let ch2 = self.src[end..].chars().next().unwrap();
                    if ch2.is_ascii_digit() {
                        prev_digit = true;
                        end += 1;
                    } else if ch2 == '_' && prev_digit {
                        end += 1;
                        prev_digit = false;
                    } else {
                        break;
                    }
                }
                break;
            } else {
                break;
            }
        }
        self.pos = end;
        if count == 0 && !saw_dot {
            self.diags.push(LexDiag {
                msg: "no valid digits found for number".to_string(),
                span: Span::new(self.file, start, end),
                note: None,
                help: None,
                is_warning: false,
            });
        } else if count > 78 {
            self.diags.push(LexDiag {
                msg: "integer part too large".to_string(),
                span: Span::new(self.file, start, end),
                note: None,
                help: None,
                is_warning: false,
            });
        }
        // underscores must be between digits
        let mut bad_underscore = false;
        for (i, &u) in underscores.iter().enumerate() {
            let before = self.src[..u].chars().last();
            let after = self.src[u + 1..].chars().next();
            let ok = matches!(before, Some(c) if c.is_ascii_digit())
                && matches!(after, Some(c) if c.is_ascii_digit());
            if !ok {
                bad_underscore = true;
            }
            if i + 1 < underscores.len() && underscores[i + 1] == u + 1 {
                bad_underscore = true;
            }
        }
        let _ = bad_underscore;
        let text = self.src[start..end].to_string();
        let kind = if saw_dot || saw_exp {
            TokenKind::Rational
        } else {
            TokenKind::Integer
        };
        self.push(start, kind, text, None);
        // try to consume a unit suffix
        for u in UNITS {
            if self.starts_with(u) {
                let after = self.src[start + (end - start) + u.len()..].chars().next();
                let is_ident_like = match after {
                    Some(c) if c.is_ascii_alphanumeric() || c == '_' || c == '$' => true,
                    _ => false,
                };
                if !is_ident_like {
                    self.pos = start + (end - start) + u.len();
                    let mut last = self.tokens.pop().unwrap();
                    last.span.end = self.pos as u32;
                    self.tokens.push(last);
                    break;
                }
            }
        }
    }

    fn lex_string(&mut self, start: usize, is_unicode: bool, _raw: bool) {
        let quote = self.peek(0) as char;
        self.pos += 1;
        let mut value = String::new();
        let mut closed = false;
        let mut unicode_error: Option<(usize, usize)> = None;
        while !self.at_end() {
            let ch = self.src[self.pos..].chars().next().unwrap();
            if ch == '\n' {
                break;
            }
            if ch == '\r' {
                break;
            }
            if ch == quote {
                self.pos += 1;
                closed = true;
                break;
            }
            if ch == '\\' {
                let esc_start = self.pos;
                self.pos += 1;
                if self.at_end() {
                    break;
                }
                let e = self.src[self.pos..].chars().next().unwrap();
                match e {
                    'n' => {
                        value.push('\n');
                        self.pos += 1;
                    }
                    'r' => {
                        value.push('\r');
                        self.pos += 1;
                    }
                    't' => {
                        value.push('\t');
                        self.pos += 1;
                    }
                    'b' => {
                        value.push('\u{8}');
                        self.pos += 1;
                    }
                    'f' => {
                        value.push('\u{c}');
                        self.pos += 1;
                    }
                    'v' => {
                        value.push('\u{b}');
                        self.pos += 1;
                    }
                    '0' => {
                        value.push('\0');
                        self.pos += 1;
                    }
                    'a' => {
                        value.push('\u{7}');
                        self.pos += 1;
                    }
                    '\\' | '\'' | '"' => {
                        value.push(e);
                        self.pos += 1;
                    }
                    'x' => {
                        self.pos += 1;
                        let mut hex = String::new();
                        while let Some(c) = self.src[self.pos..].chars().next() {
                            if c.is_ascii_hexdigit() && hex.len() < 2 {
                                hex.push(c);
                                self.pos += 1;
                            } else {
                                break;
                            }
                        }
                        if hex.len() != 2 {
                            self.diags.push(LexDiag {
                                msg: "invalid hex escape".to_string(),
                                span: Span::new(self.file, esc_start, self.pos),
                                note: None,
                                help: None,
                                is_warning: false,
                            });
                            value.push('\u{0}');
                        } else {
                            let byte = u8::from_str_radix(&hex, 16).unwrap();
                            value.push(byte as char);
                        }
                    }
                    'u' => {
                        self.pos += 1;
                        let mut hex = String::new();
                        while let Some(c) = self.src[self.pos..].chars().next() {
                            if c.is_ascii_hexdigit() && hex.len() < 4 {
                                hex.push(c);
                                self.pos += 1;
                            } else {
                                break;
                            }
                        }
                        match u32::from_str_radix(&hex, 16).ok().and_then(char::from_u32) {
                            Some(c) if hex.len() == 4 => value.push(c),
                            _ => {
                                self.diags.push(LexDiag {
                                    msg: "invalid unicode escape".to_string(),
                                    span: Span::new(self.file, esc_start, self.pos),
                                    note: None,
                                    help: None,
                                    is_warning: false,
                                });
                            }
                        }
                    }
                    c2 => {
                        self.diags.push(LexDiag {
                            msg: "unknown character escape".to_string(),
                            span: Span::new(self.file, esc_start, self.pos + c2.len_utf8()),
                            note: None,
                            help: None,
                            is_warning: false,
                        });
                        value.push('\\');
                        value.push(c2);
                        self.pos += c2.len_utf8();
                    }
                }
                continue;
            }
            // regular character
            if char_width(ch) == 2 || (ch as u32) > 0x7f {
                if !is_unicode && unicode_error.is_none() {
                    unicode_error = Some((self.pos, self.pos + ch.len_utf8()));
                }
            }
            value.push(ch);
            self.pos += ch.len_utf8();
        }
        let end = self.pos;
        if !closed {
            self.diags.push(LexDiag {
                msg: "unterminated string".to_string(),
                span: Span::new(self.file, start, end),
                note: None,
                help: None,
                is_warning: false,
            });
            self.diags.push(LexDiag {
                msg: "unescaped newline".to_string(),
                span: Span::new(self.file, start, end),
                note: None,
                help: None,
                is_warning: false,
            });
            self.pos = end;
        }
        if let Some((s, e)) = unicode_error {
            self.diags.push(LexDiag {
                msg: "unicode characters are not allowed in string literals; use a `unicode\"...\"` literal instead".to_string(),
                span: Span::new(self.file, s, e),
                note: None,
                help: None,
                is_warning: false,
            });
        }
        let kind = if is_unicode {
            TokenKind::UnicodeStr
        } else {
            TokenKind::Str
        };
        let text = self.src[start..end].to_string();
        self.push(start, kind, text, Some(value));
    }

    fn lex_hex_string(&mut self, start: usize) {
        let quote = self.peek(0) as char;
        self.pos += 1;
        let mut value = String::new();
        let mut closed = false;
        while !self.at_end() {
            let ch = self.src[self.pos..].chars().next().unwrap();
            if ch == '\n' || ch == '\r' {
                break;
            }
            if ch == quote {
                self.pos += 1;
                closed = true;
                break;
            }
            if ch.is_ascii_hexdigit() {
                value.push(ch);
                self.pos += 1;
            } else {
                self.pos += ch.len_utf8();
            }
        }
        let end = self.pos;
        if !closed {
            self.diags.push(LexDiag {
                msg: "unterminated string".to_string(),
                span: Span::new(self.file, start, end),
                note: None,
                help: None,
                is_warning: false,
            });
        }
        let text = self.src[start..end].to_string();
        self.push(start, TokenKind::HexStr, text, Some(value));
    }
}

pub fn describe_unknown_char(c: char) -> String {
    let cp = c as u32;
    if cp < 0x20 || cp == 0x7f {
        format!("unknown start of token: \\u{{{:x}}}", cp)
    } else if (0x80..=0x10FFFF).contains(&cp) {
        format!("unknown start of token: \\u{{{:x}}}", cp)
    } else {
        format!("unknown start of token: {}", render_char(c))
    }
}
