//! Abstract syntax tree.

use crate::span::Span;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Visibility {
    Public,
    External,
    Internal,
    Private,
}

impl Visibility {
    pub fn as_str(self) -> &'static str {
        match self {
            Visibility::Public => "public",
            Visibility::External => "external",
            Visibility::Internal => "internal",
            Visibility::Private => "private",
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Mutability {
    Pure,
    View,
    Payable,
    Constant,
    Immutable,
    Transient,
}

impl Mutability {
    pub fn as_str(self) -> &'static str {
        match self {
            Mutability::Pure => "pure",
            Mutability::View => "view",
            Mutability::Payable => "payable",
            Mutability::Constant => "constant",
            Mutability::Immutable => "immutable",
            Mutability::Transient => "transient",
        }
    }
    pub fn is_state(self) -> bool {
        matches!(self, Mutability::Constant | Mutability::Immutable | Mutability::Transient)
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ContractKind {
    Contract,
    Interface,
    Library,
}

#[derive(Clone, Debug)]
pub struct Path {
    pub idents: Vec<(String, Span)>,
    pub span: Span,
}

impl Path {
    pub fn to_string(&self) -> String {
        self.idents.iter().map(|(s, _)| s.as_str()).collect::<Vec<_>>().join(".")
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ElementaryType {
    Address(bool),
    Bool,
    String,
    Bytes,
    Uint(u16),
    Int(u16),
    BytesN(u8),
    UFixed(u8, u8),
    Fixed(u8, u8),
}

#[derive(Clone, Debug)]
pub enum TypeKind {
    Elementary(ElementaryType),
    UserDefined(Path),
    Mapping(Box<Type>, Box<Type>),
    Array(Box<Type>, Option<Expr>),
    Function(Vec<Param>, Vec<Param>, Option<Visibility>, Option<Mutability>),
}

#[derive(Clone, Debug)]
pub struct Type {
    pub span: Span,
    pub kind: TypeKind,
}

#[derive(Clone, Debug)]
pub struct Param {
