    pub ty: Option<Type>,
    pub data_location: Option<Mutability>,
    pub visibility: Option<Visibility>,
    pub mutability: Option<Mutability>,
    pub indexed: bool,
    pub name: Option<(String, Span)>,
}

#[derive(Clone, Debug)]
pub struct FunctionHeader {
    pub span: Span,
    pub name: Option<(String, Span)>,
    pub params: Vec<Param>,
    pub returns: Vec<Param>,
    pub visibility: Option<Visibility>,
    pub mutability: Option<Mutability>,
    pub virtual_: bool,
    pub override_: Option<Vec<Path>>,
    pub modifiers: Vec<(Path, Option<Vec<Expr>>)>,
}

#[derive(Clone, Debug)]
pub enum Body {
    None,
    Block(Vec<Stmt>),
}

#[derive(Clone, Debug)]
pub enum ItemKind {
    Contract {
        kind: ContractKind,
        name: (String, Span),
        bases: Vec<InheritanceSpecifier>,
        layout: Option<Layout>,
        body: Vec<Item>,
    },
    Struct {
        name: (String, Span),
        members: Vec<Param>,
    },
    Enum {
        name: (String, Span),
        variants: Vec<(String, Span)>,
    },
    Error {
        name: (String, Span),
        params: Vec<Param>,
    },
    Event {
        name: (String, Span),
        params: Vec<Param>,
        anonymous: bool,
    },
    Function {
        kind: FunctionKind,
        header: FunctionHeader,
        body: Body,
    },
    VariableDefinition {
        span: Span,
        ty: Type,
        visibility: Option<Visibility>,
        mutability: Option<Mutability>,
        data_location: Option<Mutability>,
        override_: Option<Vec<Path>>,
        indexed: bool,
        name: Option<(String, Span)>,
        initializer: Option<Expr>,
    },
    UsingFor {
        library: Path,
        ty: Option<Type>,
        global: bool,
        fns: Option<Vec<Path>>,
    },
    Modifier {
        name: (String, Span),
        params: Vec<Param>,
        virtual_: bool,
        override_: Option<Vec<Path>>,
        body: Body,
