{"command": "cat > src/diag.rs <<'RSEOF'
//! Diagnostics.

use crate::span::Span;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Severity {
    Error,
    Warning,
    Note,
}

#[derive(Clone, Debug)]
pub struct SpanLabel {
    pub span: Span,
    pub label: Option<String>,
}

#[derive(Clone, Debug)]
pub struct Diag {
    pub severity: Severity,
    pub code: Option<&'static str>,
    pub message: String,
    pub primary: Option<SpanLabel>,
    pub secondary: Vec<SpanLabel>,
    pub notes: Vec<(String, Option<Span>)>,
    pub helps: Vec<(String, Option<Span>)>,
    /// children rendered as sub diagnostics (`note:` blocks)
    pub children: Vec<Diag>,
}

impl Diag {
    pub fn error(message: impl Into<String>) -> Diag {
        Diag {
            severity: Severity::Error,
            code: None,
            message: message.into(),
            primary: None,
            secondary: vec![],
            notes: vec![],
            helps: vec![],
            children: vec![],
        }
    }
    pub fn warning(message: impl Into<String>) -> Diag {
        let mut d = Diag::error(message);
        d.severity = Severity::Warning;
        d
    }
    pub fn with_span(mut self, span: Span) -> Diag {
        self.primary = Some(SpanLabel { span, label: None });
        self
    }
    pub fn with_label(mut self, span: Span, label: impl Into<String>) -> Diag {
        self.primary = Some(SpanLabel { span, label: Some(label.into()) });
        self
    }
    pub fn with_secondary(mut self, span: Span, label: impl Into<String>) -> Diag {
        self.secondary.push(SpanLabel { span, label: Some(label.into()) });
