    0x000000000000808b, 0x0000000080000001, 0x8000000080008081, 0x8000000000008009,
    0x000000000000008a, 0x0000000000000088, 0x0000000080008009, 0x000000008000000a,
    0x000000008000808b, 0x800000000000008b, 0x8000000000008089, 0x8000000000008003,
    0x8000000000008002, 0x8000000000000080, 0x000000000000800a, 0x800000008000000a,
    0x8000000080008081, 0x8000000000008080, 0x0000000080000001, 0x8000000080008008,
];

const ROTC: [u32; 24] = [
    1, 3, 6, 10, 15, 21, 28, 36, 45, 55, 2, 14, 27, 41, 56, 8, 25, 43, 62, 18, 39, 61, 20, 44,
];

const PILN: [usize; 24] = [
    10, 7, 11, 17, 18, 3, 5, 16, 8, 21, 24, 4, 15, 23, 19, 13, 12, 2, 20, 14, 22, 9, 6, 1,
];

fn rotl64(x: u64, n: u32) -> u64 {
    x.rotate_left(n)
}

pub fn keccak256(data: &[u8]) -> [u8; 32] {
    let mut st = [0u64; 25];
    let rate = 136usize;
    let mut padded = Vec::with_capacity(data.len() + rate);
    padded.extend_from_slice(data);
    let rem = data.len() % rate;
    let padlen = rate - rem;
    if padlen == 1 {
        padded.push(0x81);
    } else {
        padded.push(0x01);
        for _ in 1..padlen - 1 {
            padded.push(0);
        }
        padded.push(0x81);
    }
    for block in padded.chunks(rate) {
        for (i, c) in block.chunks(8).enumerate() {
            let mut v = [0u8; 8];
            v[..c.len()].copy_from_slice(c);
            st[i] ^= u64::from_le_bytes(v);
        }
        keccakf(&mut st);
    }
    let mut out = [0u8; 32];
    for i in 0..4 {
        out[i * 8..i * 8 + 8].copy_from_slice(&st[i].to_le_bytes());
    }
    out
}

fn keccakf(st: &mut [u64; 25]) {
    let mut bc = [0u64; 5];
    for round in 0..24 {
        for i in 0..5 {
            bc[i] = st[i] ^ st[i + 5] ^ st[i + 10] ^ st[i + 15] ^ st[i + 20];
        }
        for i in 0..5 {
            let t = bc[(i + 4) % 5] ^ rotl64(bc[(i + 1) % 5], 1);
            for j in 0..5 {
                st[i + 5 * j] ^= t;
            }
        }
        let mut t = st[1];
        for i in 0..24 {
            let j = PILN[i];
            bc[0] = st[j];
            st[j] = rotl64(t, ROTC[i]);
            t = bc[0];
        }
        for j in 0..5 {
            for i in 0..5 {
                st[i + 5 * j] ^= RC[round] & ((!bc[(j + 1) % 5] + 1) & bc[(j + 2) % 5]);
            }
        }
        bc[0] = 0;
    }
}

pub fn selector(signature: &str) -> [u8; 4] {
    let h = keccak256(signature.as_bytes());
    [h[0], h[1], h[2], h[3]]
}

pub fn hex32(data: &[u8]) -> String {
    let mut s = String::with_capacity(data.len() * 2);
    for b in data {
        s.push_str(&format!("{:02x}", b));
    }
    s
}

pub fn hex4(data: &[u8]) -> String {
    hex32(&data[..4.min(data.len())])
}
RSEOF
echo ok"}

