{"command": "cat > src/parser.rs <<'RSEOF'
//! Solidity parser.

use crate::ast::*;
use crate::diag::Diag;
use crate::lexer::{DocComment, LexDiag, Lexer, Token, TokenKind};
use crate::span::{DUMMY, Span};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Exp {
    Tok(&'static str),
    Desc(&'static str),
}

const TOK_EOF: Exp = Exp::Desc("<eof>");
const TOK_IDENT: Exp = Exp::Desc("identifier");
const TOK_ELEMENTARY: Exp = Exp::Desc("elementary type name");
const TOK_LITERAL: Exp = Exp::Desc("literal");
const TOK_PATH: Exp = Exp::Desc("path");
const TOK_STRLIT: Exp = Exp::Desc("string literal");

pub struct Parser {
    pub toks: Vec<Token>,
    pos: usize,
    pub file: u32,
    pub diags: Vec<Diag>,
    pub docs: Vec<(usize, Vec<DocComment>)>,
    panic_depth: usize,
    in_contract: bool,
    contract_depth: usize,
}

fn elementary_expected() -> Vec<Exp> {
    vec![Exp::Tok("("), Exp::Tok("+"), Exp::Tok("["), Exp::Tok("delete"), Exp::Tok("new"), Exp::Tok("payable"), Exp::Tok("type"), TOK_ELEMENTARY, TOK_IDENT, TOK_LITERAL]
}

impl Parser {
    pub fn new(mut lexer: Lexer) -> Parser {
        let docs = std::mem::take(&mut lexer.docs);
        Parser {
            toks: lexer.tokens,
            pos: 0,
            file: lexer.file,
            diags: vec![],
            docs,
            panic_depth: 0,
            in_contract: false,
            contract_depth: 0,
        }
    }

    pub fn from_tokens(toks: Vec<Token>, file: u32) -> Parser {
        Parser {
            toks,
            pos: 0,
            file,
            diags: vec![],
            docs: vec![],
            panic_depth: 0,
            in_contract: false,
            contract_depth: 0,
        }
    }

    fn cur(&self) -> &Token {
        &self.toks[self.pos.min(self.toks.len() - 1)]
    }
    fn peek(&self, n: usize) -> &Token {
        &self.toks[(self.pos + n).min(self.toks.len() - 1)]
    }
    fn span(&self) -> Span {
        self.cur().span
    }
    fn prev_span(&self) -> Span {
        if self.pos == 0 {
            self.toks[0].span
        } else {
            self.toks[self.pos - 1].span
        }
    }
    fn bump(&mut self) {
        if self.pos + 1 < self.toks.len() {
            self.pos += 1;
        }
    }
    fn at_eof(&self) -> bool {
        self.cur().kind == TokenKind::Eof
    }
    fn at_kw(&self, kw: &str) -> bool {
        self.cur().is_kw(kw)
    }
    fn at_punct(&self, p: &str) -> bool {
        self.cur().is_punct(p)
    }
    fn eat_kw(&mut self, kw: &str) -> bool {
        if self.at_kw(kw) {
            self.bump();
            true
        } else {
            false
        }
    }
    fn eat_punct(&mut self, p: &str) -> bool {
        if self.at_punct(p) {
            self.bump();
            true
        } else {
            false
        }
    }
    fn eat(&mut self) -> Token {
        let t = self.cur().clone();
        self.bump();
        t
    }

    fn is_elementary_kw(&self, t: &Token) -> bool {
        if t.kind != TokenKind::Keyword {
            return false;
        }
        matches!(
            t.text.as_str(),
            "address" | "bool" | "string" | "bytes" | "int" | "uint" | "fixed" | "ufixed" | "byte"
        ) || t.text.starts_with("uint")
            && t.text != "uint"
            && t.text[4..].chars().all(|c| c.is_ascii_digit())
            || t.text.starts_with("int")
                && t.text != "int"
                && t.text[3..].chars().all(|c| c.is_ascii_digit())
            || t.text.starts_with("bytes")
                && t.text != "bytes"
                && t.text[5..].chars().all(|c| c.is_ascii_digit())
    }

    fn expected(&mut self, exp: Exp) {
        let found = self.cur().describe();
        let text = match exp {
            Exp::Tok(t) => format!("expected `{t}`"),
            Exp::Desc(d) => format!("expected {d}"),
        };
        self.emit(format!("{text}, found {found}"));
    }

    fn expected_one_of(&mut self, items: &[Exp]) {
        if items.is_empty() {
            return;
        }
        let found = self.cur().describe();
        let parts: Vec<String> = items
            .iter()
            .map(|it| match it {
                Exp::Tok(t) => format!("`{t}`"),
                Exp::Desc(d) => d.to_string(),
            })
            .collect();
        let head = if parts.len() == 1 {
            format!("expected {}", parts[0])
        } else if parts.len() == 2 {
            format!("expected one of {} or {}", parts[0], parts[1])
        } else {
            format!(
                "expected one of {}, or {}",
                parts[..parts.len() - 1].join(", "),
                parts[parts.len() - 1]
            )
        };
        let label = if parts.len() > 6 {
            format!("expected one of {} possible tokens", parts.len())
        } else {
            format!("{head}, found {found}")
        };
        self.emit_with_label(format!("{head}, found {found}"), label);
    }

    fn emit(&mut self, msg: String) {
        let span = self.span();
        self.diags.push(Diag::error(msg).with_span(span));
    }

    fn emit_span(&mut self, msg: String, span: Span) {
        self.diags.push(Diag::error(msg).with_span(span));
    }

    fn emit_with_label(&mut self, msg: String, label: String) {
        let span = self.span();
        self.diags
            .push(Diag::error(msg).with_label(span, label));
    }

    fn emit_note(&mut self, msg: String, note: &str, span: Span) {
        self.diags
            .push(Diag::error(msg).with_span(span).with_note(note.to_string()));
    }

    /// Reports an error and skips tokens until one of the sync points.
    fn bail(&mut self, msg: String, sync: &[&str]) {
        self.emit(msg);
        while !self.at_eof() {
            let t = self.cur().text.clone();
            let k = self.cur().kind;
            if k == TokenKind::Punct && sync.contains(&t.as_str()) {
                return;
            }
            self.bump();
        }
    }

    // --------------------------------------------------------------------
    // types

    fn is_type_start(&self) -> bool {
        let t = self.cur();
        match t.kind {
            TokenKind::Keyword => {
                matches!(t.text.as_str(), "mapping" | "function") || self.is_elementary_kw(t)
            }
            TokenKind::Ident => true,
            _ => false,
        }
    }

    fn parse_type(&mut self) -> Type {
        let start = self.span();
        let kind = self.parse_type_kind();
        let mut ty = Type { span: start, kind };
        // array suffixes
        while self.at_punct("[") {
            self.bump();
            let size = if self.at_punct("]") {
                None
            } else {
                Some(self.parse_expr())
            };
            if !self.eat_punct("]") {
                self.expected_one_of(&[Exp::Tok("]")]);
            }
            let end = self.prev_span();
            ty.span = ty.span.join(end);
            ty = Type {
                span: start.join(end),
                kind: TypeKind::Array(Box::new(ty), size),
            };
        }
        ty
    }

    fn parse_type_kind(&mut self) -> TypeKind {
        let t = self.cur().clone();
        if t.is_kw("mapping") {
            self.bump();
            if !self.eat_punct("(") {
                self.expected(Exp::Tok("("));
            }
            let key = self.parse_mapping_key_type();
            if !self.eat_punct("=>") {
                self.expected_one_of(&[Exp::Tok("=>"), Exp::Tok("["), Exp::Tok("payable"), Exp::Tok("pure"), Exp::Tok("view"), TOK_IDENT]);
            }
            let value = self.parse_mapping_value_type();
            if !self.eat_punct(")") {
                self.expected(Exp::Tok(")"));
            }
            return TypeKind::Mapping(Box::new(key), Box::new(value));
        }
        if t.is_kw("function") {
            self.bump();
            let params = if self.at_punct("(") {
                self.parse_param_list(false)
            } else {
                self.expected(Exp::Tok("("));
                vec![]
            };
            let mut visibility = None;
            let mut mutability = None;
            let mut returns: Vec<Param> = vec![];
            loop {
                if self.at_kw("returns") {
                    self.bump();
                    returns = self.parse_param_list(true);
                    continue;
                }
                if self.at_kw("external") {
                    self.bump();
                    visibility = Some(Visibility::External);
                    continue;
                }
                if self.at_kw("internal") {
                    self.bump();
                    visibility = Some(Visibility::Internal);
                    continue;
                }
                if self.at_kw("pure") {
                    self.bump();
                    mutability = Some(Mutability::Pure);
                    continue;
                }
                if self.at_kw("view") {
                    self.bump();
                    mutability = Some(Mutability::View);
                    continue;
                }
                if self.at_kw("payable") {
                    self.bump();
                    mutability = Some(Mutability::Payable);
                    continue;
                }
                break;
            }
            return TypeKind::Function(params, returns, visibility, mutability);
        }
        if t.kind == TokenKind::Keyword && self.is_elementary_kw(&t) {
            self.bump();
            return TypeKind::Elementary(elementary_of(&t.text));
        }
        if t.kind == TokenKind::Ident {
            let path = self.parse_path();
            return TypeKind::UserDefined(path);
        }
        self.expected_one_of(&[Exp::Tok("mapping"), Exp::Tok("function"), TOK_ELEMENTARY, TOK_PATH]);
        TypeKind::Elementary(ElementaryType::Bool)
    }

    fn parse_mapping_key_type(&mut self) -> Type {
        let t = self.cur().clone();
        let start = self.span();
        if t.is_kw("mapping") || t.is_kw("function") || t.kind == TokenKind::Ident {
            return self.parse_type();
        }
        if t.kind == TokenKind::Keyword && self.is_elementary_kw(&t) {
            self.bump();
            return Type {
                span: start,
                kind: TypeKind::Elementary(elementary_of(&t.text)),
            };
        }
        self.expected_one_of(&[Exp::Tok("mapping"), Exp::Tok("function"), TOK_ELEMENTARY, TOK_PATH]);
        Type { span: start, kind: TypeKind::Elementary(ElementaryType::Bool) }
    }

    fn parse_mapping_value_type(&mut self) -> Type {
        let mut ty = self.parse_type();
        // value types may have a data location / mutability
        loop {
            if self.at_kw("calldata")
                || self.at_kw("memory")
                || self.at_kw("storage")
                || self.at_kw("immutable")
                || self.at_kw("transient")
                || self.at_kw("payable")
                || self.at_kw("pure")
                || self.at_kw("view")
            {
                self.bump();
                continue;
            }
            if self.at_punct("[") {
                self.bump();
                let size = if self.at_punct("]") { None } else { Some(self.parse_expr()) };
                if !self.eat_punct("]") {
                    self.expected_one_of(&[Exp::Tok("]")]);
                }
                let end = self.prev_span();
                ty = Type {
                    span: ty.span.join(end),
                    kind: TypeKind::Array(Box::new(ty), size),
                };
                continue;
            }
            break;
        }
        ty
    }

    fn parse_path(&mut self) -> Path {
        let start = self.span();
        let mut idents = vec![];
        let t = self.eat();
        idents.push((t.text.clone(), t.span));
        let mut span = t.span;
        while self.at_punct(".") && matches!(self.peek(1).kind, TokenKind::Ident) {
            self.bump();
            let t2 = self.eat();
            span = span.join(t2.span);
            idents.push((t2.text.clone(), t2.span));
        }
        Path { idents, span }
    }

    // --------------------------------------------------------------------
    // parameter lists

    fn parse_param_list(&mut self, allow_indexed: bool) -> Vec<Param> {
        if !self.eat_punct("(") {
            self.expected(Exp::Tok("("));
            return vec![];
        }
        let mut params: Vec<Param> = vec![];
        if self.eat_punct(")") {
            return params;
        }
        loop {
            params.push(self.parse_param(allow_indexed));
            if self.eat_punct(",") {
                continue;
            }
            if self.eat_punct(")") {
                break;
            }
            let items = vec![
                Exp::Tok(")"),
                Exp::Tok(","),
                Exp::Tok("["),
                Exp::Tok("calldata"),
                Exp::Tok("constant"),
                Exp::Tok("external"),
                Exp::Tok("immutable"),
                Exp::Tok("indexed"),
                Exp::Tok("internal"),
                Exp::Tok("memory"),
                Exp::Tok("override"),
                Exp::Tok("payable"),
                Exp::Tok("private"),
                Exp::Tok("public"),
                Exp::Tok("pure"),
                Exp::Tok("storage"),
                Exp::Tok("transient"),
                Exp::Tok("view"),
                Exp::Tok("virtual"),
                TOK_IDENT,
            ];
            self.expected_one_of(&items);
            break;
        }
        params
    }

    fn parse_param(&mut self, allow_indexed: bool) -> Param {
        let start = self.span();
        let mut param = Param {
            span: start,
            ty: None,
            data_location: None,
            visibility: None,
            mutability: None,
            indexed: false,
            name: None,
        };
        // modifiers before the type
        if self.at_punct("[") {
            // error recovery: skip to something reasonable
            let items = vec![Exp::Tok(")"), Exp::Tok(",")];
            self.expected_one_of(&items);
            return param;
        }
        if !self.is_type_start() {
            let items = vec![Exp::Tok("("), Exp::Tok("["), Exp::Tok("mapping"), Exp::Tok("function"), Exp::Tok("payable"), TOK_ELEMENTARY, TOK_IDENT];
            self.expected_one_of(&items);
            return param;
        }
        let ty = self.parse_type();
        param.ty = Some(ty);
        loop {
            if self.at_kw("memory") {
                self.bump();
                param.data_location = Some(Mutability::Immutable);
                continue;
            }
            if self.at_kw("calldata") {
                self.bump();
                param.data_location = Some(Mutability::Immutable);
                continue;
            }
            if self.at_kw("storage") {
                self.bump();
                param.data_location = Some(Mutability::Immutable);
                continue;
            }
            if self.at_kw("indexed") {
                if allow_indexed {
                    self.bump();
                    param.indexed = true;
                    continue;
                }
                break;
            }
            if self.at_kw("payable") || self.at_kw("pure") || self.at_kw("view") {
                self.bump();
                continue;
            }
            if self.at_kw("public") || self.at_kw("external") || self.at_kw("internal") || self.at_kw("private") {
                self.bump();
                continue;
            }
            if self.at_kw("constant") || self.at_kw("immutable") || self.at_kw("transient") {
                self.bump();
                continue;
            }
            break;
        }
        if matches!(self.cur().kind, TokenKind::Ident) {
            let t = self.eat();
            param.name = Some((t.text.clone(), t.span));
        }
        param.span = start.join(self.prev_span());
        param
    }
}
RSEOF
echo ok"}

