            break;
        }
        ty
    }

    fn parse_path(&mut self) -> Path {
        let start = self.span();
        let mut idents = vec![];
        let t = self.eat();
        idents.push((t.text.clone(), t.span));
        let mut span = t.span;
        while self.at_punct(".") && matches!(self.peek(1).kind, TokenKind::Ident) {
            self.bump();
            let t2 = self.eat();
            span = span.join(t2.span);
            idents.push((t2.text.clone(), t2.span));
        }
        Path { idents, span }
    }

    // --------------------------------------------------------------------
    // parameter lists

    fn parse_param_list(&mut self, allow_indexed: bool) -> Vec<Param> {
        if !self.eat_punct("(") {
            self.expected(Exp::Tok("("));
            return vec![];
        }
        let mut params: Vec<Param> = vec![];
        if self.eat_punct(")") {
            return params;
        }
        loop {
            params.push(self.parse_param(allow_indexed));
            if self.eat_punct(",") {
                continue;
            }
            if self.eat_punct(")") {
                break;
            }
            let items = vec![
                Exp::Tok(")"),
                Exp::Tok(","),
                Exp::Tok("["),
                Exp::Tok("calldata"),
                Exp::Tok("constant"),
                Exp::Tok("external"),
                Exp::Tok("immutable"),
                Exp::Tok("indexed"),
                Exp::Tok("internal"),
                Exp::Tok("memory"),
                Exp::Tok("override"),
                Exp::Tok("payable"),
                Exp::Tok("private"),
                Exp::Tok("public"),
                Exp::Tok("pure"),
                Exp::Tok("storage"),
                Exp::Tok("transient"),
                Exp::Tok("view"),
                Exp::Tok("virtual"),
                TOK_IDENT,
            ];
            self.expected_one_of(&items);
            break;
        }
        params
    }

    fn parse_param(&mut self, allow_indexed: bool) -> Param {
        let start = self.span();
        let mut param = Param {
            span: start,
            ty: None,
            data_location: None,
            visibility: None,
            mutability: None,
            indexed: false,
            name: None,
        };
        // modifiers before the type
        if self.at_punct("[") {
            // error recovery: skip to something reasonable
            let items = vec![Exp::Tok(")"), Exp::Tok(",")];
            self.expected_one_of(&items);
            return param;
        }
        if !self.is_type_start() {
            let items = vec![Exp::Tok("("), Exp::Tok("["), Exp::Tok("mapping"), Exp::Tok("function"), Exp::Tok("payable"), TOK_ELEMENTARY, TOK_IDENT];
            self.expected_one_of(&items);
            return param;
        }
        let ty = self.parse_type();
        param.ty = Some(ty);
        loop {
            if self.at_kw("memory") {
                self.bump();
                param.data_location = Some(Mutability::Immutable);
                continue;
            }
            if self.at_kw("calldata") {
                self.bump();
                param.data_location = Some(Mutability::Immutable);
                continue;
            }
            if self.at_kw("storage") {
                self.bump();
                param.data_location = Some(Mutability::Immutable);
                continue;
            }
            if self.at_kw("indexed") {
                if allow_indexed {
                    self.bump();
                    param.indexed = true;
                    continue;
                }
                break;
            }
            if self.at_kw("payable") || self.at_kw("pure") || self.at_kw("view") {
                self.bump();
                continue;
            }
            if self.at_kw("public") || self.at_kw("external") || self.at_kw("internal") || self.at_kw("private") {
                self.bump();
                continue;
            }
            if self.at_kw("constant") || self.at_kw("immutable") || self.at_kw("transient") {
                self.bump();
                continue;
            }
            break;
        }
        if matches!(self.cur().kind, TokenKind::Ident) {
            let t = self.eat();
            param.name = Some((t.text.clone(), t.span));
        }
        param.span = start.join(self.prev_span());
        param
    }
}
