                items.push(self.parse_pragma(t.span));
                continue;
            }
            if t.is_kw("import") {
                self.bump();
                items.push(self.parse_import(t.span));
                continue;
            }
            if t.is_kw("contract") || t.is_kw("interface") || t.is_kw("library") || t.is_kw("abstract")
            {
                let kind = if t.is_kw("interface") {
                    ContractKind::Interface
                } else if t.is_kw("library") {
                    ContractKind::Library
                } else {
                    ContractKind::Contract
                };
                let docs = self.take_docs();
