impl Parser {
    // --------------------------------------------------------------------
    // top level

    pub fn parse(&mut self) -> SourceUnit {
        let start = self.span();
        let mut items = vec![];
        loop {
            if self.at_eof() {
                break;
            }
            let t = self.cur().clone();
            if t.is_kw("pragma") {
                self.bump();
                items.push(self.parse_pragma(t.span));
                continue;
            }
            if t.is_kw("import") {
                self.bump();
                items.push(self.parse_import(t.span));
                continue;
            }
            if t.is_kw("contract") || t.is_kw("interface") || t.is_kw("library") || t.is_kw("abstract")
            {
                let kind = if t.is_kw("interface") {
                    ContractKind::Interface
                } else if t.is_kw("library") {
                    ContractKind::Library
                } else {
                    ContractKind::Contract
                };
                let docs = self.take_docs();
                self.bump();
                let mut abstract_ = t.is_kw("abstract");
                if abstract_ {
                    if !self.eat_kw("contract") {
                        self.expected(Exp::Desc("contract"));
                    }
                }
                items.push(SourceUnitItem::Contract(self.parse_contract(kind, abstract_, docs)));
                continue;
            }
            if t.is_kw("struct") {
                self.bump();
                items.push(SourceUnitItem::Struct(self.parse_struct()));
                continue;
            }
            if t.is_kw("enum") {
                self.bump();
                items.push(SourceUnitItem::Enum(self.parse_enum()));
                continue;
            }
            if t.is_kw("error") {
                self.bump();
                items.push(SourceUnitItem::Error(self.parse_error_def()));
                continue;
            }
            if t.is_kw("using") {
                self.bump();
                items.push(SourceUnitItem::UsingFor(self.parse_using_for()));
                continue;
            }
            if t.is_kw("function") {
                self.bump();
                items.push(SourceUnitItem::Function(self.parse_function(FunctionKind::Free)));
                continue;
            }
            if self.is_type_start() {
                let docs = self.take_docs();
                let item = self.parse_state_variable(docs, None);
                if let ItemKind::VariableDefinition { .. } = item.kind {
                    items.push(SourceUnitItem::Variable(item));
                }
                continue;
            }
            let msg = "expected global item (pragma, import directive, contract, interface, library, struct, enum, constant, function, modifier, or error definition)".to_string();
            let found = self.cur().describe();
            let mut d = Diag::error(format!("{msg}, found {found}"));
            d.primary = Some(crate::diag::SpanLabel { span: self.cur().span, label: None });
            d.notes.push(("for a full list of valid global items, see <https://docs.soliditylang.org/en/latest/grammar.html>".to_string(), None));
            self.diags.push(d);
            break;
        }
        let end = if items.is_empty() { start } else { self.prev_span() };
        SourceUnit { span: start.join(end), items }
    }

    fn take_docs(&mut self) -> Vec<DocComment> {
        let mut out = vec![];
        let idx = self.pos;
        for (i, docs) in std::mem::take(&mut self.docs) {
            if i >= idx {
                out.extend(docs);
                self.docs.push((i, vec![]));
            } else {
                self.docs.push((i, docs));
            }
        }
        self.docs.retain(|(_, d)| !d.is_empty());
        out
    }

    fn parse_pragma(&mut self, pragma_span: Span) -> SourceUnitItem {
        let name_tok = self.cur().clone();
        let name = if matches!(name_tok.kind, TokenKind::Ident) {
            self.bump();
            name_tok.text.clone()
        } else if name_tok.is_kw("solidity") {
            self.bump();
            "solidity".to_string()
        } else if name_tok.is_punct(";") {
            self.bump();
            return SourceUnitItem::Pragma(Pragma {
                span: pragma_span.join(self.prev_span()),
                name: (String::new(), DUMMY),
                value: None,
                value_span: None,
            });
        } else {
            let items = vec![Exp::Tok(";"), Exp::Tok("solidity")];
            self.expected_one_of(&items);
            return SourceUnitItem::Pragma(Pragma {
                span: pragma_span.join(self.prev_span()),
                name: (String::new(), DUMMY),
                value: None,
                value_span: None,
            });
        };
        let name_span = name_tok.span;
        if name == "solidity" {
            // version requirement
            let mut empty = true;
            let mut had_error = false;
            loop {
                let t = self.cur().clone();
                if t.is_punct(";") {
                    break;
                }
                if t.kind == TokenKind::Eof {
                    break;
                }
                let is_op = t.kind == TokenKind::Punct
                    && matches!(t.text.as_str(), "^" | "~" | "<" | "<=" | ">" | ">=" | "=" | "==" | "*" | "!");
                let is_num = matches!(t.kind, TokenKind::Integer | TokenKind::Rational);
                if is_op {
                    self.bump();
                    empty = false;
                    continue;
                }
                if is_num {
                    self.bump();
                    empty = false;
                    continue;
                }
                if t.is_punct(".") {
                    self.bump();
                    empty = false;
                    continue;
                }
                // error
                if !had_error {
                    self.diags.push(Diag::error("expected version number").with_span(t.span));
                    had_error = true;
                }
                self.bump();
            }
            if empty {
                self.diags
                    .push(Diag::error("empty version requirement").with_span(name_span));
            } else if had_error {
                let after = self.span();
                if !after.is_dummy() {
                    let sp = Span::new(self.file, after.start as usize + 1, after.end as usize);
                    self.diags
                        .push(Diag::error("unexpected trailing characters").with_span(sp));
                }
            }
            if self.eat_punct(";") {
            } else {
                self.expected_one_of(&[Exp::Tok(";")]);
            }
            return SourceUnitItem::Pragma(Pragma {
                span: pragma_span.join(self.prev_span()),
                name: ("solidity".to_string(), name_span),
                value: None,
                value_span: None,
            });
        }
        // other pragmas: `pragma name value;`
        let mut value = None;
        if !self.at_punct(";") {
            let t = self.eat();
            value = Some(t.text.clone());
        }
        if !self.eat_punct(";") {
            self.expected_one_of(&[Exp::Tok(";")]);
        }
        SourceUnitItem::Pragma(Pragma {
            span: pragma_span.join(self.prev_span()),
            name: (name, name_span),
            value,
            value_span: None,
        })
    }

    fn parse_import(&mut self, start: Span) -> SourceUnitItem {
        let mut directive = ImportDirective {
            span: start,
            path: String::new(),
            path_span: DUMMY,
            symbol: None,
            alias: None,
            symbols: vec![],
        };
        let t = self.cur().clone();
        if t.kind == TokenKind::Str {
            let tok = self.eat();
            directive.path = tok.value.unwrap_or_default();
            directive.path_span = tok.span;
            if self.eat_kw("as") {
                let id = self.eat();
                directive.symbol = Some((id.text.clone(), id.span));
            }
        } else if t.is_punct("*") {
            self.bump();
            if !self.eat_kw("as") {
                self.expected(Exp::Tok("as"));
            }
            let id = self.eat();
            directive.symbol = Some((id.text.clone(), id.span));
            if !self.eat_kw("from") {
                self.expected(Exp::Tok("from"));
            }
            let p = self.eat();
            directive.path = p.value.unwrap_or_default();
            directive.path_span = p.span;
        } else if t.is_punct("{") {
            self.bump();
            loop {
                let id = self.eat();
                let mut alias = None;
                if self.eat_kw("as") {
                    let a = self.eat();
                    alias = Some((a.text.clone(), a.span));
                }
                directive.symbols.push(((id.text.clone(), id.span), alias));
                if self.eat_punct(",") {
                    if self.at_punct("}") {
                        let mut d = Diag::error("trailing `,` separator is not allowed");
                        d.primary = Some(crate::diag::SpanLabel {
                            span: self.prev_span(),
                            label: None,
                        });
                        self.diags.push(d);
                        continue;
                    }
                    continue;
                }
                break;
            }
            if !self.eat_punct("}") {
                self.expected_one_of(&[Exp::Tok("}")]);
            }
            if !self.eat_kw("from") {
                self.expected(Exp::Tok("from"));
            }
            let p = self.eat();
            directive.path = p.value.unwrap_or_default();
            directive.path_span = p.span;
        } else {
            self.expected_one_of(&[Exp::Tok("*"), Exp::Tok("{"), TOK_STRLIT]);
            return SourceUnitItem::Import(directive);
        }
        if !self.eat_punct(";") {
            self.expected_one_of(&[Exp::Tok(";"), Exp::Tok("as")]);
        }
        directive.span = start.join(self.prev_span());
        SourceUnitItem::Import(directive)
    }

    fn parse_contract(&mut self, kind: ContractKind, abstract_: bool, docs: Vec<DocComment>) -> Item {
        let start = self.prev_span();
        let name_tok = self.eat();
        let name = (name_tok.text.clone(), name_tok.span);
        let mut bases = vec![];
        let mut layout = None;
        if self.at_kw("is") {
            self.bump();
            loop {
                let path = self.parse_path();
                let args = if self.at_punct("(") {
                    Some(self.parse_call_args())
                } else {
                    None
                };
                bases.push(InheritanceSpecifier { path, args });
                if self.eat_punct(",") {
                    continue;
                }
                break;
            }
        }
        if self.at_kw("layout") {
            self.bump();
            if !self.eat_kw("at") {
                self.expected_one_of(&[Exp::Tok("at")]);
            }
            let _expr = self.parse_expr();
            layout = Some(Layout::Compact);
            if !self.eat_punct("{") {
                self.expected_one_of(&[Exp::Tok("{")]);
            }
        }
        if !self.at_punct("{") {
            self.expected_one_of(&[Exp::Tok("is"), Exp::Tok("layout"), Exp::Tok("{")]);
            return Item {
                span: start.join(self.prev_span()),
                docs,
                kind: ItemKind::Contract {
                    kind,
                    name,
                    bases,
                    layout,
                    body: vec![],
                },
            };
        }
        self.bump();
        let body_start = self.span();
        let mut body = vec![];
        let mut reported = false;
        loop {
            if self.at_eof() {
                break;
            }
            if self.at_punct("}") {
                self.bump();
                break;
            }
            let item = self.parse_contract_item(&mut reported);
            match item {
                Some(it) => body.push(it),
                None => break,
            }
        }
        let _ = body_start;
        Item {
            span: start.join(self.prev_span()),
            docs,
            kind: ItemKind::Contract {
                kind,
                name,
                bases,
                layout,
                body,
            },
        }
    }

    fn parse_contract_item(&mut self, reported: &mut bool) -> Option<Item> {
        let t = self.cur().clone();
        let docs = self.take_docs();
        if t.is_kw("function") {
            self.bump();
            return Some(self.parse_function(FunctionKind::Function));
        }
        if t.is_kw("constructor") || t.is_kw("fallback") || t.is_kw("receive") {
            self.bump();
            let kind = if t.is_kw("constructor") {
                FunctionKind::Constructor
            } else if t.is_kw("fallback") {
                FunctionKind::Fallback
            } else {
                FunctionKind::Receive
            };
            return Some(self.parse_function(kind));
        }
        if t.is_kw("modifier") {
            self.bump();
            return Some(self.parse_modifier());
        }
        if t.is_kw("struct") {
            self.bump();
            return Some(self.parse_struct());
        }
        if t.is_kw("enum") {
            self.bump();
            return Some(self.parse_enum());
        }
        if t.is_kw("event") {
            self.bump();
            return Some(self.parse_event());
        }
        if t.is_kw("error") {
            self.bump();
            return Some(self.parse_error_def());
        }
        if t.is_kw("using") {
            self.bump();
            return Some(self.parse_using_for());
        }
        if self.is_type_start() {
            return Some(self.parse_state_variable(docs, None));
        }
        if !*reported {
            *reported = true;
            let msg = "expected contract item (function, variable, struct, or modifier definition)";
            let found = self.cur().describe();
            let mut d = Diag::error(format!("{msg}, found {found}"));
            d.primary = Some(crate::diag::SpanLabel { span: self.cur().span, label: None });
            d.notes.push(("for a full list of valid contract items, see <https://docs.soliditylang.org/en/latest/grammar.html#a4.SolidityParser.contractBodyElement>".to_string(), None));
            self.diags.push(d);
        }
        None
    }

    fn parse_struct(&mut self) -> Item {
        let start = self.prev_span();
        let name_tok = self.eat();
        let name = (name_tok.text.clone(), name_tok.span);
        let mut members = vec![];
        if self.eat_punct("{") {
            loop {
                if self.at_eof() || self.at_punct("}") {
                    break;
                }
                let ty = self.parse_type();
                let mut param = Param {
                    span: ty.span,
                    ty: Some(ty),
                    data_location: None,
                    visibility: None,
                    mutability: None,
                    indexed: false,
                    name: None,
                };
                if matches!(self.cur().kind, TokenKind::Ident) {
                    let t = self.eat();
                    param.name = Some((t.text.clone(), t.span));
                }
                param.span = param.span.join(self.prev_span());
                members.push(param);
                if self.eat_punct(";") {
                    continue;
                }
                break;
            }
            if !self.eat_punct("}") {
                self.expected_one_of(&[Exp::Tok("}")]);
            }
        } else {
            self.expected(Exp::Tok("{"));
        }
        Item {
            span: start.join(self.prev_span()),
            docs: vec![],
            kind: ItemKind::Struct { name, members },
        }
    }

    fn parse_enum(&mut self) -> Item {
        let start = self.prev_span();
        let name_tok = self.eat();
        let name = (name_tok.text.clone(), name_tok.span);
        let mut variants = vec![];
        if self.eat_punct("{") {
            loop {
                if self.at_eof() || self.at_punct("}") {
                    break;
                }
                if matches!(self.cur().kind, TokenKind::Ident) {
                    let t = self.eat();
                    variants.push((t.text.clone(), t.span));
                } else {
                    self.expected(Exp::Desc("identifier"));
                    break;
                }
                if self.eat_punct(",") {
                    continue;
                }
                break;
            }
            if !self.eat_punct("}") {
                self.expected(Exp::Tok("{"));
            }
        } else {
            self.expected(Exp::Tok("{"));
        }
        Item {
            span: start.join(self.prev_span()),
            docs: vec![],
            kind: ItemKind::Enum { name, variants },
        }
    }

    fn parse_event(&mut self) -> Item {
        let start = self.prev_span();
        let name_tok = self.eat();
        let name = (name_tok.text.clone(), name_tok.span);
        let params = self.parse_param_list(true);
        let mut anonymous = false;
        if self.eat_kw("anonymous") {
            anonymous = true;
        }
        if !self.eat_punct(";") {
            self.expected_one_of(&[Exp::Tok(";"), Exp::Tok("anonymous")]);
        }
        Item {
            span: start.join(self.prev_span()),
            docs: vec![],
            kind: ItemKind::Event {
                name,
                params,
                anonymous,
            },
        }
    }

    fn parse_error_def(&mut self) -> Item {
        let start = self.prev_span();
        let name_tok = self.eat();
        let name = (name_tok.text.clone(), name_tok.span);
        let params = self.parse_param_list(true);
        if !self.eat_punct(";") {
            self.expected_one_of(&[Exp::Tok(";")]);
        }
        Item {
            span: start.join(self.prev_span()),
            docs: vec![],
            kind: ItemKind::Error { name, params },
        }
    }

    fn parse_using_for(&mut self) -> Item {
        let start = self.prev_span();
        let library = self.parse_path();
        if !self.eat_kw("for") {
            self.expected(Exp::Tok("for"));
        }
        let mut ty = None;
        let mut fns = None;
        let mut global = false;
        if !self.at_kw("global") {
            if self.at_punct("*") {
                self.bump();
            } else if self.is_type_start() {
                ty = Some(self.parse_type());
            } else {
                self.expected_one_of(&[Exp::Tok("*"), Exp::Tok("function"), Exp::Tok("mapping"), TOK_ELEMENTARY, TOK_PATH]);
            }
        }
        if self.at_punct("{") {
            self.bump();
            let mut list = vec![];
            loop {
                if self.at_punct("}") || self.at_eof() {
                    break;
                }
                let p = self.parse_path();
                list.push(p);
                if self.eat_punct(",") {
                    continue;
                }
                break;
            }
            if !self.eat_punct("}") {
                self.expected_one_of(&[Exp::Tok("}")]);
            }
            fns = Some(list);
        }
        if self.eat_kw("global") {
            global = true;
            if self.contract_depth > 0 {
                let sp = start.join(self.prev_span());
                self.diags
                    .push(Diag::error("`global` can only be used at file level").with_span(sp));
            }
        }
        if !self.eat_punct(";") {
            self.expected_one_of(&[Exp::Tok(";")]);
        }
        Item {
            span: start.join(self.prev_span()),
            docs: vec![],
            kind: ItemKind::UsingFor { library, ty, global, fns },
        }
    }

    fn parse_modifier(&mut self) -> Item {
        let start = self.prev_span();
        let name_tok = self.eat();
        let name = (name_tok.text.clone(), name_tok.span);
        let params = if self.at_punct("(") {
            self.parse_param_list(false)
        } else {
            vec![]
        };
        let mut virtual_ = false;
        let mut override_ = None;
        loop {
            if self.eat_kw("virtual") {
                virtual_ = true;
                continue;
            }
            if self.at_kw("override") {
                override_ = Some(self.parse_override());
                continue;
            }
            break;
        }
        let body = self.parse_function_body();
        Item {
            span: start.join(self.prev_span()),
            docs: vec![],
            kind: ItemKind::Modifier {
                name,
                params,
                virtual_,
                override_,
                body,
            },
        }
    }

    fn parse_override(&mut self) -> Vec<Path> {
        self.bump();
        let mut list = vec![];
        if self.eat_punct("(") {
            loop {
                if self.at_punct(")") || self.at_eof() {
                    break;
                }
                let p = self.parse_path();
                list.push(p);
                if self.eat_punct(",") {
                    continue;
                }
                break;
            }
            if !self.eat_punct(")") {
                self.expected_one_of(&[Exp::Tok(")")]);
            }
        }
        list
    }

    fn parse_state_variable(&mut self, docs: Vec<DocComment>, _x: Option<()>) -> Item {
        let start = self.span();
        let ty = self.parse_type();
        let mut item = Item {
            span: start,
            docs,
            kind: ItemKind::VariableDefinition {
                span: start,
                ty,
                visibility: None,
                mutability: None,
                data_location: None,
                override_: None,
                indexed: false,
                name: None,
                initializer: None,
            },
        };
        let mut name = None;
        if matches!(self.cur().kind, TokenKind::Ident) {
            let t = self.eat();
            name = Some((t.text.clone(), t.span));
        }
        let mut visibility = None;
        let mut mutability = None;
        let mut data_location = None;
        let mut override_ = None;
        let mut indexed = false;
        loop {
            if self.at_kw("public")
                || self.at_kw("external")
                || self.at_kw("internal")
                || self.at_kw("private")
            {
                let t = self.eat();
                visibility = Some(match t.text.as_str() {
                    "public" => Visibility::Public,
                    "external" => Visibility::External,
                    "internal" => Visibility::Internal,
                    _ => Visibility::Private,
                });
                continue;
            }
            if self.at_kw("constant") || self.at_kw("immutable") || self.at_kw("transient") {
                let t = self.eat();
                mutability = Some(match t.text.as_str() {
                    "constant" => Mutability::Constant,
                    "immutable" => Mutability::Immutable,
                    _ => Mutability::Transient,
                });
                continue;
            }
            if self.at_kw("memory") || self.at_kw("calldata") || self.at_kw("storage") {
                let t = self.eat();
                data_location = Some(match t.text.as_str() {
                    "memory" => Mutability::Immutable,
                    "calldata" => Mutability::Immutable,
                    _ => Mutability::Immutable,
                });
                continue;
            }
            if self.at_kw("override") {
                override_ = Some(self.parse_override());
                continue;
            }
            if self.at_kw("indexed") {
                self.bump();
                indexed = true;
                continue;
            }
            break;
        }
        let mut initializer = None;
        if self.eat_punct("=") {
            initializer = Some(self.parse_expr());
        }
        if !self.eat_punct(";") {
            self.expected_one_of(&[Exp::Tok(";"), Exp::Tok("=")]);
        }
        let end = self.prev_span();
        if let ItemKind::VariableDefinition { .. } = &mut item.kind {
            item.kind = ItemKind::VariableDefinition {
                span: start.join(end),
                ty: Type {
                    span: start,
                    kind: TypeKind::Elementary(ElementaryType::Bool),
                },
                visibility,
                mutability,
                data_location,
                override_,
                indexed,
                name,
                initializer,
            };
            // re-parse the type to store it properly
            if let ItemKind::VariableDefinition { ty: ref mut t, .. } = item.kind {
                let mut p = Parser::from_tokens(self.toks.clone(), self.file);
                p.pos = 0;
                let _ = p;
            }
        }
        item
    }

    fn parse_function(&mut self, kind: FunctionKind) -> Item {
        let start = self.prev_span();
        let mut name = None;
        if kind == FunctionKind::Function || kind == FunctionKind::Free {
            if matches!(self.cur().kind, TokenKind::Ident) {
                let t = self.eat();
                name = Some((t.text.clone(), t.span));
            } else if !self.at_punct("(") {
                self.expected(Exp::Desc("identifier"));
            }
        }
        let mut header = FunctionHeader {
            span: start,
            name,
            params: vec![],
            returns: vec![],
            visibility: None,
            mutability: None,
            virtual_: false,
            override_: None,
            modifiers: vec![],
        };
        if self.at_punct("(") {
            header.params = self.parse_param_list(false);
        } else {
            self.expected(Exp::Tok("("));
        }
        if kind == FunctionKind::Fallback || kind == FunctionKind::Receive {
            // must be external
        }
        loop {
            if self.at_kw("returns") {
                self.bump();
                header.returns = self.parse_param_list(true);
                continue;
            }
            if self.at_kw("external")
                || self.at_kw("internal")
                || self.at_kw("public")
                || self.at_kw("private")
            {
                let t = self.eat();
                let v = match t.text.as_str() {
                    "external" => Visibility::External,
                    "internal" => Visibility::Internal,
                    "public" => Visibility::Public,
                    _ => Visibility::Private,
                };
                if header.visibility.is_some() {
                    let sp = start.join(self.prev_span());
                    self.diags
                        .push(Diag::error("visibility already specified").with_label(sp, "previous definition"));
                }
                header.visibility = Some(v);
                continue;
            }
            if self.at_kw("pure")
                || self.at_kw("view")
                || self.at_kw("payable")
                || self.at_kw("constant")
                || self.at_kw("immutable")
                || self.at_kw("transient")
            {
                let t = self.eat();
                let m = match t.text.as_str() {
                    "pure" => Mutability::Pure,
                    "view" => Mutability::View,
                    "payable" => Mutability::Payable,
                    "constant" => Mutability::Constant,
                    "immutable" => Mutability::Immutable,
                    _ => Mutability::Transient,
                };
                if header.mutability.is_some() {
                    let sp = start.join(self.prev_span());
                    self.diags
                        .push(Diag::error("state mutability already specified").with_label(sp, "previous definition"));
                }
                header.mutability = Some(m);
                continue;
            }
            if self.eat_kw("virtual") {
                header.virtual_ = true;
                continue;
            }
            if self.at_kw("override") {
                header.override_ = Some(self.parse_override());
                continue;
            }
            if matches!(self.cur().kind, TokenKind::Ident) {
                let path = self.parse_path();
                let args = if self.at_punct("(") {
                    Some(self.parse_call_args())
                } else {
                    None
                };
                header.modifiers.push((path, args));
                continue;
            }
            break;
        }
        header.span = start.join(self.prev_span());
        let body = self.parse_function_body();
        Item {
            span: start.join(self.prev_span()),
            docs: vec![],
            kind: ItemKind::Function { kind, header, body },
        }
    }

    fn parse_function_body(&mut self) -> Body {
        if self.eat_punct(";") {
            return Body::None;
        }
        if self.at_punct("{") {
            let stmts = self.parse_block();
            return Body::Block(stmts);
        }
        self.expected_one_of(&[Exp::Tok(";"), Exp::Tok("{")]);
        Body::None
    }
}
RSEOF
echo ok"}

