pub fn elementary_of(name: &str) -> ElementaryType {
    match name {
        "address" => ElementaryType::Address(false),
        "bool" => ElementaryType::Bool,
        "string" => ElementaryType::String,
        "bytes" => ElementaryType::Bytes,
        "byte" => ElementaryType::BytesN(1),
        "fixed" => ElementaryType::Fixed(128, 18),
        "ufixed" => ElementaryType::UFixed(128, 18),
        _ => {}
    }
    if let Some(rest) = name.strip_prefix("uint") {
        if let Ok(n) = rest.parse::<u16>() {
            return ElementaryType::Uint(n);
        }
    }
    if let Some(rest) = name.strip_prefix("int") {
        if let Ok(n) = rest.parse::<u16>() {
            return ElementaryType::Int(n);
        }
    }
    if let Some(rest) = name.strip_prefix("bytes") {
        if let Ok(n) = rest.parse::<u8>() {
            return ElementaryType::BytesN(n);
        }
    }
    if let Some(rest) = name.strip_prefix("ufixed") {
        if let Some((m, n)) = rest.split_once('x') {
            if let (Ok(m), Ok(n)) = (m.parse::<u8>(), n.parse::<u8>()) {
                return ElementaryType::UFixed(m, n);
            }
        }
    }
    if let Some(rest) = name.strip_prefix("fixed") {
        if let Some((m, n)) = rest.split_once('x') {
            if let (Ok(m), Ok(n)) = (m.parse::<u8>(), n.parse::<u8>()) {
                return ElementaryType::Fixed(m, n);
            }
        }
    }
    if name == "address" {
        ElementaryType::Address(false)
    } else if name == "bool" {
        ElementaryType::Bool
    } else if name == "string" {
        ElementaryType::String
    } else if name == "bytes" {
        ElementaryType::Bytes
    } else {
        ElementaryType::Uint(0)
    }
}

impl Parser {
    // --------------------------------------------------------------------
    // statements

    fn parse_block(&mut self) -> Vec<Stmt> {
        if !self.eat_punct("{") {
            return vec![];
        }
        let mut out = vec![];
        loop {
            if self.at_eof() || self.at_punct("}") {
                break;
            }
            let st = self.parse_stmt();
            if let Some(s) = st {
                out.push(s);
            } else {
                break;
            }
        }
        if !self.eat_punct("}") {
            self.expected_one_of(&[Exp::Tok("}")]);
        }
        out
    }

    fn parse_stmt(&mut self) -> Option<Stmt> {
        let start = self.span();
        let t = self.cur().clone();
        if t.is_punct("{") {
            let stmts = self.parse_block();
            return Some(Stmt {
                span: start.join(self.prev_span()),
                kind: StmtKind::Block(stmts),
            });
        }
        if t.is_punct(";") {
            self.bump();
            return Some(Stmt { span: start, kind: StmtKind::Block(vec![]) });
        }
        if t.is_kw("unchecked") {
            self.bump();
            if !self.eat_punct("{") {
                self.expected(Exp::Tok("{"));
            }
            let mut out = vec![];
            loop {
                if self.at_eof() || self.at_punct("}") {
                    break;
                }
                let st = self.parse_stmt();
                match st {
                    Some(s) => out.push(s),
                    None => break,
                }
            }
            if !self.eat_punct("}") {
                self.expected_one_of(&[Exp::Tok("}")]);
            }
            return Some(Stmt {
                span: start.join(self.prev_span()),
                kind: StmtKind::Unchecked(out),
            });
        }
        if t.is_kw("if") {
            self.bump();
            if !self.eat_punct("(") {
                self.expected(Exp::Tok("("));
            }
            let cond = self.parse_expr();
            if !self.eat_punct(")") {
                self.expected(Exp::Tok(")"));
            }
            let then = self.parse_stmt_or_block();
            let else_ = if self.eat_kw("else") {
                Some(self.parse_stmt_or_block())
            } else {
                None
            };
            return Some(Stmt {
                span: start.join(self.prev_span()),
                kind: StmtKind::If(cond, then, else_),
            });
        }
        if t.is_kw("for") {
            self.bump();
            if !self.eat_punct("(") {
                self.expected(Exp::Tok("("));
            }
            let init = self.parse_for_init();
            let cond = if self.at_punct(";") {
                self.bump();
                None
            } else {
                Some(self.parse_expr())
            };
            if !self.eat_punct(";") {
                self.expected(Exp::Tok(";"));
            }
            let step = if self.at_punct(")") { None } else { Some(self.parse_expr()) };
            if !self.eat_punct(")") {
                self.expected(Exp::Tok(")"));
            }
            let body = self.parse_stmt_or_block();
            return Some(Stmt {
                span: start.join(self.prev_span()),
                kind: StmtKind::For(init, cond, step, body),
            });
        }
        if t.is_kw("while") {
            self.bump();
            if !self.eat_punct("(") {
                self.expected(Exp::Tok("("));
            }
            let cond = self.parse_expr();
            if !self.eat_punct(")") {
                self.expected(Exp::Tok(")"));
            }
            let body = self.parse_stmt_or_block();
            return Some(Stmt {
                span: start.join(self.prev_span()),
                kind: StmtKind::While(cond, body),
            });
        }
        if t.is_kw("do") {
            self.bump();
            let body = self.parse_stmt_or_block();
            if !self.eat_kw("while") {
                self.expected(Exp::Tok("while"));
            }
            if !self.eat_punct("(") {
                self.expected(Exp::Tok("("));
            }
            let cond = self.parse_expr();
            if !self.eat_punct(")") {
                self.expected(Exp::Tok(")"));
            }
            if !self.eat_punct(";") {
                self.expected(Exp::Tok(";"));
            }
            return Some(Stmt {
                span: start.join(self.prev_span()),
                kind: StmtKind::DoWhile(body, cond),
            });
        }
        if t.is_kw("continue") {
            self.bump();
            if !self.eat_punct(";") {
                self.expected(Exp::Tok(";"));
            }
            return Some(Stmt { span: start, kind: StmtKind::Continue });
        }
        if t.is_kw("break") {
            self.bump();
            if !self.eat_punct(";") {
                self.expected(Exp::Tok(";"));
            }
            return Some(Stmt { span: start, kind: StmtKind::Break });
        }
        if t.is_kw("return") {
            self.bump();
            let expr = if self.at_punct(";") {
                None
            } else {
                Some(self.parse_expr())
            };
            if !self.eat_punct(";") {
                self.expected(Exp::Tok(";"));
            }
            return Some(Stmt {
                span: start.join(self.prev_span()),
                kind: StmtKind::Return(expr),
            });
        }
        if t.is_kw("emit") {
            self.bump();
            let e = self.parse_expr();
            if !self.eat_punct(";") {
                self.expected(Exp::Tok(";"));
            }
            return Some(Stmt {
                span: start.join(self.prev_span()),
                kind: StmtKind::Emit(e),
            });
        }
        if t.is_kw("revert") {
            self.bump();
            let e = if self.at_punct(";") {
                Expr { span: start, kind: ExprKind::Tuple(vec![]) }
            } else {
                self.parse_expr()
            };
            if !self.eat_punct(";") {
                self.expected(Exp::Tok(";"));
            }
            return Some(Stmt {
                span: start.join(self.prev_span()),
                kind: StmtKind::Revert(e),
            });
        }
        if t.is_kw("assembly") {
            let blk = self.parse_assembly(start);
            return Some(Stmt {
                span: start.join(self.prev_span()),
                kind: StmtKind::Assembly(blk),
            });
        }
        if t.is_kw("try") {
            self.bump();
            let expr = self.parse_expr();
            let mut rets = vec![];
            if self.at_kw("returns") {
                self.bump();
                rets = self.parse_param_list(true);
            }
            let body = self.parse_block();
            let mut catches = vec![];
            while self.at_kw("catch") {
                let cstart = self.span();
                self.bump();
                let mut name = None;
                if matches!(self.cur().kind, TokenKind::Ident) {
                    let n = self.eat();
                    name = Some((n.text.clone(), n.span));
                }
                let params = if self.at_punct("(") {
                    self.parse_param_list(false)
                } else {
                    vec![]
                };
                let cbody = self.parse_block();
                catches.push(CatchClause {
                    span: cstart.join(self.prev_span()),
                    name,
                    params,
                    body: cbody,
                });
            }
            return Some(Stmt {
                span: start.join(self.prev_span()),
                kind: StmtKind::Try(expr, rets, body, catches),
            });
        }
        if t.is_punct("_") {
            self.bump();
            return Some(Stmt { span: start, kind: StmtKind::Placeholder });
        }
        // variable declaration or expression statement
        if self.looks_like_var_decl() {
            let decls = self.parse_var_decls();
            return Some(Stmt {
                span: start.join(self.prev_span()),
                kind: StmtKind::VarDecls(decls),
            });
        }
        let e = self.parse_expr();
        if !self.eat_punct(";") {
            self.expected_one_of(&[Exp::Tok("("), Exp::Tok("."), Exp::Tok(";"), Exp::Tok("?"), Exp::Tok("[")]);
        }
        Some(Stmt {
            span: start.join(self.prev_span()),
            kind: StmtKind::Expr(e),
        })
    }

    fn parse_stmt_or_block(&mut self) -> Vec<Stmt> {
        if self.at_punct("{") {
            return self.parse_block();
        }
        match self.parse_stmt() {
            Some(s) => vec![s],
            None => vec![],
        }
    }

    fn parse_for_init(&mut self) -> Option<Box<Stmt>> {
        if self.at_punct(";") {
            return None;
        }
        if self.looks_like_var_decl() {
            let decls = self.parse_var_decls();
            if !self.eat_punct(";") {
                self.expected(Exp::Tok(";"));
            }
            return Some(Box::new(Stmt {
                span: DUMMY,
                kind: StmtKind::VarDecls(decls),
            }));
        }
        let e = self.parse_expr();
        if !self.eat_punct(";") {
            self.expected(Exp::Tok(";"));
        }
        Some(Box::new(Stmt { span: DUMMY, kind: StmtKind::Expr(e) }))
    }

    fn looks_like_var_decl(&self) -> bool {
        // (type ident (memory|calldata|storage)? (= expr)? | (, ident)+) ;
        let mut p = self.pos;
        let tok_at = |p: usize| -> &Token { &self.toks[p.min(self.toks.len() - 1)] };
        if tok_at(p).is_punct("(") {
            return true;
        }
        if !matches!(
            tok_at(p).kind,
            TokenKind::Ident | TokenKind::Keyword
        ) {
            return false;
        }
        if tok_at(p).is_kw("emit") || tok_at(p).is_kw("revert") || tok_at(p).is_kw("assembly") {
            return false;
        }
        // scan for a `=` or `;` on the same nesting level, requiring an ident after the type
        let mut depth = 0usize;
        let mut seen_ident = false;
        while p < self.toks.len() {
            let t = tok_at(p);
            if t.is_punct("(") || t.is_punct("[") {
                depth += 1;
            }
            if t.is_punct(")") || t.is_punct("]") {
                if depth == 0 {
                    break;
                }
                depth -= 1;
            }
            if depth == 0 {
                if t.is_punct(";") {
                    return seen_ident;
                }
                if t.is_punct("=") {
                    return seen_ident;
                }
                if t.is_punct(",") {
                    return false;
                }
            }
            if depth == 0 && matches!(t.kind, TokenKind::Ident) {
                seen_ident = true;
            }
            if depth == 0 && t.is_kw("memory") || t.is_kw("calldata") || t.is_kw("storage") {
                // fine
            }
            p += 1;
            if p > self.pos + 200 {
                break;
            }
        }
        false
    }

    fn parse_var_decls(&mut self) -> Vec<VarDecl> {
        let start = self.span();
        if self.at_punct("(") {
            // tuple destructuring
            self.bump();
            let mut decls = vec![];
            loop {
                if self.at_punct(")") || self.at_eof() {
                    break;
                }
                if self.at_punct(",") {
                    self.bump();
                    continue;
                }
                let ty = self.parse_type();
                let mut dl = None;
                loop {
                    if self.at_kw("memory") || self.at_kw("calldata") || self.at_kw("storage") {
                        self.bump();
                        dl = Some(Mutability::Immutable);
                        continue;
                    }
                    break;
                }
                let name_tok = self.eat();
                let mut initializer = None;
                if self.eat_punct("=") {
                    initializer = Some(self.parse_expr());
                }
                decls.push(VarDecl {
                    span: ty.span.join(name_tok.span),
                    ty: Some(ty),
                    data_location: dl,
                    visibility: None,
                    mutability: None,
                    indexed: false,
                    name: (name_tok.text.clone(), name_tok.span),
                    initializer,
                });
                if self.eat_punct(",") {
                    continue;
                }
                break;
            }
            if !self.eat_punct(")") {
                self.expected_one_of(&[Exp::Tok(")")]);
            }
            if !self.eat_punct(";") {
                self.expected_one_of(&[Exp::Tok(";")]);
            }
            let _ = start;
            return decls;
        }
        let ty = self.parse_type();
        let mut dl = None;
        let mut mutability = None;
        loop {
            if self.at_kw("memory") || self.at_kw("calldata") || self.at_kw("storage") {
                self.bump();
                dl = Some(Mutability::Immutable);
                continue;
            }
            if self.at_kw("constant") || self.at_kw("immutable") || self.at_kw("transient") {
                let t = self.eat();
                mutability = Some(match t.text.as_str() {
                    "constant" => Mutability::Constant,
                    "immutable" => Mutability::Immutable,
                    _ => Mutability::Transient,
                });
                continue;
            }
            if self.at_kw("public") || self.at_kw("private") || self.at_kw("internal") || self.at_kw("external") {
                self.bump();
                continue;
            }
            break;
        }
        let name_tok = self.eat();
        let mut initializer = None;
        if self.eat_punct("=") {
            initializer = Some(self.parse_expr());
        }
        if !self.eat_punct(";") {
            self.expected_one_of(&[Exp::Tok(";")]);
        }
        vec![VarDecl {
            span: ty.span.join(self.prev_span()),
            ty: Some(ty),
            data_location: dl,
            visibility: None,
            mutability,
            indexed: false,
            name: (name_tok.text.clone(), name_tok.span),
            initializer,
        }]
    }

    // --------------------------------------------------------------------
    // expressions

    fn parse_call_args(&mut self) -> Vec<Expr> {
        let mut named = vec![];
        if !self.eat_punct("(") {
            self.expected(Exp::Tok("("));
            return vec![];
        }
        if self.eat_punct(")") {
            return vec![];
        }
        // named arguments?
        if matches!(self.cur().kind, TokenKind::Ident | TokenKind::Keyword)
            && self.peek(1).is_punct(":")
        {
            loop {
                let id = self.eat();
                if !self.eat_punct(":") {
                    self.expected_one_of(&[Exp::Tok(":")]);
                }
                let e = self.parse_expr();
                named.push(((id.text.clone(), id.span), e));
                if self.eat_punct(",") {
                    if self.at_punct(")") {
                        let mut d = Diag::error("trailing `,` separator is not allowed");
                        d.primary = Some(crate::diag::SpanLabel { span: self.prev_span(), label: None });
                        self.diags.push(d);
                        continue;
                    }
                    continue;
                }
                break;
            }
            if !self.eat_punct(")") {
                self.expected_one_of(&[Exp::Tok(")")]);
            }
            let _ = named;
            return vec![];
        }
        let mut args = vec![];
        loop {
            if self.at_punct(")") || self.at_eof() {
                break;
            }
            let e = self.parse_expr();
            args.push(e);
            if self.eat_punct(",") {
                if self.at_punct(")") {
                    let mut d = Diag::error("trailing `,` separator is not allowed");
                    d.primary = Some(crate::diag::SpanLabel { span: self.prev_span(), label: None });
                    self.diags.push(d);
                    continue;
                }
                continue;
            }
            break;
        }
        if !self.eat_punct(")") {
            self.expected_one_of(&[Exp::Tok(")")]);
        }
        args
    }

    pub fn parse_expr(&mut self) -> Expr {
        self.parse_expr_prec(0)
    }

    fn parse_expr_prec(&mut self, min_prec: u8) -> Expr {
        let start = self.span();
        let mut lhs = self.parse_unary();
        loop {
            let t = self.cur().clone();
            if t.is_punct("?") {
                if 2 < min_prec {
                    break;
                }
                self.bump();
                let a = self.parse_expr_prec(0);
                if !self.eat_punct(":") {
                    self.expected_one_of(&[Exp::Tok(":")]);
                }
                let b = self.parse_expr_prec(0);
                lhs = Expr {
                    span: start.join(self.prev_span()),
                    kind: ExprKind::Conditional(Box::new(lhs), Box::new(a), Box::new(b)),
                };
                continue;
            }
            let (op, prec, right_assoc) = match binary_op(&t) {
                Some(x) => x,
                None => break,
            };
            if prec < min_prec {
                break;
            }
            self.bump();
            let next_min = if right_assoc { prec } else { prec + 1 };
            let rhs = self.parse_expr_prec(next_min);
            lhs = Expr {
                span: start.join(self.prev_span()),
                kind: ExprKind::Binary(op, Box::new(lhs), Box::new(rhs)),
            };
        }
        lhs
    }

    fn parse_unary(&mut self) -> Expr {
        let start = self.span();
        let t = self.cur().clone();
        // prefix unary
        if t.kind == TokenKind::Punct
            && matches!(t.text.as_str(), "!" | "~" | "+" | "-" | "++" | "--")
        {
            self.bump();
            let e = self.parse_unary();
            return Expr {
                span: start.join(self.prev_span()),
                kind: ExprKind::Unary(t.text.clone(), Box::new(e), true),
            };
        }
        if t.is_kw("delete") {
            self.bump();
            let e = self.parse_unary();
            return Expr {
                span: start.join(self.prev_span()),
                kind: ExprKind::Unary("delete".to_string(), Box::new(e), true),
            };
        }
        if t.is_kw("new") {
            self.bump();
            let ty = self.parse_type();
            let e = self.parse_postfix_ops(Expr { span: start.join(self.prev_span()), kind: ExprKind::New(ty) });
            return e;
        }
        if t.is_kw("payable") && matches!(self.peek(1).kind, TokenKind::Punct) && self.peek(1).is_punct("(") {
            self.bump();
            let args = self.parse_call_args();
            return Expr {
                span: start.join(self.prev_span()),
                kind: ExprKind::Call(
                    Box::new(Expr { span: start, kind: ExprKind::Elementary(ElementaryType::Address(true)) }),
                    args,
                    vec![],
                ),
            };
        }
        if t.is_kw("type") {
            self.bump();
            let path = self.parse_path();
            let callee = Expr { span: start.join(path.span), kind: ExprKind::Path(path) };
            return self.parse_postfix_ops(callee);
        }
        if t.kind == TokenKind::Keyword && self.is_elementary_kw(&t) {
            // elementary type name used as a conversion
            let name = t.text.clone();
            self.bump();
            let callee = Expr {
                span: t.span,
                kind: ExprKind::Elementary(elementary_of(&name)),
            };
            return self.parse_postfix_ops(callee);
        }
        let atom = self.parse_atom();
        self.parse_postfix_ops(atom)
    }

    fn parse_atom(&mut self) -> Expr {
        let t = self.cur().clone();
        let start = t.span;
        match t.kind {
            TokenKind::Integer => {
                self.bump();
                Expr {
                    span: t.span,
                    kind: ExprKind::Lit(LitKind::Number(t.text.clone())),
                }
            }
            TokenKind::Rational => {
                self.bump();
                Expr {
                    span: t.span,
                    kind: ExprKind::Lit(LitKind::Rational(t.text.clone())),
                }
            }
            TokenKind::Str => {
                self.bump();
                let mut value: Vec<u8> = t.value.clone().unwrap_or_default().into_bytes();
                // adjacent string literals are concatenated
                while matches!(self.cur().kind, TokenKind::Str) {
                    let n = self.eat();
                    value.extend_from_slice(n.value.unwrap_or_default().as_bytes());
                }
                Expr { span: t.span, kind: ExprKind::Lit(LitKind::Str(value)) }
            }
            TokenKind::HexStr => {
                self.bump();
                let hex: String = t.value.clone().unwrap_or_default();
                let bytes = hex::decode(&hex);
                Expr {
                    span: t.span,
                    kind: ExprKind::Lit(LitKind::Str(bytes.unwrap_or_default())),
                }
            }
            TokenKind::UnicodeStr => {
                self.bump();
                let value = t.value.clone().unwrap_or_default();
                Expr {
                    span: t.span,
                    kind: ExprKind::Lit(LitKind::Str(value.into_bytes())),
                }
            }
            TokenKind::Ident => {
                let path = self.parse_path();
                Expr { span: path.span.clone(), kind: ExprKind::Path(path) }
            }
            TokenKind::Keyword => {
                if t.text == "true" || t.text == "false" {
                    self.bump();
                    return Expr {
                        span: t.span,
                        kind: ExprKind::Lit(LitKind::Bool(t.text == "true")),
                    };
                }
                if t.is_kw("address") {
                    self.bump();
                    return Expr {
                        span: t.span,
                        kind: ExprKind::Elementary(ElementaryType::Address(false)),
                    };
                }
                if t.is_kw("mapping") || t.is_kw("function") || self.is_elementary_kw(&t) {
                    let ty = self.parse_type();
                    return Expr { span: ty.span.clone(), kind: ExprKind::Elementary(ElementaryType::Bool) };
                }
                self.expected_one_of(&elementary_expected());
                self.bump();
                Expr { span: t.span, kind: ExprKind::Tuple(vec![]) }
            }
            TokenKind::Punct => {
                if t.text == "(" {
                    self.bump();
                    let mut items: Vec<Option<Expr>> = vec![];
                    loop {
                        if self.at_punct(")") || self.at_eof() {
                            break;
                        }
                        if self.at_punct(",") {
                            items.push(None);
                            self.bump();
                            continue;
                        }
                        let e = self.parse_expr();
                        items.push(Some(e));
                        if self.eat_punct(",") {
                            continue;
                        }
                        break;
                    }
                    if !self.eat_punct(")") {
                        self.expected_one_of(&[Exp::Tok(")")]);
                    }
                    if items.len() == 1 {
                        return items[0].clone().unwrap();
                    }
                    return Expr {
                        span: start.join(self.prev_span()),
                        kind: ExprKind::Tuple(items),
                    };
                }
                self.expected_one_of(&elementary_expected());
                self.bump();
                Expr { span: t.span, kind: ExprKind::Tuple(vec![]) }
            }
            TokenKind::Eof => {
                self.expected_one_of(&elementary_expected());
                Expr { span: t.span, kind: ExprKind::Tuple(vec![]) }
            }
        }
    }

    fn parse_postfix_ops(&mut self, mut e: Expr) -> Expr {
        let start = e.span;
        loop {
            let t = self.cur().clone();
            if t.is_punct(".") {
                self.bump();
                let n = self.eat();
                e = Expr {
                    span: start.join(n.span),
                    kind: ExprKind::Member(Box::new(e), (n.text.clone(), n.span)),
                };
                continue;
            }
            if t.is_punct("[") {
                self.bump();
                if self.at_punct("]") {
                    self.bump();
                    e = Expr {
                        span: start.join(self.prev_span()),
                        kind: ExprKind::Index(Box::new(e), None),
                    };
                    continue;
                }
                let idx = self.parse_expr();
                if !self.eat_punct("]") {
                    self.expected_one_of(&[Exp::Tok("]")]);
                }
                e = Expr {
                    span: start.join(self.prev_span()),
                    kind: ExprKind::Index(Box::new(e), Some(Box::new(idx))),
                };
                continue;
            }
            if t.is_punct("(") {
                let args = self.parse_call_args();
                e = Expr {
                    span: start.join(self.prev_span()),
                    kind: ExprKind::Call(Box::new(e), args, vec![]),
                };
                continue;
            }
            if t.is_punct("{") {
                // call options: f({value: 1})
                self.bump();
                let mut opts = vec![];
                loop {
                    if self.at_punct("}") || self.at_eof() {
                        break;
                    }
                    let id = self.eat();
                    if !self.eat_punct(":") {
                        self.expected_one_of(&[Exp::Tok(":")]);
                    }
                    let v = if self.at_punct(",") || self.at_punct("}") {
                        None
                    } else {
                        Some(self.parse_expr())
                    };
                    opts.push(((id.text.clone(), id.span), v));
                    if self.eat_punct(",") {
                        continue;
                    }
                    break;
                }
                if !self.eat_punct("}") {
                    self.expected_one_of(&[Exp::Tok("}")]);
                }
                e = Expr {
                    span: start.join(self.prev_span()),
                    kind: ExprKind::CallOptions(Box::new(e), opts),
                };
                continue;
            }
            if t.is_punct("++") || t.is_punct("--") {
                self.bump();
                e = Expr {
                    span: start.join(self.prev_span()),
                    kind: ExprKind::Unary(t.text.clone(), Box::new(e), false),
                };
                continue;
            }
            break;
        }
        e
    }

    // --------------------------------------------------------------------
    // assembly

    fn parse_assembly(&mut self, start: Span) -> AssemblyBlock {
        self.bump();
        let mut dialect = None;
        if matches!(self.cur().kind, TokenKind::Str) {
            let t = self.eat();
            dialect = Some(t.value.unwrap_or_default());
        }
        let mut flags = vec![];
        if self.eat_punct("(") {
            loop {
                if self.at_punct(")") || self.at_eof() {
                    break;
                }
                let e = self.parse_expr();
                flags.push(e);
                if self.eat_punct(",") {
                    continue;
                }
                break;
            }
            if !self.eat_punct(")") {
                self.expected_one_of(&[Exp::Tok(")")]);
            }
        }
        let items = self.parse_yul_block();
        AssemblyBlock {
            span: start.join(self.prev_span()),
            dialect,
            flags,
            items,
        }
    }

    fn parse_yul_block(&mut self) -> Vec<YulItem> {
        if !self.eat_punct("{") {
            return vec![];
        }
        let mut out = vec![];
        loop {
            if self.at_eof() || self.at_punct("}") {
                break;
            }
            if let Some(it) = self.parse_yul_item() {
                out.push(it);
            } else {
                break;
            }
        }
        if !self.eat_punct("}") {
            self.expected_one_of(&[Exp::Tok("}")]);
        }
        out
    }

    fn parse_yul_item(&mut self) -> Option<YulItem> {
        let t = self.cur().clone();
        if t.is_punct("{") {
            let items = self.parse_yul_block();
            return Some(YulItem::Block(items));
        }
        if t.is_kw("let") {
            self.bump();
            let mut idents = vec![];
            loop {
                if self.at_punct(":") {
                    // typed declaration `let x : type`
                    self.bump();
                    let _ty = self.parse_yul_type();
                    continue;
                }
                if matches!(self.cur().kind, TokenKind::Ident | TokenKind::Keyword) {
                    let id = self.eat();
                    idents.push((id.text.clone(), id.span));
                    if self.eat_punct(",") {
                        continue;
                    }
                    break;
                }
                break;
            }
            let mut init = None;
            if self.eat_punct(":=") {
                init = Some(self.parse_yul_expr());
            }
            if !self.eat_punct(";") {
                self.expected_one_of(&[Exp::Tok(";")]);
            }
            return Some(YulItem::Let(idents, init));
        }
        if t.is_kw("if") {
            self.bump();
            let cond = self.parse_yul_expr();
            let body = self.parse_yul_block();
            return Some(YulItem::If(cond, body));
        }
        if t.is_kw("switch") {
            self.bump();
            let subject = self.parse_yul_expr();
            let mut cases = vec![];
            let mut default = None;
            loop {
                if self.at_kw("case") {
                    self.bump();
                    let lit = self.parse_yul_expr();
                    let body = self.parse_yul_block();
                    cases.push((Some(lit), body));
                    continue;
                }
                if self.at_kw("default") {
                    self.bump();
                    let body = self.parse_yul_block();
                    default = Some(body);
                    continue;
                }
                break;
            }
            return Some(YulItem::Switch(subject, cases, default));
        }
        if t.is_kw("function") {
            self.bump();
            let name_tok = self.eat();
            let mut params = vec![];
            if self.eat_punct("(") {
                loop {
                    if self.at_punct(")") || self.at_eof() {
                        break;
                    }
                    let id = self.eat();
                    params.push(id.text.clone());
                    if self.eat_punct(",") {
                        continue;
                    }
                    break;
                }
                if !self.eat_punct(")") {
                    self.expected_one_of(&[Exp::Tok(")")]);
                }
            }
            let mut rets = vec![];
            if self.eat_punct("->") {
                loop {
                    if matches!(self.cur().kind, TokenKind::Ident | TokenKind::Keyword) {
                        let id = self.eat();
                        rets.push(id.text.clone());
                        if self.eat_punct(",") {
                            continue;
                        }
                        break;
                    }
                    break;
                }
            }
            let body = self.parse_yul_block();
            return Some(YulItem::Function(name_tok.text.clone(), params, rets, body));
        }
        if t.is_kw("for") {
            self.bump();
            let init = self.parse_yul_block();
            let cond = self.parse_yul_expr();
            let step = self.parse_yul_block();
            let body = self.parse_yul_block();
            return Some(YulItem::For(init, cond, step, body));
        }
        if matches!(t.kind, TokenKind::Ident | TokenKind::Keyword) {
            let id = self.eat();
            if self.at_punct(",") || self.at_punct(":=") {
                let mut targets = vec![(id.text.clone(), id.span)];
                while self.eat_punct(",") {
                    let id2 = self.eat();
                    targets.push((id2.text.clone(), id2.span));
                }
                if !self.eat_punct(":=") {
                    self.expected_one_of(&[Exp::Tok(":=")]);
                }
                let value = self.parse_yul_expr();
                if !self.eat_punct(";") {
                    self.expected_one_of(&[Exp::Tok(";")]);
                }
                return Some(YulItem::Assign(targets, value));
            }
            let e = self.parse_yul_expr();
            if !self.eat_punct(";") {
                self.expected_one_of(&[Exp::Tok(";")]);
            }
            return Some(YulItem::Expr(e));
        }
        None
    }

    fn parse_yul_type(&mut self) -> String {
        if matches!(self.cur().kind, TokenKind::Ident | TokenKind::Keyword) {
            let t = self.eat();
            t.text
        } else {
            String::new()
        }
    }

    fn parse_yul_expr(&mut self) -> Expr {
        let start = self.span();
        let mut lhs = self.parse_yul_primary();
        loop {
            let t = self.cur().clone();
            if t.is_punct("(") {
                let args = self.parse_call_args();
                lhs = Expr {
                    span: start.join(self.prev_span()),
                    kind: ExprKind::Call(Box::new(lhs), args, vec![]),
                };
                continue;
            }
            if t.is_punct(".") {
                self.bump();
                let n = self.eat();
                lhs = Expr {
                    span: start.join(n.span),
                    kind: ExprKind::Member(Box::new(lhs), (n.text.clone(), n.span)),
                };
                continue;
            }
            if let Some((op, prec, _ra)) = binary_op(&t) {
                if prec < 1 {
                    break;
                }
                self.bump();
                let rhs = self.parse_yul_expr();
                lhs = Expr {
                    span: start.join(self.prev_span()),
                    kind: ExprKind::Binary(op, Box::new(lhs), Box::new(rhs)),
                };
                continue;
            }
            break;
        }
        lhs
    }

    fn parse_yul_primary(&mut self) -> Expr {
        let t = self.cur().clone();
        match t.kind {
            TokenKind::Integer => {
                self.bump();
                Expr { span: t.span, kind: ExprKind::Lit(LitKind::Number(t.text.clone())) }
            }
            TokenKind::HexStr => {
                self.bump();
                Expr { span: t.span, kind: ExprKind::Lit(LitKind::Number(t.text.clone())) }
            }
            TokenKind::Ident | TokenKind::Keyword => {
                self.bump();
                Expr { span: t.span, kind: ExprKind::Ident(t.text.clone()) }
            }
            TokenKind::Punct if t.text == "(" => {
                self.bump();
                let e = self.parse_yul_expr();
                if !self.eat_punct(")") {
                    self.expected_one_of(&[Exp::Tok(")")]);
                }
                e
            }
            _ => {
                self.expected_one_of(&[TOK_IDENT, Exp::Tok("("), Exp::Tok("-")]);
                self.bump();
                Expr { span: t.span, kind: ExprKind::Tuple(vec![]) }
            }
        }
    }
}

fn binary_op(t: &Token) -> Option<(String, u8, bool)> {
    if t.kind != TokenKind::Punct {
        return None;
    }
    let (op, prec, right) = match t.text.as_str() {
        "=" | "+=" | "-=" | "*=" | "/=" | "%=" | "&=" | "|=" | "^=" | "<<=" | ">>=" | ">>>=" => {
            (t.text.clone(), 1, true)
        }
        "||" => (t.text.clone(), 3, false),
        "&&" => (t.text.clone(), 4, false),
        "==" | "!=" => (t.text.clone(), 5, false),
        "<" | ">" | "<=" | ">=" => (t.text.clone(), 6, false),
        "|" => (t.text.clone(), 7, false),
        "^" => (t.text.clone(), 8, false),
        "&" => (t.text.clone(), 9, false),
        "<<" | ">>" | ">>>" => (t.text.clone(), 10, false),
        "+" | "-" => (t.text.clone(), 11, false),
        "*" | "/" | "%" => (t.text.clone(), 12, false),
        "**" => (t.text.clone(), 13, true),
        _ => return None,
    };
    Some((op, prec, right))
}
