//! Lowering: name resolution, inheritance linearization and ABI generation.

use crate::abi::AbiType;
use crate::ast::*;
use crate::diag::{Diag, SpanLabel};
use crate::keccak;
use crate::json::Json;
use crate::span::Span;
use std::collections::{BTreeMap, HashMap};

#[derive(Clone, Debug)]
pub struct StructInfo {
    pub name: String,
    pub qualified: String,
    pub members: Vec<AbiType>,
    pub member_names: Vec<String>,
