#[derive(Clone, Debug)]
pub struct ContractInfo {
    pub file: usize,
    pub span: Span,
    pub name: String,
    pub kind: ContractKind,
    pub own_items: Vec<usize>,
    /// item ids of the contract and all its bases, in linearisation order
    pub all_items: Vec<usize>,
    pub bases: Vec<usize>,
    pub linearized: Vec<usize>,
    pub ctor: Option<usize>,
    pub fallback: Option<usize>,
    pub receive: Option<usize>,
}

#[derive(Clone, Debug)]
pub enum ItemInfo {
    Function {
        contract: Option<usize>,
        span: Span,
        name: Option<String>,
        kind: FunctionKind,
        params: Vec<AbiParam>,
        returns: Vec<AbiParam>,
        visibility: Option<Visibility>,
        mutability: Option<Mutability>,
        virtual_: bool,
        override_: bool,
        has_body: bool,
        sig: Option<String>,
    },
    Event {
        contract: usize,
        span: Span,
        name: String,
        params: Vec<AbiParam>,
        anonymous: bool,
    },
    Error {
        contract: usize,
        span: Span,
        name: String,
        params: Vec<AbiParam>,
    },
    Variable {
        contract: usize,
        span: Span,
        name: String,
        ty: Option<AbiType>,
        visibility: Option<Visibility>,
        mutability: Option<Mutability>,
        constant: bool,
    },
    Struct {
        contract: Option<usize>,
        span: Span,
        name: String,
        members: Vec<AbiType>,
        member_names: Vec<String>,
    },
    Enum {
        contract: Option<usize>,
        span: Span,
        name: String,
        size: usize,
    },
