pub struct Workspace {
    pub units: Vec<SourceUnit>,
    pub contract_names: Vec<Vec<String>>,
    pub items: Vec<ItemInfo>,
    pub contracts: Vec<ContractInfo>,
    /// file level scope: name -> (kind, index)
    pub file_scopes: Vec<HashMap<String, Sym>>,
    /// contract level scope
    pub contract_scopes: Vec<HashMap<String, Sym>>,
    pub aliases: Vec<HashMap<String, usize>>,
    pub diagnostics: Vec<Diag>,
    pub file_for_item: Vec<usize>,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Sym {
    Contract(usize),
    Item(usize),
    File(usize),
    Alias(usize, String),
}

impl Workspace {
    pub fn new(units: Vec<SourceUnit>) -> Workspace {
        Workspace {
            units,
            contract_names: vec![],
            items: vec![],
            contracts: vec![],
            file_scopes: vec![],
            contract_scopes: vec![],
            aliases: vec![],
            diagnostics: vec![],
            file_for_item: vec![],
        }
    }

    /// Collects top level items and contracts.
    pub fn collect(&mut self) {
        for (file, unit) in self.units.clone().iter().enumerate() {
            let mut scope: HashMap<String, Sym> = HashMap::new();
            let mut alias_map: HashMap<String, usize> = HashMap::new();
            let mut names = vec![];
            for item in &unit.items {
                match item {
                    SourceUnitItem::Contract(c) => {
                        let idx = self.items.len();
                        if let ItemKind::Contract {
                            kind,
                            name: (n, nspan),
                            bases,
                            layout: _,
                            body,
                        } = &c.kind
                        {
                            let cid = self.contracts.len();
                            self.contract_names.push(vec![]);
                            let cinfo = ContractInfo {
                                file,
                                span: c.span,
                                name: n.clone(),
                                kind: *kind,
                                own_items: vec![],
                                all_items: vec![],
                                bases: vec![],
                                linearized: vec![],
                                ctor: None,
                                fallback: None,
                                receive: None,
                            };
                            self.contracts.push(cinfo);
                            self.contract_scopes.push(HashMap::new());
                            for (i, b) in bases.iter().enumerate() {
                                let _ = (i, b);
                            }
                            let mut own = vec![];
                            for sub in body {
                                let id = self.add_item(sub, Some(cid), file, n.clone(), nspan.clone());
                                own.push(id);
                            }
                            let ci = &mut self.contracts[cid];
                            ci.own_items = own;
                            for it in &own {
                                let info = &self.items[*it];
                                let n = match info {
                                    ItemInfo::Function { name, .. } => name.clone(),
                                    ItemInfo::Event { name, .. } => Some(name.clone()),
                                    ItemInfo::Error { name, .. } => Some(name.clone()),
                                    ItemInfo::Variable { name, .. } => Some(name.clone()),
                                    ItemInfo::Struct { name, .. } => Some(name.clone()),
                                    ItemInfo::Enum { name, .. } => Some(name.clone()),
                                };
                                let kind = match info {
                                    ItemInfo::Function { .. } => "function",
                                    ItemInfo::Event { .. } => "event",
                                    ItemInfo::Error { .. } => "error",
                                    ItemInfo::Variable { .. } => "variable",
                                    ItemInfo::Struct { .. } => "struct",
                                    ItemInfo::Enum { .. } => "enum",
                                };
                                if let Some(n) = n {
                                    let sc = &mut self.contract_scopes[cid];
                                    match sc.get(&n) {
                                        Some(Sym::Item(other)) if !same_kind(&self.items[*other], &self.items[*it]) => {}
                                        Some(_) => {
                                            let prev = match sc.get(&n) {
                                                Some(Sym::Item(p)) => *p,
                                                _ => 0,
                                            };
                                            let prev_span = item_span(&self.items[prev]);
                                            let cur_span = item_span(&self.items[*it]);
                                            let (primary, secondary, msg) = match info {
                                                ItemInfo::Function { name: Some(_), .. } => (
                                                    cur_span,
                                                    prev_span,
                                                    "function with same name and parameter types declared twice",
                                                ),
                                                ItemInfo::Event { .. } => (
                                                    cur_span,
                                                    prev_span,
                                                    "event with same name and parameter types declared twice",
                                                ),
                                                ItemInfo::Variable { .. }
                                                    if kind == "variable" =>
                                                {
                                                    (
                                                        cur_span,
                                                        prev_span,
                                                        format!("identifier `{n}` already declared"),
                                                    )
                                                }
                                                _ => (cur_span, prev_span, format!("identifier `{n}` already declared")),
                                            };
                                            let note = match info {
                                                ItemInfo::Function { .. } => "other declaration",
                                                ItemInfo::Event { .. } => "other declaration",
                                                _ => "previous declaration declared here",
                                            };
                                            let mut d = Diag::error(msg).with_span(primary);
                                            d.children.push(
                                                Diag::error(note).with_span(secondary),
                                            );
                                            self.diagnostics.push(d);
                                        }
                                        None => {
                                            sc.insert(n.clone(), Sym::Item(*it));
                                        }
                                    }
                                }
                            }
                            scope.insert(
                                n.clone(),
                                Sym::Contract(cid),
                            );
                            names.push(n.clone());
                        }
                    }
                    SourceUnitItem::Struct(it) => {
                        let id = self.add_item(it, None, file, String::new(), None);
                        if let ItemKind::Struct { name: (n, _), .. } = &it.kind {
                            scope.insert(n.clone(), Sym::Item(id));
                        }
                    }
                    SourceUnitItem::Enum(it) => {
                        let id = self.add_item(it, None, file, String::new(), None);
                        if let ItemKind::Enum { name: (n, _), .. } = &it.kind {
                            scope.insert(n.clone(), Sym::Item(id));
                        }
                    }
                    SourceUnitItem::Error(it) => {
                        let id = self.add_item(it, None, file, String::new(), None);
                        if let ItemKind::Error { name: (n, _), .. } = &it.kind {
                            scope.insert(n.clone(), Sym::Item(id));
                        }
                    }
                    SourceUnitItem::UsingFor(it) => {
                        let id = self.add_item(it, None, file, String::new(), None);
                        if let ItemKind::UsingFor { library, .. } = &it.kind {
                            scope.insert(library.to_string(), Sym::Item(id));
                        }
                    }
                    SourceUnitItem::Function(it) => {
                        let id = self.add_item(it, None, file, String::new(), None);
                        if let ItemKind::Function { header, .. } = &it.kind {
                            if let Some((n, _)) = &header.name {
                                scope.insert(n.clone(), Sym::Item(id));
                            }
                        }
                    }
                    SourceUnitItem::Variable(it) => {
                        let id = self.add_item(it, None, file, String::new(), None);
                        if let ItemKind::VariableDefinition { name: Some((n, _)), .. } = &it.kind {
                            scope.insert(n.clone(), Sym::Item(id));
                        }
                    }
                    SourceUnitItem::Import(imp) => {
                        self.handle_import(file, imp, &mut scope, &mut alias_map);
                    }
                    _ => {}
                }
            }
            while self.file_scopes.len() <= file {
                self.file_scopes.push(HashMap::new());
            }
            self.file_scopes[file] = scope;
            while self.aliases.len() <= file {
                self.aliases.push(HashMap::new());
            }
            self.aliases[file] = alias_map;
            while self.contract_names.len() <= file {
                self.contract_names.push(vec![]);
            }
        }
    }

    fn handle_import(
        &mut self,
        file: usize,
        imp: &ImportDirective,
        scope: &mut HashMap<String, Sym>,
        alias_map: &mut HashMap<String, usize>,
    ) {
        if let Some(f) = self.import_file(file, &imp.path) {
            match (&imp.symbol, &imp.alias, imp.symbols.is_empty()) {
                (Some((n, _)), None, true) => {
                    // import "path" as Name
                    if let Some(nm) = self.contracts_file_name(f) {
                        alias_map.insert(n.clone(), f);
                        scope.insert(nm.clone(), Sym::File(f));
                    } else {
                        alias_map.insert(n.clone(), f);
                    }
                }
                (None, None, true) => {
                    // import "path"; bring all symbols
                    for (n, s) in self.file_scopes[f].clone() {
                        if !scope.contains_key(&n) {
                            scope.insert(n, s);
                        }
                    }
                    for (n, s) in self.contract_names[f].clone() {
                        let cid = self.find_contract(f, &s);
                        if let Some(cid) = cid {
                            if !scope.contains_key(&n) {
                                scope.insert(n, Sym::Contract(cid));
                            }
                        }
                    }
                }
                _ => {
                    for ((n, _), alias) in &imp.symbols {
                        let target = alias.as_ref().map(|a| a.0.clone()).unwrap_or_else(|| n.clone());
                        if let Some(cid) = self.find_contract(f, n) {
                            scope.insert(target, Sym::Contract(cid));
                        } else if let Some(s) = self.file_scopes[f].get(n) {
                            scope.insert(target, *s);
                        } else if let Some(s) = self.contract_names[f]
                            .iter()
                            .find(|x| x.0 == *n)
                        {
                            let _ = s;
                        }
                    }
                }
            }
        }
    }

    fn import_file(&self, _file: usize, _path: &str) -> Option<usize> {
        None
    }

    fn contracts_file_name(&self, _f: usize) -> Option<String> {
        None
    }

    fn find_contract(&self, f: usize, name: &str) -> Option<usize> {
        for (i, c) in self.contracts.iter().enumerate() {
            if c.file == f && c.name == name {
                return Some(i);
            }
        }
        let _ = f;
        None
    }

    fn add_item(
        &mut self,
        item: &Item,
        contract: Option<usize>,
        file: usize,
        contract_name: String,
        contract_span: Option<(String, Span)>,
    ) -> usize {
        let idx = self.items.len();
        let info = match &item.kind {
            ItemKind::Contract { name, .. } => {
                let _ = (name, contract_span);
                ItemInfo::Struct {
                    contract,
                    span: item.span,
                    name: String::new(),
                    members: vec![],
                    member_names: vec![],
                }
            }
            ItemKind::Struct { name: (n, _), members } => ItemInfo::Struct {
                contract,
                span: item.span,
                name: n.clone(),
                members: members.iter().map(|m| AbiType::Unknown).collect(),
                member_names: members
                    .iter()
                    .map(|m| m.name.as_ref().map(|(s, _)| s.clone()).unwrap_or_default())
                    .collect(),
            },
            ItemKind::Enum { name: (n, _), variants } => ItemInfo::Enum {
                contract,
                span: item.span,
                name: n.clone(),
                size: variants.len(),
            },
            ItemKind::Error { name: (n, _), params } => ItemInfo::Error {
                contract: contract.unwrap_or(0),
                span: item.span,
                name: n.clone(),
                params: params
                    .iter()
                    .map(|p| AbiParam {
                        name: p.name.as_ref().map(|(s, _)| s.clone()).unwrap_or_default(),
                        ty: AbiType::Unknown,
                        indexed: p.indexed,
                    })
                    .collect(),
            },
            ItemKind::Event {
                name: (n, _),
                params,
                anonymous,
            } => ItemInfo::Event {
                contract: contract.unwrap_or(0),
                span: item.span,
                name: n.clone(),
                params: params
                    .iter()
                    .map(|p| AbiParam {
                        name: p.name.as_ref().map(|(s, _)| s.clone()).unwrap_or_default(),
                        ty: AbiType::Unknown,
                        indexed: p.indexed,
                    })
                    .collect(),
                anonymous: *anonymous,
            },
            ItemKind::Function { kind, header, body } => ItemInfo::Function {
                contract,
                span: item.span,
                name: header.name.as_ref().map(|(s, _)| s.clone()),
                kind: *kind,
                params: header
                    .params
                    .iter()
                    .map(|p| AbiParam {
                        name: p.name.as_ref().map(|(s, _)| s.clone()).unwrap_or_default(),
                        ty: AbiType::Unknown,
                        indexed: false,
                    })
                    .collect(),
                returns: header
                    .returns
                    .iter()
                    .map(|p| AbiParam {
                        name: p.name.as_ref().map(|(s, _)| s.clone()).unwrap_or_default(),
                        ty: AbiType::Unknown,
                        indexed: false,
                    })
                    .collect(),
                visibility: header.visibility,
                mutability: header.mutability,
                virtual_: header.virtual_,
                override_: header.override_.is_some(),
                has_body: matches!(body, Body::Block(_)),
            },
            ItemKind::VariableDefinition {
                span,
                visibility,
                mutability,
                name,
                ..
            } => ItemInfo::Variable {
                contract: contract.unwrap_or(0),
                span: *span,
                name: name.as_ref().map(|(s, _)| s.clone()).unwrap_or_default(),
                ty: Some(AbiType::Unknown),
                visibility: *visibility,
                mutability: *mutability,
                constant: matches!(mutability, Some(Mutability::Constant)),
            },
            ItemKind::UsingFor { .. } => ItemInfo::Enum {
                contract,
                span: item.span,
                name: String::new(),
                size: 0,
            },
            ItemKind::Modifier { .. } => ItemInfo::Function {
                contract,
                span: item.span,
                name: Some(String::new()),
                kind: FunctionKind::Function,
                params: vec![],
                returns: vec![],
                visibility: Some(Visibility::Internal),
                mutability: None,
                virtual_: false,
                override_: false,
                has_body: false,
            },
        };
        let _ = contract_name;
        self.items.push(info);
        self.file_for_item.push(file);
        idx
    }
}

fn item_span(i: &ItemInfo) -> Span {
    match i {
        ItemInfo::Function { span, .. } => *span,
        ItemInfo::Event { span, .. } => *span,
        ItemInfo::Error { span, .. } => *span,
        ItemInfo::Variable { span, .. } => *span,
        ItemInfo::Struct { span, .. } => *span,
        ItemInfo::Enum { span, .. } => *span,
    }
}

fn same_kind(a: &ItemInfo, b: &ItemInfo) -> bool {
    matches!(
        (a, b),
        (ItemInfo::Function { .. }, ItemInfo::Function { .. })
            | (ItemInfo::Event { .. }, ItemInfo::Event { .. })
    )
}

pub fn compute_hashes(entries: &[(String, usize)]) -> BTreeMap<String, String> {
    let mut out = BTreeMap::new();
    for (sig, _) in entries {
        let sel = keccak::selector(sig);
        out.insert(sig.clone(), keccak::hex4(&sel));
    }
    out
}

pub fn abi_to_json(entries: &[Json]) -> Json {
    Json::Array(entries.to_vec())
}

pub fn err(msg: impl Into<String>, span: Span) -> Diag {
    Diag::error(msg).with_span(span)
}

pub fn label_of(s: &SpanLabel) -> &Option<String> {
    &s.label
}
