//! Lowering: collects declarations, resolves names and prepares the ABI.

use crate::abi::AbiType;
use crate::ast::*;
use crate::diag::Diag;
use crate::span::Span;
use std::collections::HashMap;

#[derive(Clone, Debug)]
pub struct ContractDecl {
    pub file: usize,
    pub item: usize,
    pub name: String,
    pub kind: ContractKind,
    pub span: Span,
    pub own: Vec<usize>,
    pub bases: Vec<usize>,
    pub linearized: Vec<usize>,
    pub ctor: Option<usize>,
    pub fallback: Option<usize>,
    pub receive: Option<usize>,
}

pub struct Global {
    pub units: Vec<SourceUnit>,
    /// flat list of items: (file, index in unit.items)
    pub items: Vec<(usize, usize)>,
    pub item_contract: Vec<Option<usize>>,
    pub contracts: Vec<ContractDecl>,
    pub contract_scope: Vec<HashMap<String, usize>>,
    pub file_scope: Vec<HashMap<String, usize>>,
    pub file_contract: Vec<HashMap<String, usize>>,
    pub aliases: Vec<HashMap<String, usize>>,
    pub imports: Vec<Vec<usize>>,
    pub struct_resolved: HashMap<usize, Option<Vec<AbiType>>>,
    pub diagnostics: Vec<Diag>,
    /// maps item id -> contract id when the item belongs to a contract
    pub contract_of_item: Vec<Option<usize>>,
}

impl Global {
    pub fn new(units: Vec<SourceUnit>) -> Global {
        Global {
            units,
            items: vec![],
            item_contract: vec![],
            contracts: vec![],
            contract_scope: vec![],
            file_scope: vec![],
            file_contract: vec![],
            aliases: vec![],
            imports: vec![],
            struct_resolved: HashMap::new(),
            diagnostics: vec![],
            contract_of_item: vec![],
        }
    }

    pub fn item_ast(&self, id: usize) -> &Item {
        let (f, i) = self.items[id];
        &self.units[f].items[i]
    }

    pub fn item_file(&self, id: usize) -> usize {
        self.items[id].0
    }

    pub fn add_file(&mut self, file: usize) {
        while self.file_scope.len() <= file {
            self.file_scope.push(HashMap::new());
            self.file_contract.push(HashMap::new());
            self.aliases.push(HashMap::new());
            self.imports.push(vec![]);
        }
    }

    /// Collects all declarations of a single file.
    pub fn collect_file(&mut self, file: usize) {
        self.add_file(file);
        let mut scope: HashMap<String, usize> = HashMap::new();
        let mut cscope: HashMap<String, usize> = HashMap::new();
        let mut aliases: HashMap<String, usize> = HashMap::new();
        let mut imports: Vec<usize> = vec![];
        let items: Vec<Item> = self.units[file].items.clone();
        for (idx, item) in items.iter().enumerate() {
            let id = self.push_item(file, idx, None);
            match &item.kind {
                ItemKind::Contract {
                    kind,
                    name: (n, _),
                    body,
                    ..
                } => {
                    let cid = self.contracts.len();
                    let own_start = self.items.len();
                    for sub in body {
                        let sid = self.push_item(file, usize::MAX, Some(cid));
                        let _ = sid;
                    }
                    let own: Vec<usize> = (own_start..self.items.len()).collect();
                    for (j, sub) in body.iter().enumerate() {
                        let sid = own[j];
                        self.fill_item_ast(sid, file, sub);
                        let scname = match &sub.kind {
                            ItemKind::Function { header, .. } => {
                                header.name.as_ref().map(|(s, _)| s.clone())
                            }
                            ItemKind::Constructor { .. } => None,
                            ItemKind::Fallback { .. } => None,
                            ItemKind::Receive { .. } => None,
