//! Lowering: collects declarations, resolves names and inheritance.

use crate::abi::AbiType;
use crate::ast::*;
use crate::diag::Diag;
use crate::span::Span;
use std::collections::HashMap;

#[derive(Clone, Debug)]
pub enum DeclKind {
    Contract(usize),
    Struct(Vec<(String, Type)>),
    Enum(usize),
    Error(Vec<Param>),
    Event(Vec<Param>, bool),
    Function(FunctionHeader, Body),
    Variable(Type, Option<Visibility>, Option<Mutability>, Option<Expr>),
    UsingFor(Path, Option<Type>),
    Modifier(FunctionHeader, Body),
    FreeFunction(FunctionHeader, Body),
}

#[derive(Clone, Debug)]
pub struct Decl {
    pub file: usize,
    pub contract: Option<usize>,
    pub name: String,
    pub span: Span,
    pub kind: DeclKind,
}

#[derive(Clone, Debug)]
pub struct ContractDecl {
    pub file: usize,
    pub name: String,
    pub kind: ContractKind,
    pub span: Span,
    pub decl: usize,
    pub own: Vec<usize>,
    pub bases: Vec<usize>,
    pub linearized: Vec<usize>,
    pub ctor: Option<usize>,
    pub fallback: Option<usize>,
    pub receive: Option<usize>,
    pub scope: HashMap<String, usize>,
}

pub struct Global {
    pub units: Vec<SourceUnit>,
    pub decls: Vec<Decl>,
    pub contracts: Vec<ContractDecl>,
    pub contract_scope: Vec<HashMap<String, usize>>,
    pub file_scope: Vec<HashMap<String, usize>>,
    pub file_contract: Vec<HashMap<String, usize>>,
    pub aliases: Vec<HashMap<String, usize>>,
    pub imports: Vec<Vec<usize>>,
    pub diagnostics: Vec<Diag>,
    /// (file, contract index) -> (item index) -> decl id
    pub resolved_types: HashMap<usize, Option<AbiType>>,
}

impl Global {
    pub fn new(units: Vec<SourceUnit>) -> Global {
        Global {
            units,
            decls: vec![],
            contracts: vec![],
            contract_scope: vec![],
            file_scope: vec![],
            file_contract: vec![],
            aliases: vec![],
            imports: vec![],
            diagnostics: vec![],
            resolved_types: HashMap::new(),
        }
    }

    fn add_file(&mut self, file: usize) {
        while self.file_scope.len() <= file {
            self.file_scope.push(HashMap::new());
            self.file_contract.push(HashMap::new());
            self.aliases.push(HashMap::new());
            self.imports.push(vec![]);
        }
    }

    pub fn decl(&self, id: usize) -> &Decl {
        &self.decls[id]
    }

    /// Registers all declarations of a file.
    pub fn collect_file(&mut self, file: usize) {
        self.add_file(file);
        let items: Vec<Item> = self.units[file].items.clone();
        let mut scope: HashMap<String, usize> = HashMap::new();
        let mut cscope: HashMap<String, usize> = HashMap::new();
        for item in &items {
            match &item.kind {
                SourceUnitItem::Pragma(_) | SourceUnitItem::Import(_) => {}
                SourceUnitItem::Contract(c) => {
                    if let ItemKind::Contract {
                        kind,
                        name: (n, _),
                        bases,
                        body,
                        ..
                    } = &c.kind
                    {
                        let cid = self.contracts.len();
                        let decl_id = self.push(Decl {
                            file,
                            contract: None,
                            name: n.clone(),
                            span: c.span,
                            kind: DeclKind::Contract(cid),
                        });
                        let own_start = self.decls.len();
                        let mut own = vec![];
                        let mut c_local: HashMap<String, usize> = HashMap::new();
                        for sub in body {
                            let (dname, dkind) = match &sub.kind {
                                ItemKind::Function { header, body } => (
                                    header.name.as_ref().map(|(s, _)| s.clone()),
                                    DeclKind::Function(header.clone(), body.clone()),
                                ),
                                ItemKind::VariableDefinition {
                                    ty,
                                    visibility,
                                    mutability,
                                    name,
                                    initializer,
                                    ..
                                } => (
                                    name.as_ref().map(|(s, _)| s.clone()),
                                    DeclKind::Variable(
                                        ty.clone(),
                                        *visibility,
                                        *mutability,
                                        initializer.clone(),
                                    ),
                                ),
                                ItemKind::Struct { name: (s, _), members } => (
                                    Some(s.clone()),
                                    DeclKind::Struct(
                                        members
                                            .iter()
                                            .map(|m| {
                                                (
                                                    m.name
                                                        .as_ref()
                                                        .map(|(x, _)| x.clone())
                                                        .unwrap_or_default(),
                                                    m.ty.clone().unwrap_or(Type {
                                                        span: crate::span::DUMMY,
                                                        kind: TypeKind::Elementary(
                                                            ElementaryType::Uint(256),
                                                        ),
                                                    }),
                                                )
                                            })
                                            .collect(),
                                    ),
                                ),
                                ItemKind::Enum { name: (s, _), variants } => {
                                    (Some(s.clone()), DeclKind::Enum(variants.len()))
                                }
                                ItemKind::Error { name: (s, _), params } => {
                                    (Some(s.clone()), DeclKind::Error(params.clone()))
                                }
                                ItemKind::Event {
                                    name: (s, _),
                                    params,
                                    anonymous,
                                } => (Some(s.clone()), DeclKind::Event(params.clone(), *anonymous)),
                                ItemKind::UsingFor { library, ty, .. } => {
                                    (Some(library.to_string()), DeclKind::UsingFor(library.clone(), ty.clone()))
                                }
                                ItemKind::Modifier {
                                    name: (s, _),
                                    params,
                                    body,
                                    ..
                                } => {
                                    let h = FunctionHeader {
                                        span: sub.span,
                                        name: Some((s.clone(), crate::span::DUMMY)),
                                        params: params.clone(),
                                        returns: vec![],
                                        visibility: None,
                                        mutability: None,
                                        virtual_: false,
                                        override_: None,
                                        modifiers: vec![],
                                    };
                                    (Some(s.clone()), DeclKind::Modifier(h, body.clone()))
                                }
                                ItemKind::Contract { .. } => (None, DeclKind::Enum(0)),
                            };
                            let span = sub.span;
                            let d = Decl {
                                file,
                                contract: Some(cid),
                                name: dname.clone().unwrap_or_default(),
                                span,
                                kind: dkind,
                            };
                            let id = self.push(d);
                            own.push(id);
                            if let Some(nm) = dname {
                                match c_local.get(&nm) {
                                    Some(&prev) => {
                                        let prev_span = self.decls[prev].span;
                                        let cur_span = span;
                                        let (msg, note) = match &sub.kind {
                                            ItemKind::Function { .. } => (
                                                "function with same name and parameter types declared twice",
                                                "other declaration",
                                            ),
                                            ItemKind::Event { .. } => (
                                                "event with same name and parameter types declared twice",
                                                "other declaration",
                                            ),
                                            _ => (
                                                &format!("identifier `{nm}` already declared")[..],
                                                "previous declaration declared here",
                                            ),
                                        };
                                        let mut dg = Diag::error(msg).with_span(cur_span);
                                        dg.children
                                            .push(Diag::error(note).with_span(prev_span));
                                        self.diagnostics.push(dg);
                                    }
                                    None => {
                                        c_local.insert(nm.clone(), id);
                                    }
                                }
                            }
                        }
                        self.contract_scope.push(c_local.clone());
                        self.contracts.push(ContractDecl {
                            file,
                            name: n.clone(),
                            kind: *kind,
                            span: c.span,
                            decl: decl_id,
                            own,
                            bases: vec![],
                            linearized: vec![],
                            ctor: None,
                            fallback: None,
                            receive: None,
                            scope: c_local,
                        });
                        cscope.insert(n.clone(), cid);
                        scope.insert(n.clone(), decl_id);
                    }
                }
                SourceUnitItem::Struct(it) => {
                    if let ItemKind::Struct { name: (n, _), members } = &it.kind {
                        let id = self.push(Decl {
                            file,
                            contract: None,
                            name: n.clone(),
                            span: it.span,
                            kind: DeclKind::Struct(
                                members
                                    .iter()
                                    .map(|m| {
                                        (
                                            m.name.as_ref().map(|(x, _)| x.clone()).unwrap_or_default(),
                                            m.ty.clone().unwrap_or(Type {
                                                span: crate::span::DUMMY,
                                                kind: TypeKind::Elementary(ElementaryType::Uint(256)),
                                            }),
                                        )
                                    })
                                    .collect(),
                            ),
                        });
                        scope.insert(n.clone(), id);
                    }
                }
                SourceUnitItem::Enum(it) => {
                    if let ItemKind::Enum { name: (n, _), variants } = &it.kind {
                        let id = self.push(Decl {
                            file,
                            contract: None,
                            name: n.clone(),
                            span: it.span,
                            kind: DeclKind::Enum(variants.len()),
                        });
                        scope.insert(n.clone(), id);
                    }
                }
                SourceUnitItem::Error(it) => {
                    if let ItemKind::Error { name: (n, _), params } = &it.kind {
                        let id = self.push(Decl {
                            file,
                            contract: None,
                            name: n.clone(),
                            span: it.span,
                            kind: DeclKind::Error(params.clone()),
                        });
                        scope.insert(n.clone(), id);
                    }
                }
                SourceUnitItem::UsingFor(it) => {
                    if let ItemKind::UsingFor { library, ty, .. } = &it.kind {
                        let id = self.push(Decl {
                            file,
                            contract: None,
                            name: library.to_string(),
                            span: it.span,
                            kind: DeclKind::UsingFor(library.clone(), ty.clone()),
                        });
                        scope.insert(library.to_string(), id);
                    }
                }
                SourceUnitItem::Function(it) => {
                    if let ItemKind::Function { header, body } = &it.kind {
                        let name = header.name.as_ref().map(|(s, _)| s.clone()).unwrap_or_default();
                        let id = self.push(Decl {
                            file,
                            contract: None,
                            name: name.clone(),
                            span: it.span,
                            kind: DeclKind::FreeFunction(header.clone(), body.clone()),
                        });
                        if !name.is_empty() {
                            scope.insert(name, id);
                        }
                    }
                }
                SourceUnitItem::Variable(it) => {
                    if let ItemKind::VariableDefinition {
                        ty,
                        visibility,
                        mutability,
                        name: Some((n, _)),
                        initializer,
                        ..
                    } = &it.kind
                    {
                        let id = self.push(Decl {
                            file,
                            contract: None,
                            name: n.clone(),
                            span: it.span,
                            kind: DeclKind::Variable(ty.clone(), *visibility, *mutability, initializer.clone()),
                        });
                        scope.insert(n.clone(), id);
                    }
                }
            }
        }
        self.file_scope[file] = scope;
        self.file_contract[file] = cscope;
    }

    fn push(&mut self, d: Decl) -> usize {
        self.decls.push(d);
        self.decls.len() - 1
    }

    /// Resolves base contracts and linearises them.
    pub fn resolve_bases(&mut self) {
        let n = self.contracts.len();
        for cid in 0..n {
            let (file, item_id) = {
                let c = &self.contracts[cid];
                (c.file, c.decl)
            };
            let bases: Vec<(String, Span)> = match &self.units[file].items[..] {
                _ => {
                    let mut out = vec![];
                    for item in &self.units[file].items {
                        if let SourceUnitItem::Contract(c) = item {
                            if c.span == self.contracts[cid].span {
                                if let ItemKind::Contract { bases, .. } = &c.kind {
                                    for b in bases {
                                        out.push((b.path.to_string(), b.path.idents[0].1));
                                    }
                                }
                                break;
                            }
                        }
                    }
                    let _ = item_id;
                    out
                }
            };
            for (name, span) in bases {
                match self.lookup_contract(file, &name, Some(cid)) {
                    Some(b) => self.contracts[cid].bases.push(b),
                    None => {
                        self.diagnostics.push(
                            Diag::error(format!("unresolved symbol `{name}`")).with_span(span),
                        );
                    }
                }
            }
        }
        // C3 linearisation
        for cid in 0..n {
            let lin = self.linearize(cid);
            self.contracts[cid].linearized = lin;
        }
    }

    fn linearize(&self, cid: usize) -> Vec<usize> {
        let bases = self.contracts[cid].bases.clone();
        let mut lists: Vec<Vec<usize>> = vec![];
        for &b in &bases {
            lists.push(self.linearize_rec(b));
        }
        lists.push(bases.clone());
        lists.push(vec![cid]);
        c3_merge(lists)
    }

    fn linearize_rec(&self, cid: usize) -> Vec<usize> {
        if !self.contracts[cid].linearized.is_empty() {
            return self.contracts[cid].linearized.clone();
        }
        let bases = self.contracts[cid].bases.clone();
        let mut lists: Vec<Vec<usize>> = vec![];
        for &b in &bases {
            lists.push(self.linearize_rec(b));
        }
        lists.push(bases);
        lists.push(vec![cid]);
        c3_merge(lists)
    }

    pub fn lookup_contract(&self, file: usize, name: &str, _from: Option<usize>) -> Option<usize> {
        if let Some(&cid) = self.file_contract.get(file).and_then(|m| m.get(name)) {
            if cid != usize::MAX {
                return Some(cid);
            }
        }
        // imported files
        let mut seen: Vec<usize> = vec![file];
        let mut queue = self.imports.get(file).cloned().unwrap_or_default();
        while let Some(f) = queue.pop() {
            if seen.contains(&f) {
                continue;
            }
            seen.push(f);
            if let Some(&cid) = self.file_contract.get(f).and_then(|m| m.get(name)) {
                if cid != usize::MAX {
                    return Some(cid);
                }
            }
            queue.extend(self.imports.get(f).cloned().unwrap_or_default());
        }
        None
    }
}

fn c3_merge(mut lists: Vec<Vec<usize>>) -> Vec<usize> {
    let mut out: Vec<usize> = vec![];
    loop {
        lists.retain(|l| !l.is_empty());
        if lists.is_empty() {
            break;
        }
        let mut candidate: Option<usize> = None;
        for l in &lists {
            let head = l[0];
            let mut in_tail = false;
            for other in &lists {
                if other.len() > 1 && other[1..].contains(&head) {
                    in_tail = true;
                    break;
                }
            }
            if !in_tail {
                candidate = Some(head);
                break;
            }
        }
        let Some(c) = candidate else {
            // cycles: just take the first head
            let c = lists[0][0];
            out.push(c);
            for l in &mut lists {
                l.retain(|&x| x != c);
            }
            continue;
        };
        if !out.contains(&c) {
            out.push(c);
        }
        for l in &mut lists {
            l.retain(|&x| x != c);
        }
    }
    out
}

/// Resolves a type expression to an ABI type.
pub struct Resolver<'a> {
    pub g: &'a mut Global,
}

impl<'a> Resolver<'a> {
    pub fn resolve_type(&mut self, ty: &Type, file: usize, contract: Option<usize>) -> Option<AbiType> {
        match &ty.kind {
            TypeKind::Elementary(e) => Some(AbiType::Elementary(*e)),
            TypeKind::UserDefined(path) => self.resolve_path(path, file, contract),
            TypeKind::Mapping(k, v) => {
                let kt = self.resolve_type(k, file, contract)?;
                let vt = self.resolve_type(v, file, contract)?;
                Some(AbiType::Mapping(Box::new(kt), Box::new(vt)))
            }
            TypeKind::Array(elem, size) => {
                let et = self.resolve_type(elem, file, contract)?;
                let len = size.as_ref().and_then(|e| eval_const(e));
                Some(AbiType::Array(Box::new(et), len))
            }
            TypeKind::Function(params, rets, vis, mut_) => {
                let ps: Option<Vec<AbiType>> = params
                    .iter()
                    .map(|p| p.ty.as_ref().and_then(|t| self.resolve_type(t, file, contract)))
                    .collect();
                let rs: Option<Vec<AbiType>> = rets
                    .iter()
                    .map(|p| p.ty.as_ref().and_then(|t| self.resolve_type(t, file, contract)))
                    .collect();
                Some(AbiType::Function {
                    params: ps?,
                    rets: rs?,
                    vis: *vis,
                    mut_: *mut_,
                })
            }
        }
    }

    pub fn resolve_path(&mut self, path: &Path, file: usize, contract: Option<usize>) -> Option<AbiType> {
        let first = &path.idents[0].0;
        // contract member lookup
        if path.idents.len() > 1 {
            if let Some(c) = self.g.lookup_contract(file, first, contract) {
                let mut cur = c;
                for (i, (_, sp)) in path.idents.iter().enumerate().skip(1) {
                    let name = &path.idents[i].0;
                    let _ = sp;
                    match self.g.contract_scope.get(cur).and_then(|m| m.get(name)) {
                        Some(&d) => {
                            let kind = std::mem::discriminant(&self.g.decls[d].kind);
                            let is_contract = matches!(self.g.decls[d].kind, DeclKind::Contract(_));
                            if i + 1 < path.idents.len() {
                                if is_contract {
                                    cur = match &self.g.decls[d].kind {
                                        DeclKind::Contract(c) => *c,
                                        _ => cur,
                                    };
                                } else {
                                    let q = match &self.g.decls[d].kind {
                                        DeclKind::Struct(_) => "struct",
                                        DeclKind::Enum(_) => "enum",
                                        _ => "type",
                                    };
                                    self.g.diagnostics.push(Diag::error(format!(
                                        "`{name}` is a {q}, which cannot be indexed in type paths"
                                    ))
                                    .with_span(*sp));
                                    return None;
                                }
                            } else {
                                let _ = kind;
                                return self.decl_to_type(d, *sp);
                            }
                        }
                        None => {
                            self.g.diagnostics.push(
                                Diag::error(format!("unresolved symbol `{name}`")).with_span(*sp),
                            );
                            return None;
                        }
                    }
                }
                return None;
            }
            // alias lookup
            if let Some(&f) = self.g.aliases.get(file).and_then(|m| m.get(first)) {
                let mut cur_file = f;
                for i in 1..path.idents.len() {
                    let name = &path.idents[i].0;
                    let sp = path.idents[i].1;
                    if let Some(&d) = self.g.file_scope.get(cur_file).and_then(|m| m.get(name)) {
                        if i + 1 < path.idents.len() {
                            if let DeclKind::Contract(c) = self.g.decls[d].kind {
                                cur_file = self.g.contracts[c].file;
                                // member lookup in that contract
                                if let Some(&d2) =
                                    self.g.contract_scope.get(c).and_then(|m| m.get(&path.idents[i + 1].0))
                                {
                                    return self.decl_to_type(d2, path.idents[i + 1].1);
                                }
                                return None;
                            }
                        } else {
                            return self.decl_to_type(d, sp);
                        }
                    }
                }
                return None;
            }
            self.g
                .diagnostics
                .push(Diag::error(format!("unresolved symbol `{first}`"))
                    .with_span(path.idents[0].1));
            return None;
        }
        // single ident
        if let Some(c) = contract {
            if let Some(&d) = self.g.contract_scope.get(c).and_then(|m| m.get(first)) {
                return self.decl_to_type(d, path.idents[0].1);
            }
        }
        if let Some(&d) = self.g.file_scope.get(file).and_then(|m| m.get(first)) {
            if let DeclKind::Contract(c) = self.g.decls[d].kind {
                return Some(AbiType::Contract(c));
            }
            return self.decl_to_type(d, path.idents[0].1);
        }
        // imported files (wildcard imports)
        let files = self.g.imports.get(file).cloned().unwrap_or_default();
        for f in files {
            if let Some(&d) = self.g.file_scope.get(f).and_then(|m| m.get(first)) {
                if let DeclKind::Contract(c) = self.g.decls[d].kind {
                    return Some(AbiType::Contract(c));
                }
                return self.decl_to_type(d, path.idents[0].1);
            }
        }
        self.g
            .diagnostics
            .push(Diag::error(format!("unresolved symbol `{first}`")).with_span(path.idents[0].1));
        None
    }

    fn decl_to_type(&mut self, d: usize, span: Span) -> Option<AbiType> {
        match &self.g.decls[d].kind {
            DeclKind::Contract(_) => Some(AbiType::Contract(d)),
            DeclKind::Struct(_) => Some(AbiType::Tuple(d)),
            DeclKind::Enum(_) => Some(AbiType::Enum(d)),
            DeclKind::UsingFor(_, _) => Some(AbiType::Unknown),
            DeclKind::Function(..) | DeclKind::FreeFunction(..) | DeclKind::Modifier(..) => {
                self.g
                    .diagnostics
                    .push(Diag::error(format!("unresolved symbol `{}`", self.g.decls[d].name))
                        .with_span(span));
                None
            }
            _ => {
                self.g
                    .diagnostics
                    .push(Diag::error(format!("unresolved symbol `{}`", self.g.decls[d].name))
                        .with_span(span));
                None
            }
        }
    }
}

pub fn eval_const(e: &Expr) -> Option<u64> {
    match &e.kind {
        ExprKind::Lit(LitKind::Number(s)) => {
            let s: String = s.chars().filter(|c| *c != '_').collect();
            if let Some(hex) = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
                u64::from_str_radix(hex, 16).ok()
            } else {
                s.parse::<u64>().ok()
            }
        }
        ExprKind::Lit(LitKind::Bool(b)) => Some(*b as u64),
        ExprKind::Lit(LitKind::Str(_)) => None,
        ExprKind::Lit(LitKind::Address(_)) => None,
        ExprKind::Lit(LitKind::Rational(s)) => s.split('.').next()?.parse::<u64>().ok(),
        ExprKind::Unary(op, e, _) => {
            let v = eval_const(e)?;
            match op.as_str() {
                "-" => Some((!(v as i64).wrapping_add(1)) as u64),
                "~" => Some(!v),
                "+" => Some(v),
                _ => None,
            }
        }
        ExprKind::Binary(op, a, b) => {
            let x = eval_const(a)?;
            let y = eval_const(b)?;
            match op.as_str() {
                "+" => Some(x.wrapping_add(y)),
                "-" => Some(x.wrapping_sub(y)),
                "*" => Some(x.wrapping_mul(y)),
                "/" => if y == 0 { None } else { Some(x / y) },
                "%" => if y == 0 { None } else { Some(x % y) },
                "**" => Some(x.pow(y.min(63) as u32)),
                "<<" => Some(x << y.min(63)),
                ">>" => Some(x >> y.min(63)),
                "&" => Some(x & y),
                "|" => Some(x | y),
                "^" => Some(x ^ y),
                _ => None,
            }
        }
        ExprKind::Tuple(items) => {
            if items.len() == 1 {
                items[0].as_ref().and_then(eval_const)
            } else {
                None
            }
        }
        ExprKind::Path(_) | ExprKind::Ident(_) => None,
        _ => None,
    }
}
RSEOF
echo ok"}

