//! ABI type representation and JSON generation.

use crate::ast::{ElementaryType, Mutability, Visibility};

#[derive(Clone, Debug, PartialEq)]
pub enum AbiType {
    Elementary(ElementaryType),
    Array(Box<AbiType>, Option<u64>),
    Mapping(Box<AbiType>, Box<AbiType>),
    Tuple(usize),
    Contract(usize),
    Enum(usize),
    Function {
        params: Vec<AbiType>,
        rets: Vec<AbiType>,
        vis: Option<Visibility>,
        mut_: Option<Mutability>,
    },
    Unknown,
}

impl AbiType {
    pub fn is_dynamic(&self) -> bool {
        match self {
            AbiType::Elementary(ElementaryType::Bytes) | AbiType::Elementary(ElementaryType::String) => true,
            AbiType::Array(_, None) => true,
            AbiType::Array(e, Some(_)) => e.is_dynamic(),
            AbiType::Mapping(_, _) => true,
            AbiType::Tuple(_) => true,
            AbiType::Function { .. } => true,
            _ => false,
        }
    }
}

pub fn elementary_canonical(e: ElementaryType) -> String {
    match e {
        ElementaryType::Address(_) => "address".to_string(),
        ElementaryType::Bool => "bool".to_string(),
        ElementaryType::String => "string".to_string(),
        ElementaryType::Bytes => "bytes".to_string(),
        ElementaryType::Uint(n) => format!("uint{}", if n == 0 { 256 } else { n }),
        ElementaryType::Int(n) => format!("int{}", if n == 0 { 256 } else { n }),
        ElementaryType::BytesN(n) => format!("bytes{}", n),
        ElementaryType::UFixed(m, n) => format!("ufixed{}x{}", m, n),
        ElementaryType::Fixed(m, n) => format!("fixed{}x{}", m, n),
    }
}

pub fn elementary_internal(e: ElementaryType) -> String {
    match e {
        ElementaryType::Address(true) => "address payable".to_string(),
        ElementaryType::Address(false) => "address".to_string(),
        ElementaryType::Bool => "bool".to_string(),
        ElementaryType::String => "string".to_string(),
        ElementaryType::Bytes => "bytes".to_string(),
        ElementaryType::Uint(n) => format!("uint{}", if n == 0 { 256 } else { n }),
        ElementaryType::Int(n) => format!("int{}", if n == 0 { 256 } else { n }),
        ElementaryType::BytesN(n) => format!("bytes{}", n),
        ElementaryType::UFixed(m, n) => format!("ufixed{}x{}", m, n),
        ElementaryType::Fixed(m, n) => format!("fixed{}x{}", m, n),
    }
}

pub fn canonical(t: &AbiType, ctx: &TypeCtx) -> String {
    match t {
        AbiType::Elementary(e) => elementary_canonical(*e),
        AbiType::Array(e, len) => match len {
            Some(l) => format!("{}[{}]", canonical(e, ctx), l),
            None => format!("{}[]", canonical(e, ctx)),
        },
        AbiType::Mapping(k, v) => format!("mapping({} => {})", canonical(k, ctx), canonical(v, ctx)),
        AbiType::Tuple(_) => "tuple".to_string(),
        AbiType::Contract(_) => "address".to_string(),
        AbiType::Enum(_) => "uint8".to_string(),
        AbiType::Function { .. } => "function".to_string(),
        AbiType::Unknown => "unknown".to_string(),
    }
}

pub fn internal(t: &AbiType, ctx: &TypeCtx) -> String {
    match t {
        AbiType::Elementary(e) => elementary_internal(*e),
        AbiType::Array(e, len) => match len {
            Some(l) => format!("{}[{}]", internal(e, ctx), l),
            None => format!("{}[]", internal(e, ctx)),
        },
        AbiType::Mapping(k, v) => format!("mapping({} => {})", internal(k, ctx), internal(v, ctx)),
        AbiType::Tuple(d) => format!("struct {}", ctx.qualified(*d)),
        AbiType::Contract(d) => format!("contract {}", ctx.qualified(*d)),
        AbiType::Enum(d) => format!("enum {}", ctx.qualified(*d)),
        AbiType::Function { params, rets, vis, mut_ } => {
            let mut s = format!("function ({})", params.iter().map(|p| internal(p, ctx)).collect::<Vec<_>>().join(","));
            if let Some(m) = mut_ {
                s.push(' ');
                s.push_str(m.as_str());
            }
            if let Some(v) = vis {
                s.push(' ');
                s.push_str(v.as_str());
            }
            if !rets.is_empty() {
                s.push_str(" returns (");
                s.push_str(&rets.iter().map(|p| internal(p, ctx)).collect::<Vec<_>>().join(","));
                s.push(')');
            }
            s
        }
        AbiType::Unknown => "unknown".to_string(),
    }
}

/// Context needed to render internal types.
pub struct TypeCtx<'a> {
    pub structs: &'a std::collections::HashMap<usize, (String, Vec<(String, Option<AbiType>)>)>,
}

impl<'a> TypeCtx<'a> {
    pub fn qualified(&self, d: usize) -> String {
        self.structs
            .get(&d)
            .map(|(q, _)| q.clone())
            .unwrap_or_default()
    }
}

pub fn abi_param_json(
    name: &str,
    ty: &AbiType,
    indexed: Option<bool>,
    ctx: &TypeCtx,
    structs: &std::collections::HashMap<usize, (String, Vec<(String, Option<AbiType>)>)>,
) -> crate::json::Json {
    use crate::json::Json;
    let mut o = Json::obj();
    o.set("name", Json::Str(name.to_string()));
    o.set("type", Json::Str(canonical(ty, ctx)));
    if let Some(ix) = indexed {
        o.set("indexed", Json::Bool(ix));
    }
    o.set("internalType", Json::Str(internal(ty, ctx)));
    if let AbiType::Tuple(d) = ty {
        if let Some((_, members)) = structs.get(d) {
            let comps: Vec<Json> = members
                .iter()
                .map(|(n, t)| {
                    let t = t.clone().unwrap_or(AbiType::Unknown);
                    abi_param_json(n, &t, None, ctx, structs)
                })
                .collect();
            o.set("components", Json::Array(comps));
        }
    }
    o
}
