{"command": "cat > src/lower.rs <<'RSEOF'
//! Lowering: collects declarations, resolves names, inheritance and builds the ABI.

use crate::abi::{self, AbiType, TypeCtx};
use crate::ast::*;
use crate::diag::Diag;
use crate::json::Json;
use crate::span::{DUMMY, Span};
use std::collections::{BTreeMap, HashMap};

#[derive(Clone, Debug)]
pub enum DeclKind {
    Contract(usize),
    Struct(Vec<(String, Type)>),
    Enum(usize),
    Error(Vec<Param>),
    Event(Vec<Param>, bool),
    Function(FunctionKind, FunctionHeader, Body),
    Variable(Type, Option<Visibility>, Option<Mutability>, Option<Expr>),
    UsingFor(Path, Option<Type>),
    Modifier(FunctionHeader, Body),
}

#[derive(Clone, Debug)]
pub struct Decl {
    pub file: usize,
    pub contract: Option<usize>,
    pub name: String,
    pub span: Span,
    pub kind: DeclKind,
}

#[derive(Clone, Debug)]
pub struct ContractDecl {
    pub file: usize,
    pub name: String,
    pub kind: ContractKind,
    pub span: Span,
    pub decl: usize,
    pub own: Vec<usize>,
    pub bases: Vec<usize>,
    pub linearized: Vec<usize>,
    pub ctor: Option<usize>,
    pub fallback: Option<usize>,
    pub receive: Option<usize>,
    pub scope: HashMap<String, usize>,
}

pub struct Global {
    pub units: Vec<SourceUnit>,
    pub decls: Vec<Decl>,
    pub contracts: Vec<ContractDecl>,
    pub contract_scope: Vec<HashMap<String, usize>>,
    pub file_scope: Vec<HashMap<String, usize>>,
    pub file_contract: Vec<HashMap<String, usize>>,
    pub alias_map: Vec<HashMap<String, usize>>,
    pub import_targets: Vec<Vec<usize>>,
    pub diagnostics: Vec<Diag>,
    pub qualified: HashMap<usize, String>,
    /// resolved abi types for struct members, keyed by decl id
    pub struct_types: HashMap<usize, Vec<AbiType>>,
}

impl Global {
    pub fn new(units: Vec<SourceUnit>) -> Global {
        Global {
            units,
            decls: vec![],
            contracts: vec![],
            contract_scope: vec![],
            file_scope: vec![],
            file_contract: vec![],
            alias_map: vec![],
            import_targets: vec![],
            diagnostics: vec![],
            qualified: HashMap::new(),
            struct_types: HashMap::new(),
        }
    }

    fn add_file(&mut self, file: usize) {
        while self.file_scope.len() <= file {
            self.file_scope.push(HashMap::new());
            self.file_contract.push(HashMap::new());
            self.alias_map.push(HashMap::new());
            self.import_targets.push(vec![]);
        }
    }

    pub fn push_decl(&mut self, d: Decl) -> usize {
        self.decls.push(d);
        self.decls.len() - 1
    }

    pub fn decl(&self, id: usize) -> &Decl {
        &self.decls[id]
    }

    pub fn contract_members_types(&mut self, sid: usize) -> Vec<AbiType> {
        if let Some(v) = self.struct_types.get(&sid) {
            return v.clone();
        }
        let members = match &self.decls[sid].kind {
            DeclKind::Struct(m) => m.clone(),
            _ => vec![],
        };
        let file = self.decls[sid].file;
        let contract = self.decls[sid].contract;
        // avoid infinite recursion by reserving
        self.struct_types.insert(sid, vec![]);
        let mut out = vec![];
        let mut resolver = Resolver { g: self };
        for (_, ty) in &members {
            let t = resolver.resolve_type(ty, file, contract);
            out.push(t.unwrap_or(AbiType::Unknown));
        }
        self.struct_types.insert(sid, out.clone());
        out
    }

    /// Collects the declarations of one file.
    pub fn collect_file(&mut self, file: usize) {
        self.add_file(file);
        let items: Vec<Item> = self.units[file].items.clone();
        let mut scope: HashMap<String, usize> = HashMap::new();
        let mut cscope: HashMap<String, usize> = HashMap::new();
        for item in &items {
            match &item.kind {
                SourceUnitItem::Pragma(_) | SourceUnitItem::Import(_) => {}
                SourceUnitItem::Contract(c) => {
                    if let ItemKind::Contract {
                        kind,
                        name: (n, _),
                        body,
                        ..
                    } = &c.kind
                    {
                        let cid = self.contracts.len();
                        let decl_id = self.push_decl(Decl {
                            file,
                            contract: None,
                            name: n.clone(),
                            span: c.span,
                            kind: DeclKind::Contract(cid),
                        });
                        self.qualified.insert(decl_id, n.clone());
                        let mut own = vec![];
                        let mut c_local: HashMap<String, usize> = HashMap::new();
                        for sub in body {
                            let (dname, dkind) = self.decl_of_contract_item(sub);
                            let span = sub.span;
                            let id = self.push_decl(Decl {
                                file,
                                contract: Some(cid),
                                name: dname.clone().unwrap_or_default(),
                                span,
                                kind: dkind,
                            });
                            own.push(id);
                            if let Some(nm) = dname {
                                if let Some(&prev) = c_local.get(&nm) {
                                    let prev_span = self.decls[prev].span;
                                    let (msg, note) = match &sub.kind {
                                        ItemKind::Function { .. } => (
                                            "function with same name and parameter types declared twice",
                                            "other declaration",
                                        ),
                                        ItemKind::Event { .. } => (
                                            "event with same name and parameter types declared twice",
                                            "other declaration",
                                        ),
                                        _ => (
                                            Box::leak(Box::new(format!("identifier `{nm}` already declared"))),
                                            "previous declaration declared here",
                                        ),
                                    };
                                    let msg = msg.to_string();
                                    let mut dg = Diag::error(msg).with_span(span);
                                    dg.children.push(Diag::error(note).with_span(prev_span));
                                    self.diagnostics.push(dg);
                                } else {
                                    c_local.insert(nm.clone(), id);
                                }
                            }
                        }
                        self.contract_scope.push(c_local.clone());
                        let mut ctor = None;
                        let mut fallback = None;
                        let mut receive = None;
                        for (i, sub) in body.iter().enumerate() {
                            if let ItemKind::Function { kind, .. } = sub.kind {
                                match kind {
                                    FunctionKind::Constructor => ctor = Some(own[i]),
                                    FunctionKind::Fallback => fallback = Some(own[i]),
                                    FunctionKind::Receive => receive = Some(own[i]),
                                    _ => {}
                                }
                            }
                        }
                        self.contracts.push(ContractDecl {
                            file,
                            name: n.clone(),
                            kind: *kind,
                            span: c.span,
                            decl: decl_id,
                            own,
                            bases: vec![],
                            linearized: vec![],
                            ctor,
                            fallback,
                            receive,
                            scope: c_local,
                        });
                        cscope.insert(n.clone(), cid);
                        scope.insert(n.clone(), decl_id);
                    }
                }
                SourceUnitItem::Struct(it) => {
                    if let ItemKind::Struct { name: (n, _), members } = &it.kind {
                        let id = self.push_decl(Decl {
                            file,
                            contract: None,
                            name: n.clone(),
                            span: it.span,
                            kind: DeclKind::Struct(
                                members
                                    .iter()
                                    .map(|m| {
                                        (
                                            m.name.as_ref().map(|(x, _)| x.clone()).unwrap_or_default(),
                                            m.ty
                                                .clone()
                                                .unwrap_or(Type { span: DUMMY, kind: TypeKind::Elementary(ElementaryType::Uint(256)) }),
                                        )
                                    })
                                    .collect(),
                            ),
                        });
                        self.qualified.insert(id, n.clone());
                        scope.insert(n.clone(), id);
                    }
                }
                SourceUnitItem::Enum(it) => {
                    if let ItemKind::Enum { name: (n, _), variants } = &it.kind {
                        let id = self.push_decl(Decl {
                            file,
                            contract: None,
                            name: n.clone(),
                            span: it.span,
                            kind: DeclKind::Enum(variants.len()),
                        });
                        self.qualified.insert(id, n.clone());
                        scope.insert(n.clone(), id);
                    }
                }
                SourceUnitItem::Error(it) => {
                    if let ItemKind::Error { name: (n, _), params } = &it.kind {
                        let id = self.push_decl(Decl {
                            file,
                            contract: None,
                            name: n.clone(),
                            span: it.span,
                            kind: DeclKind::Error(params.clone()),
                        });
                        self.qualified.insert(id, n.clone());
                        scope.insert(n.clone(), id);
                    }
                }
                SourceUnitItem::UsingFor(it) => {
                    if let ItemKind::UsingFor { library, ty, .. } = &it.kind {
                        let id = self.push_decl(Decl {
                            file,
                            contract: None,
                            name: library.to_string(),
                            span: it.span,
                            kind: DeclKind::UsingFor(library.clone(), ty.clone()),
                        });
                        scope.insert(library.to_string(), id);
                    }
                }
                SourceUnitItem::Function(it) => {
                    if let ItemKind::Function { kind, header, body } = &it.kind {
                        let name = header.name.as_ref().map(|(s, _)| s.clone()).unwrap_or_default();
                        let id = self.push_decl(Decl {
                            file,
                            contract: None,
                            name: name.clone(),
                            span: it.span,
                            kind: DeclKind::Function(*kind, header.clone(), body.clone()),
                        });
                        if !name.is_empty() {
                            scope.insert(name, id);
                        }
                    }
                }
                SourceUnitItem::Variable(it) => {
                    if let ItemKind::VariableDefinition {
                        ty,
                        visibility,
                        mutability,
                        name: Some((n, _)),
                        initializer,
                        ..
                    } = &it.kind
                    {
                        let id = self.push_decl(Decl {
                            file,
                            contract: None,
                            name: n.clone(),
                            span: it.span,
                            kind: DeclKind::Variable(ty.clone(), *visibility, *mutability, initializer.clone()),
                        });
                        scope.insert(n.clone(), id);
                    }
                }
            }
        }
        self.file_scope[file] = scope;
        self.file_contract[file] = cscope;
    }

    fn decl_of_contract_item(&self, sub: &Item) -> (Option<String>, DeclKind) {
        match &sub.kind {
            ItemKind::Function { kind, header, body } => (
                header.name.as_ref().map(|(s, _)| s.clone()),
                DeclKind::Function(*kind, header.clone(), body.clone()),
            ),
            ItemKind::VariableDefinition {
                ty,
                visibility,
                mutability,
                name,
                initializer,
                ..
            } => (
                name.as_ref().map(|(s, _)| s.clone()),
                DeclKind::Variable(ty.clone(), *visibility, *mutability, initializer.clone()),
            ),
            ItemKind::Struct { name: (s, _), members } => (
                Some(s.clone()),
                DeclKind::Struct(
                    members
                        .iter()
                        .map(|m| {
                            (
                                m.name.as_ref().map(|(x, _)| x.clone()).unwrap_or_default(),
                                m.ty.clone().unwrap_or(Type { span: DUMMY, kind: TypeKind::Elementary(ElementaryType::Uint(256)) }),
                            )
                        })
                        .collect(),
                ),
            ),
            ItemKind::Enum { name: (s, _), variants } => (Some(s.clone()), DeclKind::Enum(variants.len())),
            ItemKind::Error { name: (s, _), params } => (Some(s.clone()), DeclKind::Error(params.clone())),
            ItemKind::Event { name: (s, _), params, anonymous } => {
                (Some(s.clone()), DeclKind::Event(params.clone(), *anonymous))
            }
            ItemKind::UsingFor { library, ty, .. } => {
                (Some(library.to_string()), DeclKind::UsingFor(library.clone(), ty.clone()))
            }
            ItemKind::Modifier { name: (s, _), params, body, .. } => {
                let h = FunctionHeader {
                    span: sub.span,
                    name: Some((s.clone(), DUMMY)),
                    params: params.clone(),
                    returns: vec![],
                    visibility: None,
                    mutability: None,
                    virtual_: false,
                    override_: None,
                    modifiers: vec![],
                };
                (Some(s.clone()), DeclKind::Modifier(h, body.clone()))
            }
            ItemKind::Contract { .. } => (None, DeclKind::Enum(0)),
        }
    }

    /// Resolves base contracts and linearises the inheritance.
    pub fn resolve_bases(&mut self) {
        let n = self.contracts.len();
        let mut base_lists: Vec<Vec<(String, Span)>> = vec![];
        for cid in 0..n {
            let file = self.contracts[cid].file;
            let span = self.contracts[cid].span;
            let mut out = vec![];
            for item in &self.units[file].items {
                if let SourceUnitItem::Contract(c) = item {
                    if c.span == span {
                        if let ItemKind::Contract { bases, .. } = &c.kind {
                            for b in bases {
                                let sp = b.path.idents[0].1;
                                out.push((b.path.to_string(), sp));
                            }
                        }
                        break;
                    }
                }
            }
            base_lists.push(out);
        }
        for cid in 0..n {
            for (name, span) in base_lists[cid].clone() {
                match self.lookup_contract(self.contracts[cid].file, &name) {
                    Some(b) => self.contracts[cid].bases.push(b),
                    None => {
                        self.diagnostics
                            .push(Diag::error(format!("unresolved symbol `{name}`")).with_span(span));
                    }
                }
            }
            let lin = self.linearize(cid);
            self.contracts[cid].linearized = lin;
        }
    }

    fn linearize(&self, cid: usize) -> Vec<usize> {
        let bases = self.contracts[cid].bases.clone();
        let mut lists: Vec<Vec<usize>> = vec![];
        for &b in &bases {
            lists.push(self.linearize_rec(b, 0));
        }
        lists.push(bases.clone());
        lists.push(vec![cid]);
        c3_merge(lists)
    }

    fn linearize_rec(&self, cid: usize, depth: usize) -> Vec<usize> {
        if depth > 64 {
            return vec![cid];
        }
        if !self.contracts[cid].linearized.is_empty() {
            return self.contracts[cid].linearized.clone();
        }
        let bases = self.contracts[cid].bases.clone();
        let mut lists: Vec<Vec<usize>> = vec![];
        for &b in &bases {
            lists.push(self.linearize_rec(b, depth + 1));
        }
        lists.push(bases);
        lists.push(vec![cid]);
        c3_merge(lists)
    }

    pub fn lookup_contract(&self, file: usize, name: &str) -> Option<usize> {
        if let Some(&cid) = self.file_contract.get(file).and_then(|m| m.get(name)) {
            return Some(cid);
        }
        let mut seen: Vec<usize> = vec![file];
        let mut queue = self.import_targets.get(file).cloned().unwrap_or_default();
        while let Some(f) = queue.pop() {
            if seen.contains(&f) {
                continue;
            }
            seen.push(f);
            if let Some(&cid) = self.file_contract.get(f).and_then(|m| m.get(name)) {
                return Some(cid);
            }
            queue.extend(self.import_targets.get(f).cloned().unwrap_or_default());
        }
        None
    }

    /// Collects all inherited items of a contract in linearisation order.
    pub fn all_items(&self, cid: usize) -> Vec<usize> {
        let mut out: Vec<usize> = vec![];
        for &b in self.contracts[cid].linearized.iter().rev() {
            if b == cid {
                continue;
            }
            for &d in &self.contracts[b].own {
                if !out.contains(&d) {
                    out.push(d);
                }
            }
        }
        for &d in &self.contracts[cid].own {
            if !out.contains(&d) {
                out.push(d);
            }
        }
        out
    }

    // ------------------------------------------------------------------
    // ABI generation

    pub fn generate_abi(&mut self, emit_abi: bool, emit_hashes: bool) -> Json {
        // 1. resolve struct types for every struct decl (needed for qualified names)
        let struct_ids: Vec<usize> = (0..self.decls.len())
            .filter(|i| matches!(self.decls[*i].kind, DeclKind::Struct(_)))
            .collect();
        for sid in struct_ids {
            self.contract_members_types(sid);
        }
        let mut contracts_json = Json::obj();
        for cid in 0..self.contracts.len() {
            let key = self.contract_key(cid);
            let value = self.contract_abi(cid, emit_abi, emit_hashes);
            contracts_json.set(&key, value);
        }
        let mut out = Json::obj();
        out.set("contracts", contracts_json);
        out.set("version", Json::Str(crate::cli::VERSION.to_string()));
        out
    }

    pub fn contract_key(&self, cid: usize) -> String {
        let path = self.units[self.contracts[cid].file].display_path.clone();
        format!("{}:{}", path, self.contracts[cid].name)
    }

    fn ctx(&self) -> TypeCtx<'_> {
        let mut m: HashMap<usize, (String, Vec<(String, Option<AbiType>)>)> = HashMap::new();
        for (id, d) in self.decls.iter().enumerate() {
            match &d.kind {
                DeclKind::Struct(members) => {
                    let types = self.struct_types.get(&id).cloned().unwrap_or_default();
                    let mm: Vec<(String, Option<AbiType>)> = members
                        .iter()
                        .enumerate()
                        .map(|(i, (n, _))| (n.clone(), types.get(i).cloned()))
                        .collect();
                    m.insert(id, (self.qualified.get(&id).cloned().unwrap_or_default(), mm));
                }
                DeclKind::Contract(_) => {
                    m.insert(id, (self.qualified.get(&id).cloned().unwrap_or_default(), vec![]));
                }
                DeclKind::Enum(_) => {
                    m.insert(id, (self.qualified.get(&id).cloned().unwrap_or_default(), vec![]));
                }
                _ => {}
            }
        }
        TypeCtx { structs: &m }
    }

    fn contract_abi(&mut self, cid: usize, emit_abi: bool, emit_hashes: bool) -> Json {
        let items = self.all_items(cid);
        let mut resolver = Resolver { g: self };
        let file = self.contracts[cid].file;
        let contract = Some(cid);
        let _ = contract;
        // 1. errors, 2. events, 3. state variables, 4. functions
        let mut errors: Vec<(usize, Vec<Param>, Option<String>)> = vec![];
        let mut events: Vec<(usize, Vec<Param>, bool)> = vec![];
        let mut vars: Vec<(usize, Type, Option<Visibility>, Option<Mutability>)> = vec![];
        let mut funcs: Vec<(usize, FunctionKind, FunctionHeader)> = vec![];
        let mut ctor: Option<usize> = None;
        let mut fallback: Option<usize> = None;
        let mut receive: Option<usize> = None;
        for &d in &items {
            match &self.decls[d].kind {
                DeclKind::Error(params) => errors.push((d, params.clone(), None)),
                DeclKind::Event(params, anonymous) => events.push((d, params.clone(), *anonymous)),
                DeclKind::Variable(ty, vis, mut_, _) => vars.push((d, ty.clone(), *vis, *mut_)),
                DeclKind::Function(kind, header, _body) => {
                    match kind {
                        FunctionKind::Constructor => ctor = Some(d),
                        FunctionKind::Fallback => fallback = Some(d),
                        FunctionKind::Receive => receive = Some(d),
                        _ => funcs.push((d, *kind, header.clone())),
                    }
                }
                _ => {}
            }
        }
        let _ = &mut resolver;
        let mut abi: Vec<(String, Json)> = vec![];
        let mut hashes: BTreeMap<String, ()> = BTreeMap::new();
        // constructor
        if let Some(d) = ctor {
            if emit_abi {
                let header = match &self.decls[d].kind {
                    DeclKind::Function(_, h, _) => h.clone(),
                    _ => unreachable!(),
                };
                let inputs = self.resolve_params(&mut Resolver { g: self }, file, cid, &header.params);
                let mut o = Json::obj();
                o.set("type", Json::Str("constructor".to_string()));
                o.set("inputs", Json::Array(inputs));
                let payable = matches!(header.mutability, Some(Mutability::Payable));
                o.set(
                    "stateMutability",
                    Json::Str(if payable { "payable".to_string() } else { "nonpayable".to_string() }),
                );
                abi.push(("constructor".to_string(), o));
            }
        }
        for (d, params, _) in errors.clone() {
            if !emit_abi {
                continue;
            }
            let inputs = self.resolve_params(&mut Resolver { g: self }, file, cid, &params);
            let mut o = Json::obj();
            o.set("type", Json::Str("error".to_string()));
            o.set("name", Json::Str(self.decls[d].name.clone()));
            o.set("inputs", Json::Array(inputs));
            abi.push(("error".to_string(), o));
        }
        for (d, params, anonymous) in events.clone() {
            if !emit_abi {
                continue;
            }
            let inputs = self.resolve_params(&mut Resolver { g: self }, file, cid, &params);
            let mut o = Json::obj();
            o.set("type", Json::Str("event".to_string()));
            o.set("name", Json::Str(self.decls[d].name.clone()));
            o.set("inputs", Json::Array(inputs));
            o.set("anonymous", Json::Bool(anonymous));
            abi.push(("event".to_string(), o));
        }
        if let Some(d) = fallback {
            if emit_abi {
                let header = match &self.decls[d].kind {
                    DeclKind::Function(_, h, _) => h.clone(),
                    _ => unreachable!(),
                };
                let mut o = Json::obj();
                o.set("type", Json::Str("fallback".to_string()));
                let sm = match header.mutability {
                    Some(Mutability::Payable) => "payable",
                    Some(Mutability::Pure) => "pure",
                    Some(Mutability::View) => "view",
                    _ => "nonpayable",
                };
                o.set("stateMutability", Json::Str(sm.to_string()));
                abi.push(("fallback".to_string(), o));
            }
        }
        // functions: declared functions and public getters
        let mut fn_entries: Vec<(String, Json, String)> = vec![];
        for (d, _kind, header) in funcs.clone() {
            let vis = header.visibility.unwrap_or(Visibility::Internal);
            if !matches!(vis, Visibility::Public | Visibility::External) {
                continue;
            }
            let inputs = self.resolve_params(&mut Resolver { g: self }, file, cid, &header.params);
            let outputs = self.resolve_params(&mut Resolver { g: self }, file, cid, &header.returns);
            let name = header.name.as_ref().map(|(s, _)| s.clone()).unwrap_or_default();
            if !emit_abi {
                continue;
            }
            let mut o = Json::obj();
            o.set("type", Json::Str("function".to_string()));
            o.set("name", Json::Str(name.clone()));
            o.set("inputs", Json::Array(inputs.clone()));
            o.set("outputs", Json::Array(outputs.clone()));
            let sm = match header.mutability {
                Some(Mutability::Pure) => "pure",
                Some(Mutability::View) => "view",
                Some(Mutability::Payable) => "payable",
                _ => "nonpayable",
            };
            o.set("stateMutability", Json::Str(sm.to_string()));
            let sig = format!(
                "{}({})",
                name,
                inputs
                    .iter()
                    .map(|i| crate::abi::canonical_of_json(i))
                    .collect::<Vec<_>>()
                    .join(",")
            );
            hashes.insert(sig.clone(), ());
            fn_entries.push((name, o, sig));
        }
        // getters
        for (d, ty, vis, mut_) in vars.clone() {
            if !matches!(vis, Some(Visibility::Public)) {
                continue;
            }
            let resolved = {
                let mut r = Resolver { g: self };
                r.resolve_type(&ty, self.decls[d].file, Some(cid))
            };
            let Some(t) = resolved else { continue };
            let (idx_params, out_ty, out_components) = self.getter_parts(t);
            let name = self.decls[d].name.clone();
            if !emit_abi {
                continue;
            }
            let ctx = self.ctx();
            let mut inputs = vec![];
            for (n, it) in &idx_params {
                let j = crate::abi::abi_param_json(n, it, None, &ctx, &self.ctx_map());
                inputs.push(j);
            }
            let outputs = vec![crate::abi::getter_output(&out_ty, &out_components, &ctx, &self.ctx_map())];
            let mut o = Json::obj();
            o.set("type", Json::Str("function".to_string()));
            o.set("name", Json::Str(name.clone()));
            o.set("inputs", Json::Array(inputs.clone()));
            o.set("outputs", Json::Array(outputs));
            o.set("stateMutability", Json::Str("view".to_string()));
            let sig = format!(
                "{}({})",
                name,
                inputs
                    .iter()
                    .map(|i| crate::abi::canonical_of_json(i))
                    .collect::<Vec<_>>()
                    .join(",")
            );
            hashes.insert(sig.clone(), ());
            fn_entries.push((name, o, sig));
        }
        if let Some(d) = receive {
            if emit_abi {
                let mut o = Json::obj();
                o.set("type", Json::Str("receive".to_string()));
                o.set("stateMutability", Json::Str("payable".to_string()));
                abi.push(("receive".to_string(), o));
            }
        }
        // sort
        let type_rank = |t: &str| match t {
            "constructor" => 0,
            "error" => 1,
            "event" => 2,
            "fallback" => 3,
            "function" => 4,
            "receive" => 5,
            _ => 6,
        };
        abi.sort_by(|a, b| {
            let (ta, na) = (type_rank(&a.0), &a.1);
            let (tb, nb) = (type_rank(&b.0), &b.1);
            ta.cmp(&tb).then_with(|| name_of(na).cmp(&name_of(nb)))
        });
        fn_entries.sort_by(|a, b| a.0.cmp(&b.0));
        let mut contract_obj = Json::obj();
        if emit_abi {
            contract_obj.set(
                "abi",
                Json::Array(abi.iter().map(|(_, j)| j.clone()).collect()),
            );
        }
        if emit_hashes {
            let mut h = Json::obj();
            let mut sigs: Vec<String> = vec![];
            for (_, _, s) in &fn_entries {
                if !sigs.contains(s) {
                    sigs.push(s.clone());
                }
            }
            sigs.sort();
            for s in sigs {
                let sel = crate::keccak::selector(&s);
                h.set(&s, Json::Str(crate::keccak::hex4(&sel)));
            }
            contract_obj.set("hashes", h);
        }
        contract_obj
    }

    fn ctx_map(&self) -> std::collections::HashMap<usize, (String, Vec<(String, Option<AbiType>)>)> {
        let mut m: HashMap<usize, (String, Vec<(String, Option<AbiType>)>)> = HashMap::new();
        for (id, d) in self.decls.iter().enumerate() {
            match &d.kind {
                DeclKind::Struct(members) => {
                    let types = self.struct_types.get(&id).cloned().unwrap_or_default();
                    let mm: Vec<(String, Option<AbiType>)> = members
                        .iter()
                        .enumerate()
                        .map(|(i, (n, _))| (n.clone(), types.get(i).cloned()))
                        .collect();
                    m.insert(id, (self.qualified.get(&id).cloned().unwrap_or_default(), mm));
                }
                DeclKind::Contract(_) => {
                    m.insert(id, (self.qualified.get(&id).cloned().unwrap_or_default(), vec![]));
                }
                DeclKind::Enum(_) => {
                    m.insert(id, (self.qualified.get(&id).cloned().unwrap_or_default(), vec![]));
                }
                _ => {}
            }
        }
        m
    }

    fn resolve_params(
        &mut self,
        r: &mut Resolver,
        file: usize,
        cid: usize,
        params: &[Param],
    ) -> Vec<Json> {
        let ctx = self.ctx();
        let map = self.ctx_map();
        let mut out = vec![];
        for p in params {
            let name = p.name.as_ref().map(|(s, _)| s.clone()).unwrap_or_default();
            let ty = match &p.ty {
                Some(t) => r.resolve_type(t, file, Some(cid)),
                None => None,
            };
            let t = ty.unwrap_or(AbiType::Unknown);
            out.push(crate::abi::abi_param_json(
                &name,
                &t,
                if p.indexed { Some(true) } else { None },
                &ctx,
                &map,
            ));
        }
        out
    }

    /// Computes the getter parts for a public state variable.
    fn getter_parts(&self, t: AbiType) -> (Vec<(String, AbiType)>, AbiType, Vec<(String, AbiType)>) {
        let mut idx = vec![];
        let mut cur = t;
        loop {
            match cur {
                AbiType::Mapping(k, v) => {
                    idx.push((String::new(), *k));
                    cur = *v;
                }
                AbiType::Array(e, _) => {
                    idx.push((String::new(), AbiType::Elementary(ElementaryType::Uint(256))));
                    cur = *e;
                }
                _ => break,
            }
        }
        match cur {
            AbiType::Tuple(sid) => {
                let members = self.struct_types.get(&sid).cloned().unwrap_or_default();
                let names: Vec<String> = match &self.decls[sid].kind {
                    DeclKind::Struct(m) => m.iter().map(|(n, _)| n.clone()).collect(),
                    _ => vec![],
                };
                let mut comps = vec![];
                for (i, mt) in members.iter().enumerate() {
                    if matches!(mt, AbiType::Array(_, _) | AbiType::Mapping(_, _)) {
                        continue;
                    }
                    comps.push((
                        names.get(i).cloned().unwrap_or_default(),
                        mt.clone(),
                    ));
                }
                (idx, cur, comps)
            }
            _ => (idx, cur, vec![]),
        }
    }
}

fn name_of(j: &Json) -> String {
    match j.get("name") {
        Some(Json::Str(s)) => s.clone(),
        _ => String::new(),
    }
}

fn c3_merge(mut lists: Vec<Vec<usize>>) -> Vec<usize> {
    let mut out: Vec<usize> = vec![];
    loop {
        lists.retain(|l| !l.is_empty());
        if lists.is_empty() {
            break;
        }
        let mut candidate: Option<usize> = None;
        for l in &lists {
            let head = l[0];
            let mut in_tail = false;
            for other in &lists {
                if other.len() > 1 && other[1..].contains(&head) {
                    in_tail = true;
                    break;
                }
            }
            if !in_tail {
                candidate = Some(head);
                break;
            }
        }
        let Some(c) = candidate else {
            let c = lists[0][0];
            out.push(c);
            for l in &mut lists {
                l.retain(|&x| x != c);
            }
            continue;
        };
        if !out.contains(&c) {
            out.push(c);
        }
        for l in &mut lists {
            l.retain(|&x| x != c);
        }
    }
    out
}

pub struct Resolver<'a> {
    pub g: &'a mut Global,
}

impl<'a> Resolver<'a> {
    pub fn resolve_type(&mut self, ty: &Type, file: usize, contract: Option<usize>) -> Option<AbiType> {
        match &ty.kind {
            TypeKind::Elementary(e) => Some(AbiType::Elementary(*e)),
            TypeKind::UserDefined(path) => self.resolve_path(path, file, contract),
            TypeKind::Mapping(k, v) => {
                let kt = self.resolve_type(k, file, contract)?;
                let vt = self.resolve_type(v, file, contract)?;
                Some(AbiType::Mapping(Box::new(kt), Box::new(vt)))
            }
            TypeKind::Array(elem, size) => {
                let et = self.resolve_type(elem, file, contract)?;
                let len = size.as_ref().and_then(crate::lower::eval_const);
                Some(AbiType::Array(Box::new(et), len))
            }
            TypeKind::Function(params, rets, vis, mut_) => {
                let mut ps = vec![];
                for p in params {
                    if let Some(t) = &p.ty {
                        ps.push(self.resolve_type(t, file, contract)?);
                    }
                }
                let mut rs = vec![];
                for p in rets {
                    if let Some(t) = &p.ty {
                        rs.push(self.resolve_type(t, file, contract)?);
                    }
                }
                Some(AbiType::Function {
                    params: ps,
                    rets: rs,
                    vis: *vis,
                    mut_: *mut_,
                })
            }
        }
    }

    pub fn resolve_path(&mut self, path: &Path, file: usize, contract: Option<usize>) -> Option<AbiType> {
        let first = &path.idents[0].0;
        if path.idents.len() > 1 {
            // alias lookup: X.member
            if let Some(&f) = self.g.alias_map.get(file).and_then(|m| m.get(first)) {
                let name = &path.idents[1].0;
                let sp = path.idents[1].1;
                if let Some(&d) = self.g.file_scope.get(f).and_then(|m| m.get(name)) {
                    return self.decl_to_type(d, sp);
                }
                self.g
                    .diagnostics
                    .push(Diag::error(format!("unresolved symbol `{name}`")).with_span(sp));
                return None;
            }
            if let Some(c) = self.g.lookup_contract(file, first) {
                let decl_id = self.g.contracts[c].decl;
                let name = &path.idents[1].0;
                let sp = path.idents[1].1;
                if let Some(&d) = self.g.contract_scope.get(c).and_then(|m| m.get(name)) {
                    return self.decl_to_type(d, sp);
                }
                let _ = decl_id;
                self.g
                    .diagnostics
                    .push(Diag::error(format!("unresolved symbol `{name}`")).with_span(sp));
                return None;
            }
            self.g
                .diagnostics
                .push(Diag::error(format!("unresolved symbol `{first}`")).with_span(path.idents[0].1));
            return None;
        }
        if let Some(c) = contract {
            if let Some(&d) = self.g.contract_scope.get(c).and_then(|m| m.get(first)) {
                return self.decl_to_type(d, path.idents[0].1);
            }
        }
        if let Some(&d) = self.g.file_scope.get(file).and_then(|m| m.get(first)) {
            if let DeclKind::Contract(c) = self.g.decls[d].kind {
                return Some(AbiType::Contract(c));
            }
            return self.decl_to_type(d, path.idents[0].1);
        }
        for f in self.g.import_targets.get(file).cloned().unwrap_or_default() {
            if let Some(&d) = self.g.file_scope.get(f).and_then(|m| m.get(first)) {
                if let DeclKind::Contract(c) = self.g.decls[d].kind {
                    return Some(AbiType::Contract(c));
                }
                return self.decl_to_type(d, path.idents[0].1);
            }
        }
        self.g
            .diagnostics
            .push(Diag::error(format!("unresolved symbol `{first}`")).with_span(path.idents[0].1));
        None
    }

    fn decl_to_type(&mut self, d: usize, span: Span) -> Option<AbiType> {
        match &self.g.decls[d].kind {
            DeclKind::Contract(_) => Some(AbiType::Contract(d)),
            DeclKind::Struct(_) => Some(AbiType::Tuple(d)),
            DeclKind::Enum(_) => Some(AbiType::Enum(d)),
            _ => {
                let n = self.g.decls[d].name.clone();
                self.g
                    .diagnostics
                    .push(Diag::error(format!("unresolved symbol `{n}`")).with_span(span));
                None
            }
        }
    }
}

pub fn eval_const(e: &Expr) -> Option<u64> {
    match &e.kind {
        ExprKind::Lit(LitKind::Number(s)) => {
            let s: String = s.chars().filter(|c| *c != '_').collect();
            if let Some(hex) = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
                u64::from_str_radix(hex, 16).ok()
            } else {
                s.parse::<u64>().ok()
            }
        }
        ExprKind::Lit(LitKind::Rational(s)) => s.split('.').next()?.parse::<u64>().ok(),
        ExprKind::Unary(op, e, _) => {
            let v = eval_const(e)?;
            match op.as_str() {
                "-" => Some((0i64.wrapping_sub(v as i64)) as u64),
                "~" => Some(!v),
                "+" => Some(v),
                _ => None,
            }
        }
        ExprKind::Binary(op, a, b) => {
            let x = eval_const(a)?;
            let y = eval_const(b)?;
            match op.as_str() {
                "+" => Some(x.wrapping_add(y)),
                "-" => Some(x.wrapping_sub(y)),
                "*" => Some(x.wrapping_mul(y)),
                "/" => if y == 0 { None } else { Some(x / y) },
                "%" => if y == 0 { None } else { Some(x % y) },
                "**" => Some(x.pow(y.min(63) as u32)),
                "<<" => Some(x << y.min(63)),
                ">>" => Some(x >> y.min(63)),
                "&" => Some(x & y),
                "|" => Some(x | y),
                "^" => Some(x ^ y),
                _ => None,
            }
        }
        ExprKind::Tuple(items) => {
            if items.len() == 1 {
                items[0].as_ref().and_then(eval_const)
            } else {
                None
            }
        }
        _ => None,
    }
}
RSEOF
echo ok"}

actions.command:
cat > src/lower.rs <<'RSEOF'
//! Lowering: collects declarations, resolves names, inheritance and builds the ABI.

use crate::abi::{self, AbiType, TypeCtx};
use crate::ast::*;
use crate::diag::Diag;
use crate::json::Json;
use crate::span::{DUMMY, Span};
use std::collections::{BTreeMap, HashMap};

#[derive(Clone, Debug)]
pub enum DeclKind {
    Contract(usize),
    Struct(Vec<(String, Type)>),
    Enum(usize),
    Error(Vec<Param>),
    Event(Vec<Param>, bool),
    Function(FunctionKind, FunctionHeader, Body),
    Variable(Type, Option<Visibility>, Option<Mutability>, Option<Expr>),
    UsingFor(Path, Option<Type>),
    Modifier(FunctionHeader, Body),
}

#[derive(Clone, Debug)]
pub struct Decl {
    pub file: usize,
    pub contract: Option<usize>,
    pub name: String,
    pub span: Span,
    pub kind: DeclKind,
}

#[derive(Clone, Debug)]
pub struct ContractDecl {
    pub file: usize,
    pub name: String,
    pub kind: ContractKind,
    pub span: Span,
    pub decl: usize,
    pub own: Vec<usize>,
    pub bases: Vec<usize>,
    pub linearized: Vec<usize>,
    pub ctor: Option<usize>,
    pub fallback: Option<usize>,
    pub receive: Option<usize>,
    pub scope: HashMap<String, usize>,
}

pub struct Global {
    pub units: Vec<SourceUnit>,
    pub decls: Vec<Decl>,
    pub contracts: Vec<ContractDecl>,
    pub contract_scope: Vec<HashMap<String, usize>>,
    pub file_scope: Vec<HashMap<String, usize>>,
    pub file_contract: Vec<HashMap<String, usize>>,
    pub alias_map: Vec<HashMap<String, usize>>,
    pub import_targets: Vec<Vec<usize>>,
    pub diagnostics: Vec<Diag>,
    pub qualified: HashMap<usize, String>,
    /// resolved abi types for struct members, keyed by decl id
    pub struct_types: HashMap<usize, Vec<AbiType>>,
}

impl Global {
    pub fn new(units: Vec<SourceUnit>) -> Global {
        Global {
            units,
            decls: vec![],
            contracts: vec![],
            contract_scope: vec![],
            file_scope: vec![],
            file_contract: vec![],
            alias_map: vec![],
            import_targets: vec![],
            diagnostics: vec![],
            qualified: HashMap::new(),
            struct_types: HashMap::new(),
        }
    }

    fn add_file(&mut self, file: usize) {
        while self.file_scope.len() <= file {
            self.file_scope.push(HashMap::new());
            self.file_contract.push(HashMap::new());
            self.alias_map.push(HashMap::new());
            self.import_targets.push(vec![]);
        }
    }

    pub fn push_decl(&mut self, d: Decl) -> usize {
        self.decls.push(d);
        self.decls.len() - 1
    }

    pub fn decl(&self, id: usize) -> &Decl {
        &self.decls[id]
    }

    pub fn contract_members_types(&mut self, sid: usize) -> Vec<AbiType> {
        if let Some(v) = self.struct_types.get(&sid) {
            return v.clone();
        }
        let members = match &self.decls[sid].kind {
            DeclKind::Struct(m) => m.clone(),
            _ => vec![],
        };
        let file = self.decls[sid].file;
        let contract = self.decls[sid].contract;
        // avoid infinite recursion by reserving
        self.struct_types.insert(sid, vec![]);
        let mut out = vec![];
        let mut resolver = Resolver { g: self };
        for (_, ty) in &members {
            let t = resolver.resolve_type(ty, file, contract);
            out.push(t.unwrap_or(AbiType::Unknown));
        }
        self.struct_types.insert(sid, out.clone());
        out
    }

    /// Collects the declarations of one file.
    pub fn collect_file(&mut self, file: usize) {
        self.add_file(file);
        let items: Vec<Item> = self.units[file].items.clone();
        let mut scope: HashMap<String, usize> = HashMap::new();
        let mut cscope: HashMap<String, usize> = HashMap::new();
        for item in &items {
            match &item.kind {
                SourceUnitItem::Pragma(_) | SourceUnitItem::Import(_) => {}
                SourceUnitItem::Contract(c) => {
                    if let ItemKind::Contract {
                        kind,
                        name: (n, _),
                        body,
                        ..
                    } = &c.kind
                    {
                        let cid = self.contracts.len();
                        let decl_id = self.push_decl(Decl {
                            file,
                            contract: None,
                            name: n.clone(),
                            span: c.span,
                            kind: DeclKind::Contract(cid),
                        });
                        self.qualified.insert(decl_id, n.clone());
                        let mut own = vec![];
                        let mut c_local: HashMap<String, usize> = HashMap::new();
                        for sub in body {
                            let (dname, dkind) = self.decl_of_contract_item(sub);
                            let span = sub.span;
                            let id = self.push_decl(Decl {
                                file,
                                contract: Some(cid),
                                name: dname.clone().unwrap_or_default(),
                                span,
                                kind: dkind,
                            });
                            own.push(id);
                            if let Some(nm) = dname {
                                if let Some(&prev) = c_local.get(&nm) {
                                    let prev_span = self.decls[prev].span;
                                    let (msg, note) = match &sub.kind {
                                        ItemKind::Function { .. } => (
                                            "function with same name and parameter types declared twice",
                                            "other declaration",
                                        ),
                                        ItemKind::Event { .. } => (
                                            "event with same name and parameter types declared twice",
                                            "other declaration",
                                        ),
                                        _ => (
                                            Box::leak(Box::new(format!("identifier `{nm}` already declared"))),
                                            "previous declaration declared here",
                                        ),
                                    };
                                    let msg = msg.to_string();
                                    let mut dg = Diag::error(msg).with_span(span);
                                    dg.children.push(Diag::error(note).with_span(prev_span));
                                    self.diagnostics.push(dg);
                                } else {
                                    c_local.insert(nm.clone(), id);
                                }
                            }
                        }
                        self.contract_scope.push(c_local.clone());
                        let mut ctor = None;
                        let mut fallback = None;
                        let mut receive = None;
                        for (i, sub) in body.iter().enumerate() {
                            if let ItemKind::Function { kind, .. } = sub.kind {
                                match kind {
                                    FunctionKind::Constructor => ctor = Some(own[i]),
                                    FunctionKind::Fallback => fallback = Some(own[i]),
                                    FunctionKind::Receive => receive = Some(own[i]),
                                    _ => {}
                                }
                            }
                        }
                        self.contracts.push(ContractDecl {
                            file,
                            name: n.clone(),
                            kind: *kind,
                            span: c.span,
                            decl: decl_id,
                            own,
                            bases: vec![],
                            linearized: vec![],
                            ctor,
                            fallback,
                            receive,
                            scope: c_local,
                        });
                        cscope.insert(n.clone(), cid);
                        scope.insert(n.clone(), decl_id);
                    }
                }
                SourceUnitItem::Struct(it) => {
                    if let ItemKind::Struct { name: (n, _), members } = &it.kind {
                        let id = self.push_decl(Decl {
                            file,
                            contract: None,
                            name: n.clone(),
                            span: it.span,
                            kind: DeclKind::Struct(
                                members
                                    .iter()
                                    .map(|m| {
                                        (
                                            m.name.as_ref().map(|(x, _)| x.clone()).unwrap_or_default(),
                                            m.ty
                                                .clone()
                                                .unwrap_or(Type { span: DUMMY, kind: TypeKind::Elementary(ElementaryType::Uint(256)) }),
                                        )
                                    })
                                    .collect(),
                            ),
                        });
                        self.qualified.insert(id, n.clone());
                        scope.insert(n.clone(), id);
                    }
                }
                SourceUnitItem::Enum(it) => {
                    if let ItemKind::Enum { name: (n, _), variants } = &it.kind {
                        let id = self.push_decl(Decl {
                            file,
                            contract: None,
                            name: n.clone(),
                            span: it.span,
                            kind: DeclKind::Enum(variants.len()),
                        });
                        self.qualified.insert(id, n.clone());
                        scope.insert(n.clone(), id);
                    }
                }
                SourceUnitItem::Error(it) => {
                    if let ItemKind::Error { name: (n, _), params } = &it.kind {
                        let id = self.push_decl(Decl {
                            file,
                            contract: None,
                            name: n.clone(),
                            span: it.span,
                            kind: DeclKind::Error(params.clone()),
                        });
                        self.qualified.insert(id, n.clone());
                        scope.insert(n.clone(), id);
                    }
                }
                SourceUnitItem::UsingFor(it) => {
                    if let ItemKind::UsingFor { library, ty, .. } = &it.kind {
                        let id = self.push_decl(Decl {
                            file,
                            contract: None,
                            name: library.to_string(),
                            span: it.span,
                            kind: DeclKind::UsingFor(library.clone(), ty.clone()),
                        });
                        scope.insert(library.to_string(), id);
                    }
                }
                SourceUnitItem::Function(it) => {
                    if let ItemKind::Function { kind, header, body } = &it.kind {
                        let name = header.name.as_ref().map(|(s, _)| s.clone()).unwrap_or_default();
                        let id = self.push_decl(Decl {
                            file,
                            contract: None,
                            name: name.clone(),
                            span: it.span,
                            kind: DeclKind::Function(*kind, header.clone(), body.clone()),
                        });
                        if !name.is_empty() {
                            scope.insert(name, id);
                        }
                    }
                }
                SourceUnitItem::Variable(it) => {
                    if let ItemKind::VariableDefinition {
                        ty,
                        visibility,
                        mutability,
                        name: Some((n, _)),
                        initializer,
                        ..
                    } = &it.kind
                    {
                        let id = self.push_decl(Decl {
                            file,
                            contract: None,
                            name: n.clone(),
                            span: it.span,
                            kind: DeclKind::Variable(ty.clone(), *visibility, *mutability, initializer.clone()),
                        });
                        scope.insert(n.clone(), id);
                    }
                }
            }
        }
        self.file_scope[file] = scope;
        self.file_contract[file] = cscope;
    }

    fn decl_of_contract_item(&self, sub: &Item) -> (Option<String>, DeclKind) {
        match &sub.kind {
            ItemKind::Function { kind, header, body } => (
                header.name.as_ref().map(|(s, _)| s.clone()),
                DeclKind::Function(*kind, header.clone(), body.clone()),
            ),
            ItemKind::VariableDefinition {
                ty,
                visibility,
                mutability,
                name,
                initializer,
                ..
            } => (
                name.as_ref().map(|(s, _)| s.clone()),
                DeclKind::Variable(ty.clone(), *visibility, *mutability, initializer.clone()),
            ),
            ItemKind::Struct { name: (s, _), members } => (
                Some(s.clone()),
                DeclKind::Struct(
                    members
                        .iter()
                        .map(|m| {
                            (
                                m.name.as_ref().map(|(x, _)| x.clone()).unwrap_or_default(),
                                m.ty.clone().unwrap_or(Type { span: DUMMY, kind: TypeKind::Elementary(ElementaryType::Uint(256)) }),
                            )
                        })
                        .collect(),
                ),
            ),
            ItemKind::Enum { name: (s, _), variants } => (Some(s.clone()), DeclKind::Enum(variants.len())),
            ItemKind::Error { name: (s, _), params } => (Some(s.clone()), DeclKind::Error(params.clone())),
            ItemKind::Event { name: (s, _), params, anonymous } => {
                (Some(s.clone()), DeclKind::Event(params.clone(), *anonymous))
            }
            ItemKind::UsingFor { library, ty, .. } => {
                (Some(library.to_string()), DeclKind::UsingFor(library.clone(), ty.clone()))
            }
            ItemKind::Modifier { name: (s, _), params, body, .. } => {
                let h = FunctionHeader {
                    span: sub.span,
                    name: Some((s.clone(), DUMMY)),
                    params: params.clone(),
                    returns: vec![],
                    visibility: None,
                    mutability: None,
                    virtual_: false,
                    override_: None,
                    modifiers: vec![],
                };
                (Some(s.clone()), DeclKind::Modifier(h, body.clone()))
            }
            ItemKind::Contract { .. } => (None, DeclKind::Enum(0)),
        }
    }

    /// Resolves base contracts and linearises the inheritance.
    pub fn resolve_bases(&mut self) {
        let n = self.contracts.len();
        let mut base_lists: Vec<Vec<(String, Span)>> = vec![];
        for cid in 0..n {
            let file = self.contracts[cid].file;
            let span = self.contracts[cid].span;
            let mut out = vec![];
            for item in &self.units[file].items {
                if let SourceUnitItem::Contract(c) = item {
                    if c.span == span {
                        if let ItemKind::Contract { bases, .. } = &c.kind {
                            for b in bases {
                                let sp = b.path.idents[0].1;
                                out.push((b.path.to_string(), sp));
                            }
                        }
                        break;
                    }
                }
            }
            base_lists.push(out);
        }
        for cid in 0..n {
            for (name, span) in base_lists[cid].clone() {
                match self.lookup_contract(self.contracts[cid].file, &name) {
                    Some(b) => self.contracts[cid].bases.push(b),
                    None => {
                        self.diagnostics
                            .push(Diag::error(format!("unresolved symbol `{name}`")).with_span(span));
                    }
                }
            }
            let lin = self.linearize(cid);
            self.contracts[cid].linearized = lin;
        }
    }

    fn linearize(&self, cid: usize) -> Vec<usize> {
        let bases = self.contracts[cid].bases.clone();
        let mut lists: Vec<Vec<usize>> = vec![];
        for &b in &bases {
            lists.push(self.linearize_rec(b, 0));
        }
        lists.push(bases.clone());
        lists.push(vec![cid]);
        c3_merge(lists)
    }

    fn linearize_rec(&self, cid: usize, depth: usize) -> Vec<usize> {
        if depth > 64 {
            return vec![cid];
        }
        if !self.contracts[cid].linearized.is_empty() {
            return self.contracts[cid].linearized.clone();
        }
        let bases = self.contracts[cid].bases.clone();
        let mut lists: Vec<Vec<usize>> = vec![];
        for &b in &bases {
            lists.push(self.linearize_rec(b, depth + 1));
        }
        lists.push(bases);
        lists.push(vec![cid]);
        c3_merge(lists)
    }

    pub fn lookup_contract(&self, file: usize, name: &str) -> Option<usize> {
        if let Some(&cid) = self.file_contract.get(file).and_then(|m| m.get(name)) {
            return Some(cid);
        }
        let mut seen: Vec<usize> = vec![file];
        let mut queue = self.import_targets.get(file).cloned().unwrap_or_default();
        while let Some(f) = queue.pop() {
            if seen.contains(&f) {
                continue;
            }
            seen.push(f);
            if let Some(&cid) = self.file_contract.get(f).and_then(|m| m.get(name)) {
                return Some(cid);
            }
            queue.extend(self.import_targets.get(f).cloned().unwrap_or_default());
        }
        None
    }

    /// Collects all inherited items of a contract in linearisation order.
    pub fn all_items(&self, cid: usize) -> Vec<usize> {
        let mut out: Vec<usize> = vec![];
        for &b in self.contracts[cid].linearized.iter().rev() {
            if b == cid {
                continue;
            }
            for &d in &self.contracts[b].own {
                if !out.contains(&d) {
                    out.push(d);
                }
            }
        }
        for &d in &self.contracts[cid].own {
            if !out.contains(&d) {
                out.push(d);
            }
        }
        out
    }

    // ------------------------------------------------------------------
    // ABI generation

    pub fn generate_abi(&mut self, emit_abi: bool, emit_hashes: bool) -> Json {
        // 1. resolve struct types for every struct decl (needed for qualified names)
        let struct_ids: Vec<usize> = (0..self.decls.len())
            .filter(|i| matches!(self.decls[*i].kind, DeclKind::Struct(_)))
            .collect();
        for sid in struct_ids {
            self.contract_members_types(sid);
        }
        let mut contracts_json = Json::obj();
        for cid in 0..self.contracts.len() {
            let key = self.contract_key(cid);
            let value = self.contract_abi(cid, emit_abi, emit_hashes);
            contracts_json.set(&key, value);
        }
        let mut out = Json::obj();
        out.set("contracts", contracts_json);
        out.set("version", Json::Str(crate::cli::VERSION.to_string()));
        out
    }

    pub fn contract_key(&self, cid: usize) -> String {
        let path = self.units[self.contracts[cid].file].display_path.clone();
        format!("{}:{}", path, self.contracts[cid].name)
    }

    fn ctx(&self) -> TypeCtx<'_> {
        let mut m: HashMap<usize, (String, Vec<(String, Option<AbiType>)>)> = HashMap::new();
        for (id, d) in self.decls.iter().enumerate() {
            match &d.kind {
                DeclKind::Struct(members) => {
                    let types = self.struct_types.get(&id).cloned().unwrap_or_default();
                    let mm: Vec<(String, Option<AbiType>)> = members
                        .iter()
                        .enumerate()
                        .map(|(i, (n, _))| (n.clone(), types.get(i).cloned()))
                        .collect();
                    m.insert(id, (self.qualified.get(&id).cloned().unwrap_or_default(), mm));
                }
                DeclKind::Contract(_) => {
                    m.insert(id, (self.qualified.get(&id).cloned().unwrap_or_default(), vec![]));
                }
                DeclKind::Enum(_) => {
                    m.insert(id, (self.qualified.get(&id).cloned().unwrap_or_default(), vec![]));
                }
                _ => {}
            }
        }
        TypeCtx { structs: &m }
    }

    fn contract_abi(&mut self, cid: usize, emit_abi: bool, emit_hashes: bool) -> Json {
        let items = self.all_items(cid);
        let mut resolver = Resolver { g: self };
        let file = self.contracts[cid].file;
        let contract = Some(cid);
        let _ = contract;
        // 1. errors, 2. events, 3. state variables, 4. functions
        let mut errors: Vec<(usize, Vec<Param>, Option<String>)> = vec![];
        let mut events: Vec<(usize, Vec<Param>, bool)> = vec![];
        let mut vars: Vec<(usize, Type, Option<Visibility>, Option<Mutability>)> = vec![];
        let mut funcs: Vec<(usize, FunctionKind, FunctionHeader)> = vec![];
        let mut ctor: Option<usize> = None;
        let mut fallback: Option<usize> = None;
        let mut receive: Option<usize> = None;
        for &d in &items {
            match &self.decls[d].kind {
                DeclKind::Error(params) => errors.push((d, params.clone(), None)),
                DeclKind::Event(params, anonymous) => events.push((d, params.clone(), *anonymous)),
                DeclKind::Variable(ty, vis, mut_, _) => vars.push((d, ty.clone(), *vis, *mut_)),
                DeclKind::Function(kind, header, _body) => {
                    match kind {
                        FunctionKind::Constructor => ctor = Some(d),
                        FunctionKind::Fallback => fallback = Some(d),
                        FunctionKind::Receive => receive = Some(d),
                        _ => funcs.push((d, *kind, header.clone())),
                    }
                }
                _ => {}
            }
        }
        let _ = &mut resolver;
        let mut abi: Vec<(String, Json)> = vec![];
        let mut hashes: BTreeMap<String, ()> = BTreeMap::new();
        // constructor
        if let Some(d) = ctor {
            if emit_abi {
                let header = match &self.decls[d].kind {
                    DeclKind::Function(_, h, _) => h.clone(),
                    _ => unreachable!(),
                };
                let inputs = self.resolve_params(&mut Resolver { g: self }, file, cid, &header.params);
                let mut o = Json::obj();
                o.set("type", Json::Str("constructor".to_string()));
                o.set("inputs", Json::Array(inputs));
                let payable = matches!(header.mutability, Some(Mutability::Payable));
                o.set(
                    "stateMutability",
                    Json::Str(if payable { "payable".to_string() } else { "nonpayable".to_string() }),
                );
                abi.push(("constructor".to_string(), o));
            }
        }
        for (d, params, _) in errors.clone() {
            if !emit_abi {
                continue;
            }
            let inputs = self.resolve_params(&mut Resolver { g: self }, file, cid, &params);
            let mut o = Json::obj();
            o.set("type", Json::Str("error".to_string()));
            o.set("name", Json::Str(self.decls[d].name.clone()));
            o.set("inputs", Json::Array(inputs));
            abi.push(("error".to_string(), o));
        }
        for (d, params, anonymous) in events.clone() {
            if !emit_abi {
                continue;
            }
            let inputs = self.resolve_params(&mut Resolver { g: self }, file, cid, &params);
            let mut o = Json::obj();
            o.set("type", Json::Str("event".to_string()));
            o.set("name", Json::Str(self.decls[d].name.clone()));
            o.set("inputs", Json::Array(inputs));
            o.set("anonymous", Json::Bool(anonymous));
            abi.push(("event".to_string(), o));
        }
        if let Some(d) = fallback {
            if emit_abi {
                let header = match &self.decls[d].kind {
                    DeclKind::Function(_, h, _) => h.clone(),
                    _ => unreachable!(),
                };
                let mut o = Json::obj();
                o.set("type", Json::Str("fallback".to_string()));
                let sm = match header.mutability {
                    Some(Mutability::Payable) => "payable",
                    Some(Mutability::Pure) => "pure",
                    Some(Mutability::View) => "view",
                    _ => "nonpayable",
                };
                o.set("stateMutability", Json::Str(sm.to_string()));
                abi.push(("fallback".to_string(), o));
            }
        }
        // functions: declared functions and public getters
        let mut fn_entries: Vec<(String, Json, String)> = vec![];
        for (d, _kind, header) in funcs.clone() {
            let vis = header.visibility.unwrap_or(Visibility::Internal);
            if !matches!(vis, Visibility::Public | Visibility::External) {
                continue;
            }
            let inputs = self.resolve_params(&mut Resolver { g: self }, file, cid, &header.params);
            let outputs = self.resolve_params(&mut Resolver { g: self }, file, cid, &header.returns);
            let name = header.name.as_ref().map(|(s, _)| s.clone()).unwrap_or_default();
            if !emit_abi {
                continue;
            }
            let mut o = Json::obj();
            o.set("type", Json::Str("function".to_string()));
            o.set("name", Json::Str(name.clone()));
            o.set("inputs", Json::Array(inputs.clone()));
            o.set("outputs", Json::Array(outputs.clone()));
            let sm = match header.mutability {
                Some(Mutability::Pure) => "pure",
                Some(Mutability::View) => "view",
                Some(Mutability::Payable) => "payable",
                _ => "nonpayable",
            };
            o.set("stateMutability", Json::Str(sm.to_string()));
            let sig = format!(
                "{}({})",
                name,
                inputs
                    .iter()
                    .map(|i| crate::abi::canonical_of_json(i))
                    .collect::<Vec<_>>()
                    .join(",")
            );
            hashes.insert(sig.clone(), ());
            fn_entries.push((name, o, sig));
        }
        // getters
        for (d, ty, vis, mut_) in vars.clone() {
            if !matches!(vis, Some(Visibility::Public)) {
                continue;
            }
            let resolved = {
                let mut r = Resolver { g: self };
                r.resolve_type(&ty, self.decls[d].file, Some(cid))
            };
            let Some(t) = resolved else { continue };
            let (idx_params, out_ty, out_components) = self.getter_parts(t);
            let name = self.decls[d].name.clone();
            if !emit_abi {
                continue;
            }
            let ctx = self.ctx();
            let mut inputs = vec![];
            for (n, it) in &idx_params {
                let j = crate::abi::abi_param_json(n, it, None, &ctx, &self.ctx_map());
                inputs.push(j);
            }
            let outputs = vec![crate::abi::getter_output(&out_ty, &out_components, &ctx, &self.ctx_map())];
            let mut o = Json::obj();
            o.set("type", Json::Str("function".to_string()));
            o.set("name", Json::Str(name.clone()));
            o.set("inputs", Json::Array(inputs.clone()));
            o.set("outputs", Json::Array(outputs));
            o.set("stateMutability", Json::Str("view".to_string()));
            let sig = format!(
                "{}({})",
                name,
                inputs
                    .iter()
                    .map(|i| crate::abi::canonical_of_json(i))
                    .collect::<Vec<_>>()
                    .join(",")
            );
            hashes.insert(sig.clone(), ());
            fn_entries.push((name, o, sig));
        }
        if let Some(d) = receive {
            if emit_abi {
                let mut o = Json::obj();
                o.set("type", Json::Str("receive".to_string()));
                o.set("stateMutability", Json::Str("payable".to_string()));
                abi.push(("receive".to_string(), o));
            }
        }
        // sort
        let type_rank = |t: &str| match t {
            "constructor" => 0,
            "error" => 1,
            "event" => 2,
            "fallback" => 3,
            "function" => 4,
            "receive" => 5,
            _ => 6,
        };
        abi.sort_by(|a, b| {
            let (ta, na) = (type_rank(&a.0), &a.1);
            let (tb, nb) = (type_rank(&b.0), &b.1);
            ta.cmp(&tb).then_with(|| name_of(na).cmp(&name_of(nb)))
        });
        fn_entries.sort_by(|a, b| a.0.cmp(&b.0));
        let mut contract_obj = Json::obj();
        if emit_abi {
            contract_obj.set(
                "abi",
                Json::Array(abi.iter().map(|(_, j)| j.clone()).collect()),
            );
        }
        if emit_hashes {
            let mut h = Json::obj();
            let mut sigs: Vec<String> = vec![];
            for (_, _, s) in &fn_entries {
                if !sigs.contains(s) {
                    sigs.push(s.clone());
                }
            }
            sigs.sort();
            for s in sigs {
                let sel = crate::keccak::selector(&s);
                h.set(&s, Json::Str(crate::keccak::hex4(&sel)));
            }
            contract_obj.set("hashes", h);
        }
        contract_obj
    }

    fn ctx_map(&self) -> std::collections::HashMap<usize, (String, Vec<(String, Option<AbiType>)>)> {
        let mut m: HashMap<usize, (String, Vec<(String, Option<AbiType>)>)> = HashMap::new();
        for (id, d) in self.decls.iter().enumerate() {
            match &d.kind {
                DeclKind::Struct(members) => {
                    let types = self.struct_types.get(&id).cloned().unwrap_or_default();
                    let mm: Vec<(String, Option<AbiType>)> = members
                        .iter()
                        .enumerate()
                        .map(|(i, (n, _))| (n.clone(), types.get(i).cloned()))
                        .collect();
                    m.insert(id, (self.qualified.get(&id).cloned().unwrap_or_default(), mm));
                }
                DeclKind::Contract(_) => {
                    m.insert(id, (self.qualified.get(&id).cloned().unwrap_or_default(), vec![]));
                }
                DeclKind::Enum(_) => {
                    m.insert(id, (self.qualified.get(&id).cloned().unwrap_or_default(), vec![]));
                }
                _ => {}
            }
        }
        m
    }

    fn resolve_params(
        &mut self,
        r: &mut Resolver,
        file: usize,
        cid: usize,
        params: &[Param],
    ) -> Vec<Json> {
        let ctx = self.ctx();
        let map = self.ctx_map();
        let mut out = vec![];
        for p in params {
            let name = p.name.as_ref().map(|(s, _)| s.clone()).unwrap_or_default();
            let ty = match &p.ty {
                Some(t) => r.resolve_type(t, file, Some(cid)),
                None => None,
            };
            let t = ty.unwrap_or(AbiType::Unknown);
            out.push(crate::abi::abi_param_json(
                &name,
                &t,
                if p.indexed { Some(true) } else { None },
                &ctx,
                &map,
            ));
        }
        out
    }

    /// Computes the getter parts for a public state variable.
    fn getter_parts(&self, t: AbiType) -> (Vec<(String, AbiType)>, AbiType, Vec<(String, AbiType)>) {
        let mut idx = vec![];
        let mut cur = t;
        loop {
            match cur {
                AbiType::Mapping(k, v) => {
                    idx.push((String::new(), *k));
                    cur = *v;
                }
                AbiType::Array(e, _) => {
                    idx.push((String::new(), AbiType::Elementary(ElementaryType::Uint(256))));
                    cur = *e;
                }
                _ => break,
            }
        }
        match cur {
            AbiType::Tuple(sid) => {
                let members = self.struct_types.get(&sid).cloned().unwrap_or_default();
                let names: Vec<String> = match &self.decls[sid].kind {
                    DeclKind::Struct(m) => m.iter().map(|(n, _)| n.clone()).collect(),
                    _ => vec![],
                };
                let mut comps = vec![];
                for (i, mt) in members.iter().enumerate() {
                    if matches!(mt, AbiType::Array(_, _) | AbiType::Mapping(_, _)) {
                        continue;
                    }
                    comps.push((
                        names.get(i).cloned().unwrap_or_default(),
                        mt.clone(),
                    ));
                }
                (idx, cur, comps)
            }
            _ => (idx, cur, vec![]),
        }
    }
}

fn name_of(j: &Json) -> String {
    match j.get("name") {
        Some(Json::Str(s)) => s.clone(),
        _ => String::new(),
    }
}

fn c3_merge(mut lists: Vec<Vec<usize>>) -> Vec<usize> {
    let mut out: Vec<usize> = vec![];
    loop {
        lists.retain(|l| !l.is_empty());
        if lists.is_empty() {
            break;
        }
        let mut candidate: Option<usize> = None;
        for l in &lists {
            let head = l[0];
            let mut in_tail = false;
            for other in &lists {
                if other.len() > 1 && other[1..].contains(&head) {
                    in_tail = true;
                    break;
                }
            }
            if !in_tail {
                candidate = Some(head);
                break;
            }
        }
        let Some(c) = candidate else {
            let c = lists[0][0];
            out.push(c);
            for l in &mut lists {
                l.retain(|&x| x != c);
            }
            continue;
        };
        if !out.contains(&c) {
            out.push(c);
        }
        for l in &mut lists {
            l.retain(|&x| x != c);
        }
    }
    out
}

pub struct Resolver<'a> {
    pub g: &'a mut Global,
}

impl<'a> Resolver<'a> {
    pub fn resolve_type(&mut self, ty: &Type, file: usize, contract: Option<usize>) -> Option<AbiType> {
        match &ty.kind {
            TypeKind::Elementary(e) => Some(AbiType::Elementary(*e)),
            TypeKind::UserDefined(path) => self.resolve_path(path, file, contract),
            TypeKind::Mapping(k, v) => {
                let kt = self.resolve_type(k, file, contract)?;
                let vt = self.resolve_type(v, file, contract)?;
                Some(AbiType::Mapping(Box::new(kt), Box::new(vt)))
            }
            TypeKind::Array(elem, size) => {
                let et = self.resolve_type(elem, file, contract)?;
                let len = size.as_ref().and_then(crate::lower::eval_const);
                Some(AbiType::Array(Box::new(et), len))
            }
            TypeKind::Function(params, rets, vis, mut_) => {
                let mut ps = vec![];
                for p in params {
                    if let Some(t) = &p.ty {
                        ps.push(self.resolve_type(t, file, contract)?);
                    }
                }
                let mut rs = vec![];
                for p in rets {
                    if let Some(t) = &p.ty {
                        rs.push(self.resolve_type(t, file, contract)?);
                    }
                }
                Some(AbiType::Function {
                    params: ps,
                    rets: rs,
                    vis: *vis,
                    mut_: *mut_,
                })
            }
        }
    }

    pub fn resolve_path(&mut self, path: &Path, file: usize, contract: Option<usize>) -> Option<AbiType> {
        let first = &path.idents[0].0;
        if path.idents.len() > 1 {
            // alias lookup: X.member
            if let Some(&f) = self.g.alias_map.get(file).and_then(|m| m.get(first)) {
                let name = &path.idents[1].0;
                let sp = path.idents[1].1;
                if let Some(&d) = self.g.file_scope.get(f).and_then(|m| m.get(name)) {
                    return self.decl_to_type(d, sp);
                }
                self.g
                    .diagnostics
                    .push(Diag::error(format!("unresolved symbol `{name}`")).with_span(sp));
                return None;
            }
            if let Some(c) = self.g.lookup_contract(file, first) {
                let decl_id = self.g.contracts[c].decl;
                let name = &path.idents[1].0;
                let sp = path.idents[1].1;
                if let Some(&d) = self.g.contract_scope.get(c).and_then(|m| m.get(name)) {
                    return self.decl_to_type(d, sp);
                }
                let _ = decl_id;
                self.g
                    .diagnostics
                    .push(Diag::error(format!("unresolved symbol `{name}`")).with_span(sp));
                return None;
            }
            self.g
                .diagnostics
                .push(Diag::error(format!("unresolved symbol `{first}`")).with_span(path.idents[0].1));
            return None;
        }
        if let Some(c) = contract {
            if let Some(&d) = self.g.contract_scope.get(c).and_then(|m| m.get(first)) {
                return self.decl_to_type(d, path.idents[0].1);
            }
        }
        if let Some(&d) = self.g.file_scope.get(file).and_then(|m| m.get(first)) {
            if let DeclKind::Contract(c) = self.g.decls[d].kind {
                return Some(AbiType::Contract(c));
            }
            return self.decl_to_type(d, path.idents[0].1);
        }
        for f in self.g.import_targets.get(file).cloned().unwrap_or_default() {
            if let Some(&d) = self.g.file_scope.get(f).and_then(|m| m.get(first)) {
                if let DeclKind::Contract(c) = self.g.decls[d].kind {
                    return Some(AbiType::Contract(c));
                }
                return self.decl_to_type(d, path.idents[0].1);
            }
        }
        self.g
            .diagnostics
            .push(Diag::error(format!("unresolved symbol `{first}`")).with_span(path.idents[0].1));
        None
    }

    fn decl_to_type(&mut self, d: usize, span: Span) -> Option<AbiType> {
        match &self.g.decls[d].kind {
            DeclKind::Contract(_) => Some(AbiType::Contract(d)),
            DeclKind::Struct(_) => Some(AbiType::Tuple(d)),
            DeclKind::Enum(_) => Some(AbiType::Enum(d)),
            _ => {
                let n = self.g.decls[d].name.clone();
                self.g
                    .diagnostics
                    .push(Diag::error(format!("unresolved symbol `{n}`")).with_span(span));
                None
            }
        }
    }
}

pub fn eval_const(e: &Expr) -> Option<u64> {
    match &e.kind {
        ExprKind::Lit(LitKind::Number(s)) => {
            let s: String = s.chars().filter(|c| *c != '_').collect();
            if let Some(hex) = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
                u64::from_str_radix(hex, 16).ok()
            } else {
                s.parse::<u64>().ok()
            }
        }
        ExprKind::Lit(LitKind::Rational(s)) => s.split('.').next()?.parse::<u64>().ok(),
        ExprKind::Unary(op, e, _) => {
            let v = eval_const(e)?;
            match op.as_str() {
                "-" => Some((0i64.wrapping_sub(v as i64)) as u64),
                "~" => Some(!v),
                "+" => Some(v),
                _ => None,
            }
        }
        ExprKind::Binary(op, a, b) => {
            let x = eval_const(a)?;
            let y = eval_const(b)?;
            match op.as_str() {
                "+" => Some(x.wrapping_add(y)),
                "-" => Some(x.wrapping_sub(y)),
                "*" => Some(x.wrapping_mul(y)),
                "/" => if y == 0 { None } else { Some(x / y) },
                "%" => if y == 0 { None } else { Some(x % y) },
                "**" => Some(x.pow(y.min(63) as u32)),
                "<<" => Some(x << y.min(63)),
                ">>" => Some(x >> y.min(63)),
                "&" => Some(x & y),
                "|" => Some(x | y),
                "^" => Some(x ^ y),
                _ => None,
            }
        }
        ExprKind::Tuple(items) => {
            if items.len() == 1 {
                items[0].as_ref().and_then(eval_const)
            } else {
                None
            }
        }
        _ => None,
    }
}
