//! Diagnostic rendering (rustc/annotate-snippets style).

use crate::cli::{Color, HumanStyle};
use crate::diag::{Diag, Severity};
use crate::span::{char_width, str_width, Span};
use std::collections::HashMap;

pub const BOLD: &str = "\x1b[1m";
pub const RESET: &str = "\x1b[0m";

pub struct SourceText {
    pub text: String,
    /// byte offset of the start of each line
    pub lines: Vec<usize>,
    pub line_count: usize,
}

impl SourceText {
    pub fn new(text: &str) -> SourceText {
        let mut lines = vec![0usize];
        for (i, b) in text.bytes().enumerate() {
            if b == b'\n' {
                lines.push(i + 1);
            }
        }
        let line_count = lines.len();
        SourceText {
            text: text.to_string(),
            lines,
            line_count,
        }
    }

    pub fn line_of(&self, offset: usize) -> usize {
        let mut lo = 0usize;
        let mut hi = self.lines.len();
        while lo + 1 < hi {
            let mid = (lo + hi) / 2;
            if self.lines[mid] <= offset {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        lo
    }

    pub fn col_of(&self, offset: usize) -> usize {
        let l = self.line_of(offset);
        let start = self.lines[l];
        self.text[start..offset.min(self.text.len())].chars().count()
    }

    /// The raw text of a line (without the trailing newline).
    pub fn line_text(&self, line: usize) -> &str {
        let start = self.lines[line];
        let end = self
            .lines
            .get(line + 1)
            .map(|e| e - 1)
            .unwrap_or(self.text.len());
        let s = &self.text[start..end.min(self.text.len())];
        s.trim_end_matches('\r')
    }

    /// Display offset of a byte offset within its line (tabs expanded).
    pub fn display_offset(&self, offset: usize) -> usize {
        let l = self.line_of(offset);
        let start = self.lines[l];
        let s = &self.text[start..offset.min(self.text.len())];
        let mut w = 0usize;
        for c in s.chars() {
            w += if c == '\t' { 4 - (w % 4) } else { char_width(c) };
        }
        w
    }

    /// Display width of the byte range [start, end)
    pub fn display_width(&self, start: usize, end: usize) -> usize {
        let s = &self.text[start.min(self.text.len())..end.min(self.text.len())];
        let mut w = 0usize;
        for c in s.chars() {
            w += if c == '\t' { 4 - (w % 4) } else { char_width(c) };
        }
        w
    }

    /// The text of a byte range with tabs expanded.
    pub fn display_text(&self, start: usize, end: usize) -> String {
        let s = &self.text[start.min(self.text.len())..end.min(self.text.len())];
        let mut out = String::new();
        let mut w = 0usize;
        for c in s.chars() {
            if c == '\t' {
                let n = 4 - (w % 4);
                for _ in 0..n {
                    out.push(' ');
                }
                w += n;
            } else if (c as u32) < 0x20 || c as u32 == 0x7f {
                let cp = c as u32;
                let pic = char::from_u32(0x2400 + cp).unwrap_or(c);
                out.push(pic);
                w += 1;
            } else {
                out.push(c);
                w += char_width(c);
            }
        }
        out
    }
}

pub struct Renderer {
    pub style: HumanStyle,
    pub color: bool,
    pub width: usize,
    pub sources: HashMap<u32, SourceText>,
    pub paths: HashMap<u32, String>,
}

#[derive(Clone)]
struct Annotation {
    start: usize,
    end: usize,
    primary: bool,
    label: Option<String>,
    /// a "hanging" annotation (dashed connector with a label below)
    hanging: bool,
}

impl Renderer {
    fn colors(&self) -> (String, String, String) {
        if !self.color {
            return (String::new(), String::new(), String::new());
        }
        (BOLD.to_string(), RESET.to_string(), BOLD.to_string())
    }

    fn severity_label(&self, sev: Severity, code: Option<&str>) -> String {
        let (bold, reset, _) = self.colors();
        match sev {
            Severity::Error => {
                let name = match code {
                    Some(c) => format!("error[{}]", c),
                    None => "error".to_string(),
                };
                format!("{}{}{}{}: ", bold, red(self.color), name, reset)
            }
            Severity::Warning => {
                let name = match code {
                    Some(c) => format!("warning[{}]", c),
                    None => "warning".to_string(),
                };
                format!("{}{}{}{}: ", bold, yellow(self.color), name, reset)
            }
            Severity::Note => format!("{}{}{}: ", bold, green(self.color), "note"),
        }
    }

    fn severity_body_bold(&self, sev: Severity) -> bool {
        matches!(sev, Severity::Error | Severity::Warning)
    }

    fn gutter_str(&self, digits: usize) -> String {
        match self.style {
            HumanStyle::Unicode => format!("{}{}", " ".repeat(digits + 1), style(self.color, BOLD, "94", "│")),
            _ => format!("{}{}", " ".repeat(digits + 1), style(self.color, BOLD, "94", "|")),
        }
    }

    fn loc_marker(&self) -> String {
        match self.style {
            HumanStyle::Unicode => style(self.color, BOLD, "94", " ╭▸ "),
            _ => style(self.color, BOLD, "94", "--> "),
        }
    }

    fn close_marker(&self, with_footer: bool) -> String {
        match self.style {
            HumanStyle::Unicode => {
                if with_footer {
                    style(self.color, BOLD, "94", "╰")
                } else {
                    style(self.color, BOLD, "94", "╰╴")
                }
            }
            _ => {
                if with_footer {
                    style(self.color, BOLD, "94", "=")
                } else {
                    style(self.color, BOLD, "94", "|")
                }
            }
        }
    }

    fn marker_color(&self, primary: bool, sev: Severity) -> &'static str {
        match sev {
            Severity::Error => {
                if primary {
                    "91"
                } else {
                    "94"
                }
            }
            Severity::Warning => {
                if primary {
                    "93"
                } else {
                    "94"
                }
            }
            Severity::Note => {
                if primary {
                    "92"
                } else {
                    "92"
                }
            }
        }
    }

    fn marker_char(&self, primary: bool) -> &str {
        match self.style {
            HumanStyle::Unicode => {
                if primary {
                    "━"
                } else {
                    "─"
                }
            }
            _ => "^",
        }
    }

    fn dash_char(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "─",
            _ => "-",
        }
    }

    fn connector_start(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "┬",
            _ => "-",
        }
    }

    fn bar_char(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "│",
            _ => "|",
        }
    }

    fn multiline_start(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "┏",
            _ => "^",
        }
    }

    fn multiline_end(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "┛",
            _ => "^",
        }
    }

    fn multiline_bar(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "┃",
            _ => "|",
        }
    }

    fn multiline_close(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "┗",
            _ => "^",
        }
    }

    fn arrow(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "↖",
            _ => "^",
        }
    }

    fn ellipsis(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "…",
            _ => "...",
        }
    }

    /// Renders a single diagnostic.
    pub fn render(&self, d: &Diag, extra_children: &[Diag]) -> String {
        let mut out = String::new();
        let (bold, reset, _) = self.colors();
        let header = self.severity_label(d.severity, d.code);
        let body_bold = self.severity_body_bold(d.severity);
        if body_bold {
            out.push_str(&format!("{}{}{}{}\n", header, bold, d.message, reset));
        } else {
            out.push_str(&format!("{}{}\n", header, d.message));
        }
        let mut spans: Vec<Annotation> = vec![];
        if let Some(p) = &d.primary {
            spans.push(Annotation {
                start: p.span.start as usize,
                end: p.span.end as usize,
                primary: true,
                label: p.label.clone(),
                hanging: false,
            });
        }
        for s in &d.secondary {
            spans.push(Annotation {
                start: s.span.start as usize,
                end: s.span.end as usize,
                primary: false,
                label: s.label.clone(),
                hanging: false,
            });
        }
        let mut footer_spans: Vec<Annotation> = vec![];
        let mut footers: Vec<(String, Option<usize>)> = vec![];
        for (i, (text, span)) in d.notes.iter().enumerate() {
            let _ = i;
            footers.push((format!("note: {text}"), span.map(|s| s.start as usize)));
        }
        for (text, span) in &d.helps {
            footers.push((format!("help: {text}"), span.map(|s| s.start as usize)));
        }
        if spans.is_empty() && footers.is_empty() && extra_children.is_empty() {
            return out;
        }
        // group spans by file
        let file = spans
            .first()
            .map(|a| self.file_of(a.start))
            .or_else(|| footers.iter().find_map(|(_, s)| *s).map(|s| self.file_of(s)));
        let Some(file) = file else {
            return out;
        };
        let src = match self.sources.get(&file) {
            Some(s) => s,
            None => return out,
        };
        // split footers with spans into hanging annotations
        for (text, span) in footers {
            if let Some(s) = span {
                footer_spans.push(Annotation {
                    start: s,
                    end: s,
                    primary: false,
                    label: None,
                    hanging: true,
                });
                footers.push((text, Some(s)));
            } else {
                footers.push((text, None));
            }
        }
        let _ = footer_spans;
        let digits = src.line_count.to_string().len().max(1);
        let primary = spans.iter().find(|a| a.primary).cloned();
        let first = spans
            .iter()
            .min_by_key(|a| a.start)
            .cloned()
            .unwrap_or(Annotation {
                start: 0,
                end: 0,
                primary: false,
                label: None,
                hanging: false,
            });
        let loc_span = primary.clone().unwrap_or(first.clone());
        let line = src.line_of(loc_span.start);
        let col = src.col_of(loc_span.start) + 1;
        let path = self
            .paths
            .get(&file)
            .cloned()
            .unwrap_or_default();
        out.push_str(&format!(
            "{}{}{}:{}:{}\n",
            " ".repeat(digits),
            self.loc_marker(),
            path,
            line + 1,
            col
        ));
        let min_line = spans
            .iter()
            .map(|a| src.line_of(a.start))
            .chain(footer_spans.iter().map(|a| src.line_of(a.start)))
            .min()
            .unwrap_or(line);
        let max_line = spans
            .iter()
            .map(|a| src.line_of(a.end.saturating_sub(1)))
            .chain(footer_spans.iter().map(|a| src.line_of(a.start)))
            .max()
            .unwrap_or(line);
        // annotations on each line
        let mut by_line: HashMap<usize, Vec<Annotation>> = HashMap::new();
        for a in &spans {
            let l0 = src.line_of(a.start);
            let l1 = src.line_of(a.end.saturating_sub(1).min(src.text.len()));
            if l0 == l1 {
                by_line.entry(l0).or_default().push(a.clone());
            } else {
                // multi-line span
                by_line.entry(l0).or_default().push(Annotation {
                    start: a.start,
                    end: a.end,
                    primary: a.primary,
                    label: a.label.clone(),
                    hanging: false,
                });
                if l0 + 1 < l1 {
                    by_line.entry(l0 + 1).or_default().push(a.clone());
                }
            }
        }
        for l in min_line..=max_line {
            let content = src.line_text(l);
            let line_no = (l + 1).to_string();
            let pad = " ".repeat(digits.saturating_sub(line_no.len()));
            let has_ml = spans
                .iter()
                .any(|a| src.line_of(a.start) != src.line_of(a.end.saturating_sub(1).min(src.text.len())));
            if has_ml {
                out.push_str(&self.multiline_line(src, l, &line_no, &pad, spans.as_slice(), d));
                continue;
            }
            out.push_str(&format!(
                "{}{} {}{} {}\n",
                pad,
                style(self.color, BOLD, "94", &line_no),
                self.gutter_char(),
                style(self.color, BOLD, "94", ""),
                truncate_line(self, content, &by_line, l, src)
            ));
            let anns = by_line.get(&l).cloned().unwrap_or_default();
            if !anns.is_empty() {
                out.push_str(&self.annotation_line(digits, src, l, &anns, d.severity));
            }
            if !anns.is_empty() {
                out.push_str(&self.gutter_str(digits));
                out.push('\n');
            }
        }
        // closing line
        let has_footer = footers.iter().any(|(_, s)| s.is_none());
        out.push_str(&format!("{}{}", " ".repeat(digits + 1), self.close_marker(has_footer)));
        let mut labels: Vec<(usize, String)> = vec![];
        for a in &spans {
            if a.label.is_some() && src.line_of(a.start) == src.line_of(a.end.saturating_sub(1).min(src.text.len())) {
                // inline label: printed after the marker, not on the closing line
            } else if let Some(lb) = &a.label {
                labels.push((src.display_offset(a.start), lb.clone()));
            }
        }
        if !labels.is_empty() {
            let maxoff = labels.iter().map(|(o, _)| *o).max().unwrap_or(0);
            let mut s = String::new();
            let mut cur = 0usize;
            let mut parts: Vec<(usize, String)> = labels.clone();
            parts.sort_by_key(|(o, _)| *o);
            for (o, lb) in parts {
                while cur < o {
                    s.push(' ');
                    cur += 1;
                }
                if cur > o {
                    s.push(' ');
                    cur += 1;
                }
                s.push_str(lb.as_str());
                cur += str_width(lb);
            }
            let _ = maxoff;
            out.push(' ');
            out.push_str(&s);
        }
        out.push('\n');
        // footers
        let mut first_footer = true;
        for (text, span) in &footers {
            if span.is_some() {
                continue;
            }
            if self.style == HumanStyle::Unicode {
                if first_footer {
                    out.push_str(&format!("{} {} {}\n", " ".repeat(digits + 1), style(self.color, BOLD, "94", "╰╴"), text));
                    first_footer = false;
                } else {
                    out.push_str(&format!("{} {}\n", " ".repeat(digits + 1), text));
                }
            } else {
                if first_footer {
                    out.push_str(&format!("{} {} {}\n", " ".repeat(digits + 1), style(self.color, BOLD, "94", "="), text));
                    first_footer = false;
                } else {
                    out.push_str(&format!("{} {}\n", " ".repeat(digits + 1), text));
                }
            }
        }
        out
    }

    fn gutter_char(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "│",
            _ => "|",
        }
    }

    fn file_of(&self, _offset: usize) -> u32 {
        0
    }

    fn multiline_line(
        &self,
        src: &SourceText,
        line: usize,
        line_no: &str,
        pad: &str,
        spans: &[Annotation],
        d: &Diag,
    ) -> String {
        let _ = (spans, d, pad);
        let content = src.line_text(line);
        let digits = src.line_count.to_string().len().max(1);
        let ml = spans
            .iter()
            .find(|a| src.line_of(a.start) != src.line_of(a.end.saturating_sub(1).min(src.text.len())));
        let Some(a) = ml else {
            return String::new();
        };
        let l0 = src.line_of(a.start);
        let l1 = src.line_of(a.end.saturating_sub(1).min(src.text.len()));
        let is_first = line == l0;
        let is_last = line == l1;
        let start_off = src.display_offset(a.start);
        let prefix_ws = {
            let s = src.display_text(src.lines[line], a.start);
            s.chars().all(|c| c == ' ')
        };
        let ends_mid = {
            let lstart = src.lines[l1];
            let lend = src.lines.get(l1 + 1).map(|e| e - 1).unwrap_or(src.text.len());
            let _ = (lstart, lend);
            (a.end as usize) < lend
        };
        let mut out = String::new();
        let line_marker = if is_first {
            self.multiline_start()
        } else if is_last {
            self.multiline_close()
        } else {
            self.multiline_bar()
        };
        let shifted = if is_first {
            !(starts_at_line_end(src, a) ) && prefix_ws
        } else {
            !ends_mid
        };
        if shifted {
            out.push_str(&format!(
                "{}{} {}{} {}{}\n",
                pad,
                style(self.color, BOLD, "94", line_no),
                " ",
                self.gutter_str(0),
                style(self.color, BOLD, "94", line_marker),
                " "
            ));
            out.push_str(&src.display_text(src.lines[line], src.lines.get(line + 1).map(|e| e - 1).unwrap_or(src.text.len())));
            out.push('\n');
        } else {
            out.push_str(&format!(
                "{}{} {}{} {}\n",
                pad,
                style(self.color, BOLD, "94", line_no),
                self.gutter_char(),
                style(self.color, BOLD, "94", ""),
                truncate_content(self, content)
            ));
        }
        if is_first && !shifted {
            // separate marker line with dashes
            out.push_str(&self.gutter_str(digits));
            out.push(' ');
            out.push_str(&style(self.color, BOLD, "94", self.multiline_start()));
            for _ in 0..start_off {
                out.push_str(&style(self.color, BOLD, "94", self.dash_char()));
            }
            out.push_str(&style(self.color, BOLD, "94", self.multiline_end()));
            out.push('\n');
        }
        if is_first && shifted && a.label.is_some() {
            // label placed on the annotation line
            out.push_str(&self.gutter_str(digits));
            out.push('\n');
        }
        if is_last && ends_mid {
            out.push_str(&self.close_with_label(digits, src, a, d));
        }
        out
    }

    fn close_with_label(&self, digits: usize, src: &SourceText, a: &Annotation, d: &Diag) -> String {
        let _ = d;
        let mut out = String::new();
        out.push_str(&format!("{}{}", " ".repeat(digits + 1), self.close_marker(false)));
        let off = src.display_offset(a.start);
        for _ in 0..(off + 1) {
            out.push(' ');
        }
        let w = src.display_width(a.start, a.end);
        out.push_str(&style(
            self.color,
            BOLD,
            self.marker_color(a.primary, Severity::Error),
            &self.marker_char(a.primary).repeat(w),
        ));
        if let Some(lb) = &a.label {
            out.push(' ');
            out.push_str(lb);
        }
        out.push('\n');
        out
    }

    fn annotation_line(
        &self,
        digits: usize,
        src: &SourceText,
        line: usize,
        anns: &[Annotation],
        sev: Severity,
    ) -> String {
        let mut out = String::new();
        out.push_str(&self.gutter_str(digits));
        out.push(' ');
        let mut pieces: Vec<(usize, usize, String)> = vec![];
        let sorted: Vec<&Annotation> = {
            let mut v: Vec<&Annotation> = anns.iter().collect();
            v.sort_by_key(|a| a.start);
            v
        };
        let last = sorted.len().saturating_sub(1);
        for (i, a) in sorted.iter().enumerate() {
            if src.line_of(a.start) != line {
                continue;
            }
            let start = src.display_offset(a.start);
            let w = src.display_width(a.start, a.end).max(1);
            let is_last_ann = i == last;
            let hanging = !is_last_ann && sorted.len() > 1;
            if hanging {
                let s = format!(
                    "{}{}",
                    style(self.color, BOLD, "94", self.connector_start()),
                    style(self.color, BOLD, "94", &self.dash_char().repeat(w.saturating_sub(1)))
                );
                pieces.push((start, start + w, s));
            } else {
                let s = style(
                    self.color,
                    BOLD,
                    self.marker_color(a.primary, sev),
                    &self.marker_char(a.primary).repeat(w),
                );
                pieces.push((start, start + w, s));
            }
        }
        pieces.sort_by_key(|p| p.0);
        let mut cur = 0usize;
        for (s, _e, txt) in pieces {
            while cur < s {
                out.push(' ');
                cur += 1;
            }
            if cur > s {
                out.push(' ');
                cur += 1;
            }
            out.push_str(&txt);
            cur = s + str_width(&strip_ansi(&txt));
        }
        // inline label for the last annotation
        if let Some(a) = sorted.last() {
            if src.line_of(a.start) == line {
                if let Some(lb) = &a.label {
                    if sorted.len() == 1 {
                        out.push(' ');
                        out.push_str(lb);
                    }
                }
            }
        }
        out.push('\n');
        // hanging bars and labels
        let hung: Vec<&Annotation> = sorted
            .iter()
            .enumerate()
            .filter(|(i, a)| *i != last && sorted.len() > 1 && src.line_of(a.start) == line)
            .map(|(_, a)| *a)
            .collect();
        if !hung.is_empty() {
            out.push_str(&self.gutter_str(digits));
            out.push(' ');
            let mut cur = 0usize;
            let mut positions: Vec<usize> = hung.iter().map(|a| src.display_offset(a.start)).collect();
            positions.sort();
            positions.dedup();
            for p in positions {
                while cur < p {
                    out.push(' ');
                    cur += 1;
                }
                if cur > p {
                    out.push(' ');
                    cur += 1;
                }
                out.push_str(&style(self.color, BOLD, "94", self.bar_char()));
                cur += 1;
            }
            out.push('\n');
        }
        out
    }
}

fn starts_at_line_end(src: &SourceText, a: &Annotation) -> bool {
    let l = src.line_of(a.start);
    let lend = src.lines.get(l + 1).map(|e| e - 1).unwrap_or(src.text.len());
    a.start >= lend
}

fn strip_ansi(s: &str) -> String {
    let mut out = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\x1b' {
            for c2 in chars.by_ref() {
                if c2 == 'm' {
                    break;
                }
            }
        } else {
            out.push(c);
        }
    }
    out
}

fn style(color: bool, bold: &str, code: &str, text: &str) -> String {
    if !color || text.is_empty() {
        return text.to_string();
    }
    format!("{}{}{}{}{}{}", bold, "\x1b[", code, "m", text, RESET)
}

fn red(color: bool) -> String {
    if color {
        "\x1b[91m".to_string()
    } else {
        String::new()
    }
}
fn green(color: bool) -> String {
    if color {
        "\x1b[92m".to_string()
    } else {
        String::new()
    }
}
fn yellow(color: bool) -> String {
    if color {
        "\x1b[93m".to_string()
    } else {
        String::new()
    }
}

fn truncate_content(r: &Renderer, content: &str) -> String {
    let w = str_width(content);
    if w + 4 <= r.width {
        return content.to_string();
    }
    let budget = r.width.saturating_sub(4);
    let mut out = String::new();
    let mut cur = 0usize;
    for c in content.chars() {
        let cw = if c == '\t' { 4 - (cur % 4) } else { char_width(c) };
        if cur + cw > budget {
            break;
        }
        if c == '\t' {
            for _ in 0..cw {
                out.push(' ');
            }
        } else {
            out.push(c);
        }
        cur += cw;
    }
    format!("{}{}", out, r.ellipsis())
}

fn truncate_line(
    _r: &Renderer,
    content: &str,
    _anns: &std::collections::HashMap<usize, Vec<Annotation>>,
