    fn mchar(&self, primary: bool) -> &str {
        match self.style {
            HumanStyle::Unicode => {
                if primary { "━" } else { "─" }
            }
            _ => "^",
        }
    }
    fn dash(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "─",
            _ => "-",
        }
    }
    fn conn(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "┬",
            _ => "-",
        }
    }
    fn ml_start(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "┏",
            _ => "^",
        }
    }
    fn ml_bar(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "┃",
            _ => "|",
        }
    }
    fn ml_end(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "┛",
            _ => "^",
        }
    }
    fn ml_close(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "┗",
            _ => "^",
        }
    }
    fn arrow(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "↖",
            _ => "^",
        }
    }
    fn ellip(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "…",
            _ => "...",
        }
    }
    fn color_of(&self, primary: bool, sev: Severity) -> String {
        match sev {
            Severity::Note => "92".to_string(),
            _ => {
                if primary {
                    self.sev_color(sev).to_string()
                } else {
                    "94".to_string()
                }
            }
        }
    }

    pub fn render(
        &self,
        d: &Diag,
        path: &str,
        src: Option<&SourceText>,
        file: u32,
        extra: &[Diag],
    ) -> String {
        let mut out = String::new();
        let header = match d.code {
            Some(c) => format!("{}[{}]", match d.severity { Severity::Error => "error", Severity::Warning => "warning", Severity::Note => "note" }, c),
            None => match d.severity {
                Severity::Error => "error".to_string(),
                Severity::Warning => "warning".to_string(),
                Severity::Note => "note".to_string(),
            },
        };
        let code = self.sev_color(d.severity);
        let body_bold = matches!(d.severity, Severity::Error | Severity::Warning);
        if body_bold {
            out.push_str(&format!(
                "{}{}{}{}{}: {}\n",
                BOLD,
                self.st_code(code),
                header,
                RESET,
                if self.color { BOLD } else { "" },
                d.message
            ));
            if self.color {
                out.push_str(RESET);
            }
            // remove trailing RESET duplication
        } else {
            out.push_str(&format!("{}{}{}{}: {}\n", BOLD, self.st_code(code), header, RESET, d.message));
        }
        // gather annotations
        let mut anns: Vec<Ann> = vec![];
        if let Some(p) = &d.primary {
            anns.push(Ann { start: p.span.start as usize, end: p.span.end as usize, primary: true, label: p.label.clone() });
        }
        for s in &d.secondary {
            anns.push(Ann { start: s.span.start as usize, end: s.span.end as usize, primary: false, label: s.label.clone() });
        }
        let mut footers: Vec<(String, Option<usize>)> = vec![];
        for (text, span) in &d.notes {
            footers.push((format!("note: {text}"), span.map(|s| s.start as usize)));
        }
        for (text, span) in &d.helps {
            footers.push((format!("help: {text}"), span.map(|s| s.start as usize)));
        }
        if anns.is_empty() && footers.iter().all(|(_, s)| s.is_none()) {
            return out;
        }
        let Some(src) = src else { return out };
        let _ = file;
        // footers with spans become hanging annotations
        let mut hanging: Vec<(usize, String)> = vec![];
        footers.retain(|(t, s)| {
            if let Some(off) = s {
                hanging.push((*off, t.clone()));
                false
            } else {
                true
            }
        });
        for (off, t) in hanging.clone() {
            anns.push(Ann { start: off, end: off, primary: false, label: None });
            footers.push((t, Some(off)));
        }
        let digits = src.line_count.to_string().len().max(1);
        anns.sort_by_key(|a| a.start);
        let primary_ann = anns.iter().position(|a| a.primary);
        let loc = anns.get(primary_ann.unwrap_or(0)).cloned().unwrap_or(Ann { start: 0, end: 0, primary: false, label: None });
        let line = src.line_of(loc.start);
        let col = src.col_of(loc.start) + 1;
        out.push_str(&format!(
            "{}{}{}:{}:{}\n",
            " ".repeat(digits),
            self.locmark(),
            path,
            line + 1,
            col
        ));
        let min_line = anns.iter().map(|a| src.line_of(a.start)).min().unwrap_or(line);
        let max_line = anns.iter().map(|a| src.line_of(a.end.saturating_sub(1).min(src.text.len()))).max().unwrap_or(line);
        let multi = max_line > min_line;
        if !multi {
            out.push_str(&self.gutter(digits));
            out.push('\n');
            let content = self.truncate(src, src.line_text(line), src.display_offset(loc.start), &anns);
            out.push_str(&format!(
                "{}{} {} {} {}\n",
                " ".repeat(digits.saturating_sub((line + 1).to_string().len())),
                self.st("94", &(line + 1).to_string()),
                self.gch(),
                self.st("94", ""),
                content
            ));
            out.push_str(&self.annotation_lines(digits, src, line, &anns, d.severity));
        } else {
            out.push_str(&self.multiline(digits, src, &anns, d));
        }
        // closing line
        let has_footer = footers.iter().any(|(_, s)| s.is_none());
        out.push_str(&format!("{}{}", " ".repeat(digits + 1), self.closemark(has_footer)));
        if !multi {
            let last = anns.last();
            if let Some(a) = last {
                if anns.len() == 1 && a.label.is_none() {
                    let start = src.display_offset(a.start);
                    for _ in 0..start {
                        out.push(' ');
                    }
                    let w = src.display_width(a.start, a.end).max(1);
                    out.push_str(&self.st(&self.color_of(a.primary, d.severity), &self.mchar(a.primary).repeat(w)));
                }
            }
        }
        let mut labels: Vec<(usize, String)> = vec![];
        for a in &anns {
            if let Some(lb) = &a.label {
                if multi || anns.len() > 1 {
                    labels.push((src.display_offset(a.start), lb.clone()));
                }
            }
        }
        if !labels.is_empty() {
            labels.sort_by_key(|(o, _)| *o);
            out.push(' ');
            let mut cur = 0usize;
            for (o, lb) in labels {
                while cur < o {
                    out.push(' ');
                    cur += 1;
                }
                if cur > o {
                    out.push(' ');
                    cur += 1;
                }
                out.push_str(&lb);
                cur += str_width(&lb);
            }
        }
        out.push('\n');
        for (text, span) in &footers {
            if span.is_some() {
                continue;
            }
            out.push_str(&format!(
                "{} {} {}\n",
                " ".repeat(digits + 1),
                if has_footer {
                    self.st("94", "")
                } else {
                    String::new()
                },
                text
            ));
        }
        out
    }

    fn st_code(&self, _code: &str) -> &'static str {
        "\x1b["
    }

    fn annotation_lines(&self, digits: usize, src: &SourceText, line: usize, anns: &[Ann], sev: Severity) -> String {
        let mut out = String::new();
        let last = anns.len().saturating_sub(1);
        let mut marker = String::new();
        let mut cur = 0usize;
        let mut hung: Vec<usize> = vec![];
        for (i, a) in anns.iter().enumerate() {
            let start = src.display_offset(a.start);
            let w = src.display_width(a.start, a.end).max(1);
            let is_last = i == last;
            while cur < start {
                marker.push(' ');
                cur += 1;
            }
            if cur > start {
                marker.push(' ');
                cur += 1;
            }
            if is_last {
                marker.push_str(&self.st(&self.color_of(a.primary, sev), &self.mchar(a.primary).repeat(w)));
            } else {
                marker.push_str(&self.st("94", &format!("{}{}", self.conn(), self.dash().repeat(w.saturating_sub(1)))));
                hung.push(src.display_offset(a.start));
            }
            cur = start + w;
        }
        if !marker.is_empty() {
            out.push_str(&self.gutter(digits));
            out.push(' ');
            out.push_str(&marker);
            if anns.len() == 1 {
                if let Some(lb) = &anns[last].label {
                    out.push(' ');
                    out.push_str(lb);
                }
            }
            out.push('\n');
        }
        if !hung.is_empty() {
            out.push_str(&self.gutter(digits));
            out.push(' ');
            hung.sort();
            hung.dedup();
            let mut cur = 0usize;
            for p in hung {
                while cur < p {
                    out.push(' ');
                    cur += 1;
                }
                if cur > p {
                    out.push(' ');
                    cur += 1;
                }
                out.push_str(&self.st("94", self.gch()));
                cur += 1;
            }
            out.push('\n');
        }
        out
    }

    fn multiline(&self, digits: usize, src: &SourceText, anns: &[Ann], d: &Diag) -> String {
        let mut out = String::new();
        let a = anns.iter().find(|a| src.line_of(a.start) != src.line_of(a.end.saturating_sub(1).min(src.text.len()))).cloned().unwrap_or(Ann { start: 0, end: 0, primary: false, label: None });
        let l0 = src.line_of(a.start);
        let l1 = src.line_of(a.end.saturating_sub(1).min(src.text.len()));
        let start_off = src.display_offset(a.start);
        let ends_mid = a.end < src.line_end(l1);
        for l in l0..=l1 {
            let line_no = (l + 1).to_string();
            let pad = " ".repeat(digits.saturating_sub(line_no.len()));
            let is_first = l == l0;
            let is_last = l == l1;
            if is_first && a.start >= src.line_end(l0) {
                // span starts at the end of the line
                out.push_str(&format!(
                    "{}{} {} {} {}\n",
                    pad,
                    self.st("94", &line_no),
                    self.gch(),
                    self.st("94", ""),
                    self.truncate(src, src.line_text(l), start_off, anns)
                ));
                out.push_str(&self.gutter(digits));
                out.push(' ');
                out.push_str(&self.st("94", self.arrow()));
                out.push(' ');
                if let Some(lb) = &a.label {
                    out.push_str(lb);
                }
                out.push('\n');
                continue;
            }
            let prefix_ws = src.display_text(src.lines[l], a.start).chars().all(|c| c == ' ');
            let inline = is_first && prefix_ws;
            if inline || !is_first {
                let marker = if is_first { self.ml_start() } else if is_last { self.ml_close() } else { self.ml_bar() };
                out.push_str(&format!(
                    "{}{} {} {} {}\n",
                    pad,
                    self.st("94", &line_no),
                    self.gch(),
                    self.st("94", ""),
                    ""
                ));
                out.push_str(&self.st("94", marker));
                out.push(' ');
                out.push_str(&src.display_text(src.lines[l], src.line_end(l)));
                out.push('\n');
            } else {
                out.push_str(&format!(
                    "{}{} {} {} {}\n",
                    pad,
                    self.st("94", &line_no),
                    self.gch(),
                    self.st("94", ""),
                    self.truncate(src, src.line_text(l), start_off, anns)
                ));
                out.push_str(&self.gutter(digits));
                out.push(' ');
                out.push_str(&self.st("94", self.ml_start()));
                for _ in 0..start_off {
                    out.push_str(&self.st("94", self.dash()));
                }
                out.push_str(&self.st("94", self.ml_end()));
                out.push('\n');
            }
        }
        let _ = d;
        if !ends_mid {
            out.push_str(&format!("{}{}", " ".repeat(digits + 1), self.closemark(false)));
            for _ in 0..3 {
                out.push_str(&self.st("94", self.dash()));
            }
            out.push_str(&self.st("94", self.ml_end()));
            out.push('\n');
        }
        out
    }

    fn truncate(&self, src: &SourceText, content: &str, focus: usize, _anns: &[Ann]) -> String {
        let w = str_width(content);
        let budget = self.width.saturating_sub(6);
        if w <= budget {
            return content.to_string();
        }
        // keep a window around the focus
        let mut start_col = 0usize;
        if focus + 8 > budget {
            start_col = focus.saturating_sub(budget.saturating_sub(8));
        }
        let mut out = String::new();
        let mut cur = 0usize;
        let mut kept = 0usize;
        for c in content.chars() {
            let cw = if c == '\t' { 4 - (cur % 4) } else { char_width(c) };
            if cur >= start_col {
                if kept + cw > budget {
                    break;
                }
                if c == '\t' {
                    for _ in 0..cw {
                        out.push(' ');
                    }
                } else {
                    out.push(c);
                }
                kept += cw;
            }
            cur += cw;
        }
        let prefix = if start_col > 0 { self.ellip().to_string() } else { String::new() };
        let suffix = if cur > start_col + kept { self.ellip().to_string() } else { String::new() };
        format!("{}{}{}", prefix, out, suffix)
    }
}
