const BOLD: &str = "\x1b[1m";
const RESET: &str = "\x1b[0m";

pub struct SourceText {
    pub text: String,
    pub lines: Vec<usize>,
    pub line_count: usize,
}

impl SourceText {
    pub fn new(text: &str) -> SourceText {
        let mut lines = vec![0usize];
        for (i, b) in text.bytes().enumerate() {
            if b == b'\n' {
                lines.push(i + 1);
            }
        }
        let line_count = lines.len();
        SourceText { text: text.to_string(), lines, line_count }
    }

    pub fn line_of(&self, offset: usize) -> usize {
        let offset = offset.min(self.text.len());
        let mut lo = 0usize;
        let mut hi = self.lines.len();
        while lo + 1 < hi {
            let mid = (lo + hi) / 2;
            if self.lines[mid] <= offset {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        lo
    }

    pub fn col_of(&self, offset: usize) -> usize {
        let l = self.line_of(offset);
        let start = self.lines[l];
        self.text[start..offset.min(self.text.len())].chars().count()
    }

    pub fn line_end(&self, line: usize) -> usize {
        self.lines.get(line + 1).map(|e| e - 1).unwrap_or(self.text.len())
    }

    pub fn line_text(&self, line: usize) -> &str {
        let start = self.lines[line];
        let end = self.line_end(line);
        self.text[start..end.min(self.text.len())].trim_end_matches('\r')
    }

    pub fn display_offset(&self, offset: usize) -> usize {
        let l = self.line_of(offset);
        let start = self.lines[l];
        let s = &self.text[start..offset.min(self.text.len())];
        let mut w = 0usize;
        for c in s.chars() {
            w += if c == '\t' { 4 - (w % 4) } else { char_width(c) };
        }
        w
    }

    pub fn display_width(&self, start: usize, end: usize) -> usize {
        let s = &self.text[start.min(self.text.len())..end.min(self.text.len())];
        let mut w = 0usize;
        for c in s.chars() {
            w += if c == '\t' { 4 - (w % 4) } else { char_width(c) };
        }
        w
    }

    pub fn display_text(&self, start: usize, end: usize) -> String {
        let s = &self.text[start.min(self.text.len())..end.min(self.text.len())];
        let mut out = String::new();
        let mut w = 0usize;
        for c in s.chars() {
            if c == '\t' {
                let n = 4 - (w % 4);
                for _ in 0..n {
                    out.push(' ');
                }
                w += n;
            } else if (c as u32) < 0x20 || c as u32 == 0x7f {
                let cp = c as u32;
                let pic = char::from_u32(0x2400 + cp).unwrap_or(c);
                out.push(pic);
                w += 1;
            } else {
                out.push(c);
                w += char_width(c);
            }
        }
        out
    }
}

