                while cur < o {
                    out.push(' ');
                    cur += 1;
                }
                if cur > o {
                    out.push(' ');
                    cur += 1;
                }
                out.push_str(&lb);
                cur += str_width(&lb);
            }
        }
        out.push('\n');
        for (text, span) in &footers {
            if span.is_some() {
                continue;
            }
            out.push_str(&format!(
                "{} {} {}\n",
                " ".repeat(digits + 1),
                if has_footer {
                    self.st("94", "")
                } else {
