        let mut marker = String::new();
        let mut cur = 0usize;
        let mut hung: Vec<usize> = vec![];
        for (i, a) in anns.iter().enumerate() {
            let start = src.display_offset(a.start);
            let w = src.display_width(a.start, a.end).max(1);
            let is_last = i == last;
            while cur < start {
                marker.push(' ');
                cur += 1;
            }
            if cur > start {
                marker.push(' ');
                cur += 1;
            }
            if is_last {
                marker.push_str(&self.st(&self.color_of(a.primary, sev), &self.mchar(a.primary).repeat(w)));
            } else {
                marker.push_str(&self.st("94", &format!("{}{}", self.conn(), self.dash().repeat(w.saturating_sub(1)))));
                hung.push(src.display_offset(a.start));
            }
            cur = start + w;
        }
        if !marker.is_empty() {
            out.push_str(&self.gutter(digits));
            out.push(' ');
            out.push_str(&marker);
            if anns.len() == 1 {
                if let Some(lb) = &anns[last].label {
                    out.push(' ');
                    out.push_str(lb);
                }
            }
            out.push('\n');
        }
        if !hung.is_empty() {
            out.push_str(&self.gutter(digits));
            out.push(' ');
            hung.sort();
            hung.dedup();
            let mut cur = 0usize;
            for p in hung {
                while cur < p {
                    out.push(' ');
                    cur += 1;
                }
                if cur > p {
                    out.push(' ');
                    cur += 1;
                }
                out.push_str(&self.st("94", self.gch()));
                cur += 1;
            }
            out.push('\n');
        }
        out
    }

    fn multiline(&self, digits: usize, src: &SourceText, anns: &[Ann], d: &Diag) -> String {
        let mut out = String::new();
        let a = anns.iter().find(|a| src.line_of(a.start) != src.line_of(a.end.saturating_sub(1).min(src.text.len()))).cloned().unwrap_or(Ann { start: 0, end: 0, primary: false, label: None });
        let l0 = src.line_of(a.start);
        let l1 = src.line_of(a.end.saturating_sub(1).min(src.text.len()));
        let start_off = src.display_offset(a.start);
        let ends_mid = a.end < src.line_end(l1);
        for l in l0..=l1 {
            let line_no = (l + 1).to_string();
            let pad = " ".repeat(digits.saturating_sub(line_no.len()));
            let is_first = l == l0;
            let is_last = l == l1;
            if is_first && a.start >= src.line_end(l0) {
                // span starts at the end of the line
                out.push_str(&format!(
                    "{}{} {} {} {}\n",
                    pad,
                    self.st("94", &line_no),
                    self.gch(),
                    self.st("94", ""),
                    self.truncate(src, src.line_text(l), start_off, anns)
                ));
                out.push_str(&self.gutter(digits));
                out.push(' ');
                out.push_str(&self.st("94", self.arrow()));
                out.push(' ');
                if let Some(lb) = &a.label {
                    out.push_str(lb);
                }
                out.push('\n');
                continue;
            }
            let prefix_ws = src.display_text(src.lines[l], a.start).chars().all(|c| c == ' ');
            let inline = is_first && prefix_ws;
            if inline || !is_first {
                let marker = if is_first { self.ml_start() } else if is_last { self.ml_close() } else { self.ml_bar() };
                out.push_str(&format!(
                    "{}{} {} {} {}\n",
                    pad,
                    self.st("94", &line_no),
                    self.gch(),
                    self.st("94", ""),
                    ""
                ));
                out.push_str(&self.st("94", marker));
                out.push(' ');
                out.push_str(&src.display_text(src.lines[l], src.line_end(l)));
                out.push('\n');
            } else {
                out.push_str(&format!(
                    "{}{} {} {} {}\n",
                    pad,
                    self.st("94", &line_no),
                    self.gch(),
                    self.st("94", ""),
                    self.truncate(src, src.line_text(l), start_off, anns)
                ));
                out.push_str(&self.gutter(digits));
                out.push(' ');
                out.push_str(&self.st("94", self.ml_start()));
                for _ in 0..start_off {
                    out.push_str(&self.st("94", self.dash()));
                }
                out.push_str(&self.st("94", self.ml_end()));
                out.push('\n');
            }
        }
        let _ = d;
        if !ends_mid {
            out.push_str(&format!("{}{}", " ".repeat(digits + 1), self.closemark(false)));
            for _ in 0..3 {
                out.push_str(&self.st("94", self.dash()));
            }
            out.push_str(&self.st("94", self.ml_end()));
            out.push('\n');
        }
        out
    }

    fn truncate(&self, src: &SourceText, content: &str, focus: usize, _anns: &[Ann]) -> String {
        let w = str_width(content);
        let budget = self.width.saturating_sub(6);
        if w <= budget {
            return content.to_string();
        }
        // keep a window around the focus
        let mut start_col = 0usize;
        if focus + 8 > budget {
            start_col = focus.saturating_sub(budget.saturating_sub(8));
        }
        let mut out = String::new();
        let mut cur = 0usize;
        let mut kept = 0usize;
        for c in content.chars() {
            let cw = if c == '\t' { 4 - (cur % 4) } else { char_width(c) };
            if cur >= start_col {
                if kept + cw > budget {
                    break;
                }
                if c == '\t' {
                    for _ in 0..cw {
                        out.push(' ');
                    }
                } else {
                    out.push(c);
                }
                kept += cw;
            }
            cur += cw;
        }
        let prefix = if start_col > 0 { self.ellip().to_string() } else { String::new() };
        let suffix = if cur > start_col + kept { self.ellip().to_string() } else { String::new() };
        format!("{}{}{}", prefix, out, suffix)
    }
}
