#[derive(Clone)]
struct Ann {
    start: usize,
    end: usize,
    primary: bool,
    label: Option<String>,
}

pub struct Renderer {
    pub style: HumanStyle,
    pub color: bool,
    pub width: usize,
}

impl Renderer {
    fn st(&self, code: &str, text: &str) -> String {
        if !self.color || text.is_empty() {
            return text.to_string();
        }
        format!("{}{}{}m{}{}", BOLD, "\x1b[", code, text, RESET)
    }

    fn sev_code(&self, s: Severity) -> &'static str {
        match s {
            Severity::Error => "91",
            Severity::Warning => "93",
            Severity::Note => "92",
        }
    }

    fn gch(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "│",
            _ => "|",
        }
    }

    fn gutter(&self, digits: usize) -> String {
        format!("{}{}", " ".repeat(digits + 1), self.st("94", self.gch()))
    }

    fn locmark(&self) -> String {
        match self.style {
            HumanStyle::Unicode => self.st("94", " ╭▸ "),
            _ => self.st("94", "--> "),
        }
    }

    fn closemark(&self, footer: bool) -> String {
        match self.style {
            HumanStyle::Unicode => {
                if footer {
                    self.st("94", "├")
                } else {
                    self.st("94", "╰╴")
                }
            }
            _ => self.st("94", "="),
        }
    }

    fn lastclosemark(&self) -> String {
        match self.style {
            HumanStyle::Unicode => self.st("94", "╰"),
            _ => self.st("94", "="),
        }
    }

    fn mchar(&self, primary: bool) -> &str {
        match self.style {
            HumanStyle::Unicode => {
                if primary {
                    "━"
                } else {
                    "─"
                }
            }
            _ => "^",
        }
    }

    fn dash(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "─",
            _ => "-",
        }
    }

    fn conn(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "┬",
            _ => "-",
        }
    }

    fn ml_start(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "┏",
            _ => "^",
        }
    }
    fn ml_bar(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "┃",
            _ => "|",
        }
    }
    fn ml_end(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "┛",
            _ => "^",
        }
    }
    fn ml_close(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "┗",
            _ => "^",
        }
    }
    fn arrow(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "↖",
            _ => "^",
        }
    }
    fn ellip(&self) -> &str {
        match self.style {
            HumanStyle::Unicode => "…",
            _ => "...",
        }
    }

    fn marker_color(&self, primary: bool, sev: Severity) -> &'static str {
        match sev {
            Severity::Note => "92",
            _ => {
                if primary {
                    self.sev_code(sev)
                } else {
                    "94"
                }
            }
        }
    }

    fn code_line(&self, digits: usize, line: usize, content: &str) -> String {
        let line_no = (line + 1).to_string();
        let pad = " ".repeat(digits.saturating_sub(line_no.len()));
        format!(
            "{}{} {} {}\n",
            pad,
            self.st("94", &line_no),
            self.st("94", self.gch()),
            content
        )
    }

    pub fn render_snippet(
        &self,
        out: &mut String,
        digits: usize,
        src: &SourceText,
        anns: &[Ann],
        footers: &[(String, Option<usize>)],
        sev: Severity,
        loc_start: usize,
    ) {
        if anns.is_empty() && footers.iter().all(|(_, s)| s.is_none()) {
            return;
        }
        let loc_ann = anns.iter().find(|a| a.start == loc_start).cloned().unwrap_or_else(|| {
            anns.first().cloned().unwrap_or(Ann { start: loc_start, end: loc_start, primary: false, label: None })
        });
        let line = src.line_of(loc_ann.start);
        let col = src.col_of(loc_ann.start) + 1;
        out.push_str(&format!(
            "{}{}:{}:{}\n",
            self.locmark(),
            src.display_path,
            line + 1,
            col
        ));
        if anns.is_empty() {
            // footers only
            self.render_footers(out, digits, footers, true);
            return;
        }
        let min_line = anns.iter().map(|a| src.line_of(a.start)).min().unwrap_or(line);
        let max_line = anns
            .iter()
            .map(|a| src.line_of(a.end.saturating_sub(1).min(src.text.len())))
            .max()
            .unwrap_or(line);
        let multi = max_line > min_line;
        out.push_str(&self.gutter(digits));
        out.push('\n');
        let mut merged = false;
        if !multi {
            let content = self.truncate(src, src.line_text(line), loc_ann.start);
            out.push_str(&self.code_line(digits, line, &content));
            let (lines, hanging_labels, marker_on_close) =
                self.annotation_lines(digits, src, line, anns, sev, footers.is_empty() && true);
            for l in lines {
                out.push_str(&l);
            }
            merged = marker_on_close;
            if !merged {
                out.push_str(&self.gutter(digits));
                out.push('\n');
            }
        } else {
            self.render_multiline(out, digits, src, anns, sev);
        }
        self.render_footers(out, digits, footers, false);
        if merged {
            // the closing line was already emitted with the marker
        }
    }

    fn render_footers(&self, out: &mut String, digits: usize, footers: &[(String, Option<usize>)], first_is_close: bool) {
        let visible: Vec<&(String, Option<usize>)> =
            footers.iter().filter(|(_, s)| s.is_none()).collect();
        let n = visible.len();
        for (i, (text, _)) in visible.iter().enumerate() {
            let is_last = i + 1 == n;
            let prefix = if is_last && !(first_is_close && n > 1) {
                self.lastclosemark()
            } else {
                self.closemark(true)
            };
            out.push_str(&format!("{}{} {}\n", " ".repeat(digits + 1), prefix, text));
        }
    }

    fn annotation_lines(
        &self,
        digits: usize,
        src: &SourceText,
        line: usize,
        anns: &[Ann],
        sev: Severity,
        can_merge: bool,
    ) -> (Vec<String>, Vec<(usize, String)>, bool) {
        let mut lines = vec![];
        let mut hanging_labels: Vec<(usize, String)> = vec![];
        let n = anns.len();
        let last = n.saturating_sub(1);
        let mut marker = String::new();
        let mut cur = 0usize;
        let mut hung: Vec<usize> = vec![];
        for (i, a) in anns.iter().enumerate() {
            let start = src.display_offset(a.start);
            let w = src.display_width(a.start, a.end).max(1);
            let is_last = i == last;
            while cur < start {
                marker.push(' ');
                cur += 1;
            }
            if cur > start {
                marker.push(' ');
                cur += 1;
            }
            if is_last {
                marker.push_str(&self.st(
                    self.marker_color(a.primary, sev),
                    &self.mchar(a.primary).repeat(w),
                ));
            } else {
                marker.push_str(&self.st(
                    "94",
                    &format!("{}{}", self.conn(), self.dash().repeat(w.saturating_sub(1))),
                ));
                hung.push(src.display_offset(a.start));
                if let Some(lb) = &a.label {
                    hanging_labels.push((src.display_offset(a.start), lb.clone()));
                }
            }
            cur = start + w;
        }
        let merge = can_merge && n == 1;
        let mut out = String::new();
        out.push_str(&self.gutter(digits));
        out.push(' ');
        if merge {
            out.push_str(&self.st("94", self.closemark(false)));
        }
        out.push_str(&marker);
        if n == 1 {
            if let Some(lb) = &anns[last].label {
                out.push(' ');
                out.push_str(lb);
            }
        }
        out.push('\n');
        lines.push(out);
        if !hung.is_empty() && !merge {
            let mut bar = String::new();
            bar.push_str(&self.gutter(digits));
            bar.push(' ');
            hung.sort();
            hung.dedup();
            let mut cur = 0usize;
            for p in hung {
                while cur < p {
                    bar.push(' ');
                    cur += 1;
                }
                if cur > p {
                    bar.push(' ');
                    cur += 1;
                }
                bar.push_str(&self.st("94", self.gch()));
                cur += 1;
            }
            bar.push('\n');
            lines.push(bar);
        }
        (lines, hanging_labels, merge)
    }

    fn render_multiline(&self, out: &mut String, digits: usize, src: &SourceText, anns: &[Ann], sev: Severity) {
        let a = anns
            .iter()
            .find(|a| src.line_of(a.start) != src.line_of(a.end.saturating_sub(1).min(src.text.len())))
            .cloned()
            .unwrap_or_else(|| anns.last().cloned().unwrap_or(Ann { start: 0, end: 0, primary: false, label: None }));
        let l0 = src.line_of(a.start);
        let l1 = src.line_of(a.end.saturating_sub(1).min(src.text.len()));
        let start_off = src.display_offset(a.start);
        let ends_mid = a.end < src.line_end(l1);
        for l in l0..=l1 {
            let is_first = l == l0;
            let is_last = l == l1;
            if is_first && a.start >= src.line_end(l0) {
                out.push_str(&self.code_line(
                    digits,
                    l,
                    &self.truncate(src, src.line_text(l), a.start),
                ));
                out.push_str(&self.gutter(digits));
                out.push(' ');
                out.push_str(&self.st("94", self.arrow()));
                out.push(' ');
                if let Some(lb) = &a.label {
                    out.push_str(lb);
                }
                out.push('\n');
                continue;
            }
            let prefix_ws = src.display_text(src.lines[l], a.start).chars().all(|c| c == ' ');
            let inline = is_first && prefix_ws;
            if inline || (!is_first && !is_last) || (is_last && !ends_mid && false) {
                let marker = if is_first {
                    self.ml_start()
                } else if is_last {
                    self.ml_close()
                } else {
                    self.ml_bar()
                };
                out.push_str(&self.code_line(digits, l, ""));
                out.push_str(&self.st("94", marker));
                out.push(' ');
                out.push_str(&src.display_text(src.lines[l], src.line_end(l)));
                out.push('\n');
            } else if is_last && !ends_mid {
                out.push_str(&self.code_line(
                    digits,
                    l,
                    &self.truncate(src, src.line_text(l), a.start),
                ));
            } else {
                out.push_str(&self.code_line(
                    digits,
                    l,
                    &self.truncate(src, src.line_text(l), a.start),
                ));
                out.push_str(&self.gutter(digits));
                out.push(' ');
                out.push_str(&self.st("94", self.ml_start()));
                for _ in 0..start_off {
                    out.push_str(&self.st("94", self.dash()));
                }
                out.push_str(&self.st("94", self.ml_end()));
                out.push('\n');
            }
        }
        if !ends_mid {
            out.push_str(&format!("{}{}", " ".repeat(digits + 1), self.closemark(false)));
            let off = src.display_offset(a.end.saturating_sub(1));
            for _ in 0..off {
                out.push(' ');
            }
            let w = src
                .display_width(src.lines[l1] + off_bytes(src, l1, off), a.end)
                .max(1);
            out.push_str(&self.st(
                self.marker_color(a.primary, sev),
                &self.mchar(a.primary).repeat(w),
            ));
            if let Some(lb) = &a.label {
                out.push(' ');
                out.push_str(lb);
            }
            out.push('\n');
        } else {
            out.push_str(&format!("{}{}", " ".repeat(digits + 1), self.closemark(false)));
            for _ in 0..2 {
                out.push_str(&self.st("94", self.dash()));
            }
            out.push_str(&self.st("94", self.ml_end()));
            out.push('\n');
        }
    }

    fn truncate(&self, src: &SourceText, content: &str, focus: usize) -> String {
        let w = str_width(content);
        let budget = self.width.saturating_sub(6);
        if w <= budget {
            return content.to_string();
        }
        let mut start_col = 0usize;
        if focus + 8 > budget {
            start_col = focus.saturating_sub(budget.saturating_sub(8));
        }
        let mut out = String::new();
        let mut cur = 0usize;
        let mut kept = 0usize;
        let mut overflow = false;
        for c in content.chars() {
            let cw = if c == '\t' { 4 - (cur % 4) } else { char_width(c) };
            if cur >= start_col {
                if kept + cw > budget {
                    overflow = true;
                    break;
                }
                if c == '\t' {
                    for _ in 0..cw {
                        out.push(' ');
                    }
                } else {
                    out.push(c);
                }
                kept += cw;
            }
            cur += cw;
        }
        let prefix = if start_col > 0 { self.ellip().to_string() } else { String::new() };
        let suffix = if overflow { self.ellip().to_string() } else { String::new() };
        format!("{}{}{}", prefix, out, suffix)
    }
}

