/// Renders a list of diagnostics in the human readable format.
pub fn render_human(
    diags: &[Diag],
    renderer: &Renderer,
    sources: &std::collections::HashMap<u32, SourceText>,
    paths: &std::collections::HashMap<u32, String>,
) -> String {
    let mut out = String::new();
    for d in diags {
        let mut all: Vec<&Diag> = vec![d];
        for c in &d.children {
            all.push(c);
        }
        for sub in all {
            out.push_str(&render_one(sub, renderer, sources, paths));
        }
        out.push('\n');
    }
    out
}

fn render_one(
    d: &Diag,
    renderer: &Renderer,
    sources: &std::collections::HashMap<u32, SourceText>,
    paths: &std::collections::HashMap<u32, String>,
) -> String {
    if renderer.style == HumanStyle::Short {
        let mut s = String::new();
        let sevname = match d.severity {
            Severity::Error => "error",
            Severity::Warning => "warning",
            Severity::Note => "note",
        };
        let loc = match &d.primary {
            Some(p) => {
                let f = p.span.file;
                let path = paths.get(&f).cloned().unwrap_or_default();
                let src = sources.get(&f);
                match src {
                    Some(src) => format!(
                        "{}:{}:{}: ",
                        path,
                        src.line_of(p.span.start as usize) + 1,
                        src.col_of(p.span.start as usize) + 1
                    ),
                    None => format!("{}: ", path),
                }
            }
            None => String::new(),
        };
        let code = match d.code {
            Some(c) => format!("[{}]", c),
            None => String::new(),
        };
        s.push_str(&format!("{}{}{}: {}\n", loc, sevname, code, d.message));
        for (text, span) in &d.notes {
            if let Some(sp) = span {
                let f = sp.file;
                let path = paths.get(&f).cloned().unwrap_or_default();
                let src = sources.get(&f);
                if let Some(src) = src {
                    s.push_str(&format!(
                        "{}:{}:{}: note: {}\n",
                        path,
                        src.line_of(sp.start as usize) + 1,
                        src.col_of(sp.start as usize) + 1,
                        text
                    ));
                    continue;
                }
            }
            s.push_str(&format!("note: {}\n", text));
        }
        return s;
    }
    // human style with snippets
    let file = d
        .primary
        .as_ref()
        .map(|p| p.span.file)
        .or_else(|| d.secondary.first().map(|s| s.span.file))
        .or_else(|| d.notes.iter().find_map(|(_, s)| *s).map(|s| s.file))
        .or_else(|| d.helps.iter().find_map(|(_, s)| *s).map(|s| s.file));
    let mut out = String::new();
    // header
    let sevname = match d.severity {
        Severity::Error => "error",
        Severity::Warning => "warning",
        Severity::Note => "note",
    };
    let header = match d.code {
        Some(c) => format!("{}[{}]", sevname, c),
        None => sevname.to_string(),
    };
    out.push_str(BOLD);
    out.push_str(&renderer.st(renderer.sev_color(d.severity), &header));
    if renderer.color {
        out.push_str(RESET);
    }
    out.push_str(": ");
    if renderer.color && matches!(d.severity, Severity::Error | Severity::Warning) {
        out.push_str(BOLD);
    }
    out.push_str(&d.message);
    if renderer.color && matches!(d.severity, Severity::Error | Severity::Warning) {
        out.push_str(RESET);
    }
    out.push('\n');
    let mut footers: Vec<(String, Option<usize>)> = vec![];
    for (text, span) in &d.notes {
        footers.push((format!("note: {text}"), span.map(|s| s.start as usize)));
    }
    for (text, span) in &d.helps {
        footers.push((format!("help: {text}"), span.map(|s| s.start as usize)));
    }
    let mut anns: Vec<Ann> = vec![];
    if let Some(p) = &d.primary {
        anns.push(Ann {
            start: p.span.start as usize,
            end: p.span.end as usize,
            primary: true,
            label: p.label.clone(),
        });
    }
    for s in &d.secondary {
        anns.push(Ann {
            start: s.span.start as usize,
            end: s.span.end as usize,
            primary: false,
            label: s.label.clone(),
        });
    }
    anns.sort_by_key(|a| a.start);
    let hanging: Vec<(usize, String)> = footers
        .iter()
        .filter(|(_, s)| s.is_some())
        .map(|(t, s)| (s.unwrap(), t.clone()))
        .collect();
    for (off, _t) in &hanging {
        anns.push(Ann { start: *off, end: *off, primary: false, label: None });
    }
    footers.retain(|(_, s)| s.is_none());
    anns.sort_by_key(|a| a.start);
    let mut children: Vec<Diag> = vec![];
    for c in &d.children {
        children.push(c.clone());
    }
    let _ = &mut children;
    match file {
        Some(f) => {
            let src = sources.get(&f);
            let path = paths.get(&f).cloned().unwrap_or_default();
            match src {
                Some(src) => {
                    let digits = src.line_count.to_string().len().max(1);
                    let mut anns2 = anns.clone();
                    let loc_start = anns2
                        .iter()
                        .find(|a| a.primary)
                        .map(|a| a.start)
                        .unwrap_or_else(|| anns2.first().map(|a| a.start).unwrap_or(0));
                    // footers with spans stay as annotations
                    let footer_with_span: Vec<(String, Option<usize>)> = footers
                        .iter()
                        .map(|(t, s)| (t.clone(), s.filter(|_| false).map(|_| 0usize)))
                        .collect();
                    let _ = footer_with_span;
                    renderer.render_snippet(&mut out, digits, src, &anns2, &footers, d.severity, loc_start);
                }
                None => {
                    out.push_str(&format!("{}:{}: {}\n", path, "", d.message));
                }
            }
        }
        None => {
            // no spans
            let digits = 1;
            if footers.iter().any(|(_, s)| s.is_some()) || !anns.is_empty() {
                // nothing
            }
            if footers.is_empty() {
                return out;
            }
            out.push_str(&renderer.gutter(digits));
            out.push('\n');
            renderer.render_footers(&mut out, digits, &footers, true);
        }
    }
    out
}
