//! solar: a Solidity compiler.

mod abi;
mod ast;
mod cli;
mod diag;
mod json;
mod keccak;
mod lexer;
mod lower;
mod parser;
mod render;
mod source;

use crate::cli::{CliResult, Color, Emit, ErrorFormat, Options};
use std::collections::HashMap;

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    match cli::parse(&args) {
        CliResult::Help(h) => {
            print!("{}", h);
            std::process::exit(0);
        }
        CliResult::Version(v) => {
            print!("{}", v);
            std::process::exit(0);
        }
        CliResult::Err(e) => {
            eprint!("{}", e);
            std::process::exit(2);
        }
        CliResult::Parsed(opts) => run(opts),
    }
}

fn run(opts: Options) {
    let mut ctx = source::Context::new(&opts);
    let loaded = ctx.load();
    let mut diags: Vec<crate::diag::Diag> = ctx.diagnostics.clone();
    let units = match loaded {
        Ok(u) => u,
        Err(()) => {
            report(&opts, &diags, &ctx.sources, &ctx.paths, None);
            std::process::exit(1);
        }
    };
    // parse
    let mut parse_diags = vec![];
    let mut parsed = vec![];
    for (i, u) in units.iter().enumerate() {
        let mut lx = lexer::Lexer::new(&u.text, i as u32);
        lx.run();
        for d in &lx.diags {
            parse_diags.push(crate::diag::Diag::error(d.msg.clone()).with_span(d.span));
        }
        let mut p = parser::Parser::new(lx);
        let unit = p.parse();
        parse_diags.extend(p.diags.clone());
        parsed.push((unit, p.docs.clone()));
    }
    diags.extend(parse_diags);
    if diags.iter().any(|d| d.severity == crate::diag::Severity::Error) {
        report(&opts, &diags, &ctx.sources, &ctx.paths, None);
        std::process::exit(1);
    }
    // lowering
    let mut g = lower::Global::new(parsed.iter().map(|(u, _)| u.clone()).collect());
    g.alias_map = ctx.aliases.clone();
    g.import_targets = ctx.import_targets.clone();
    for f in 0..units.len() {
        g.collect_file(f);
    }
    g.resolve_bases();
    let abi_json = g.generate_abi(
        opts.emit.contains(&Emit::Abi),
        opts.emit.contains(&Emit::Hashes),
    );
    diags.extend(g.diagnostics.clone());
    if diags.iter().any(|d| d.severity == crate::diag::Severity::Error) {
        report(&opts, &diags, &ctx.sources, &ctx.paths, None);
        std::process::exit(1);
    }
    // output
    let text = if opts.pretty_json {
        crate::json::to_pretty(&abi_json)
    } else {
        crate::json::to_string(&abi_json)
    };
    match &opts.out_dir {
        Some(dir) => {
            let path = dir.join("combined.json");
            if let Err(e) = std::fs::write(&path, &text) {
                diags.push(crate::diag::Diag::error(format!(
                    "failed to write to output: {}",
                    e
                )));
                report(&opts, &diags, &ctx.sources, &ctx.paths, None);
                std::process::exit(1);
            }
        }
        None => {
            print!("{}", text);
        }
    }
}

fn report(
    opts: &Options,
    diags: &[crate::diag::Diag],
    sources: &HashMap<u32, crate::render::SourceText>,
    paths: &HashMap<u32, String>,
    _x: Option<()>,
) {
    let errors: Vec<&crate::diag::Diag> = diags
        .iter()
        .filter(|d| d.severity == crate::diag::Severity::Error)
        .collect();
    match opts.error_format {
        ErrorFormat::Json => {
            for d in diags {
                let mut o = crate::json::obj();
                match &d.primary {
                    Some(p) => {
                        let mut loc = crate::json::obj();
                        loc.set(
                            "file",
                            crate::json::Json::Str(paths.get(&p.span.file).cloned().unwrap_or_default()),
                        );
                        loc.set("start", crate::json::Json::Int(p.span.start as i64));
                        loc.set("end", crate::json::Json::Int(p.span.end as i64));
                        o.set("sourceLocation", loc);
                    }
                    None => {
                        o.set("sourceLocation", crate::json::Json::Null);
                    }
                }
                let mut secs = vec![];
                for s in &d.children {
                    if let Some(sp) = &s.primary {
                        let mut l = crate::json::obj();
                        l.set(
                            "file",
                            crate::json::Json::Str(paths.get(&sp.span.file).cloned().unwrap_or_default()),
                        );
                        l.set("start", crate::json::Json::Int(sp.span.start as i64));
                        l.set("end", crate::json::Json::Int(sp.span.end as i64));
                        l.set("message", crate::json::Json::Str(s.message.clone()));
                        secs.push(l);
                    }
                }
                o.set(
                    "secondarySourceLocations",
                    crate::json::Json::Array(secs),
                );
                o.set("type", crate::json::Json::Str("Exception".to_string()));
                o.set("component", crate::json::Json::Str("general".to_string()));
                o.set(
                    "severity",
                    crate::json::Json::Str(match d.severity {
                        crate::diag::Severity::Error => "error".to_string(),
                        crate::diag::Severity::Warning => "warning".to_string(),
                        crate::diag::Severity::Note => "info".to_string(),
                    }),
                );
                o.set(
                    "errorCode",
                    match d.code {
                        Some(c) => crate::json::Json::Str(c.to_string()),
                        None => crate::json::Json::Null,
                    },
                );
                o.set("message", crate::json::Json::Str(d.message.clone()));
                let renderer = make_renderer(opts, sources);
                let rendered = crate::render::render_human(&std::slice::from_ref(d), &renderer, sources, paths);
                o.set("formattedMessage", crate::json::Json::Str(rendered));
                let s = if opts.pretty_json_err {
                    crate::json::to_pretty(&o)
                } else {
                    crate::json::to_string(&o)
                };
                eprintln!("{}", s);
            }
        }
        ErrorFormat::RustcJson => {
            for d in diags {
                let mut o = crate::json::obj();
                o.set("$message_type", crate::json::Json::Str("diagnostic".to_string()));
                o.set("message", crate::json::Json::Str(d.message.clone()));
                o.set(
                    "code",
                    match d.code {
                        Some(c) => crate::json::Json::Str(c.to_string()),
                        None => crate::json::Json::Null,
                    },
                );
                o.set(
                    "level",
                    crate::json::Json::Str(match d.severity {
                        crate::diag::Severity::Error => "error".to_string(),
                        crate::diag::Severity::Warning => "warning".to_string(),
                        crate::diag::Severity::Note => "note".to_string(),
                    }),
                );
                let mut spans = vec![];
                for s in &d.secondary {
                    if let Some(sp) = &s.primary {
                        spans.push(span_json(sp, sources, paths, false, s.label.clone()));
                    }
                }
                if let Some(p) = &d.primary {
                    spans.push(span_json(p, sources, paths, true, p.label.clone()));
                }
                o.set("spans", crate::json::Json::Array(spans));
                let mut children = vec![];
                for c in &d.children {
                    let mut co = crate::json::obj();
                    co.set("$message_type", crate::json::Json::Str("diagnostic".to_string()));
                    co.set("message", crate::json::Json::Str(c.message.clone()));
                    co.set("code", crate::json::Json::Null);
                    co.set(
                        "level",
                        crate::json::Json::Str(match c.severity {
                            crate::diag::Severity::Error => "error".to_string(),
                            crate::diag::Severity::Warning => "warning".to_string(),
                            crate::diag::Severity::Note => "note".to_string(),
                        }),
                    );
                    let mut cspans = vec![];
                    if let Some(p) = &c.primary {
                        cspans.push(span_json(p, sources, paths, true, p.label.clone()));
                    }
                    co.set("spans", crate::json::Json::Array(cspans));
                    co.set("children", crate::json::Json::Array(vec![]));
                    co.set("rendered", crate::json::Json::Null);
                    children.push(co);
                }
                o.set("children", crate::json::Json::Array(children));
                let renderer = make_renderer(opts, sources);
                let rendered = crate::render::render_human(&std::slice::from_ref(d), &renderer, sources, paths);
                o.set("rendered", crate::json::Json::Str(rendered));
                let s = if opts.pretty_json_err {
                    crate::json::to_pretty(&o)
                } else {
                    crate::json::to_string(&o)
                };
                eprintln!("{}", s);
            }
        }
        ErrorFormat::Human => {
            let renderer = make_renderer(opts, sources);
            let text = crate::render::render_human(diags, &renderer, sources, paths);
            if opts.no_warnings {
                let filtered: Vec<&crate::diag::Diag> =
                    diags.iter().filter(|d| d.severity != crate::diag::Severity::Warning).collect();
                let owned: Vec<crate::diag::Diag> = filtered.into_iter().cloned().collect();
                eprint!("{}", crate::render::render_human(&owned, &renderer, sources, paths));
            } else {
                eprint!("{}", text);
            }
        }
    }
    if !errors.is_empty() {
        let n = errors.len();
        let msg = if n == 1 {
            "aborting due to 1 previous error".to_string()
        } else {
            format!("aborting due to {n} previous errors")
        };
        let d = crate::diag::Diag::error(msg);
        match opts.error_format {
            ErrorFormat::Json | ErrorFormat::RustcJson => {
                let single = vec![d];
                let renderer = make_renderer(opts, sources);
                let text = crate::render::render_human(&single, &renderer, sources, paths);
                if opts.error_format == ErrorFormat::Json {
                    let mut o = crate::json::obj();
                    o.set("sourceLocation", crate::json::Json::Null);
                    o.set(
                        "secondarySourceLocations",
                        crate::json::Json::Array(vec![]),
                    );
                    o.set("type", crate::json::Json::Str("Exception".to_string()));
                    o.set("component", crate::json::Json::Str("general".to_string()));
                    o.set("severity", crate::json::Json::Str("error".to_string()));
                    o.set("errorCode", crate::json::Json::Null);
                    o.set("message", crate::json::Json::Str(msg));
                    o.set("formattedMessage", crate::json::Json::Str(text));
                    let s = if opts.pretty_json_err {
                        crate::json::to_pretty(&o)
                    } else {
                        crate::json::to_string(&o)
                    };
                    eprintln!("{}", s);
                } else {
                    let mut o = crate::json::obj();
                    o.set("$message_type", crate::json::Json::Str("diagnostic".to_string()));
                    o.set("message", crate::json::Json::Str(msg));
                    o.set("code", crate::json::Json::Null);
                    o.set("level", crate::json::Json::Str("error".to_string()));
                    o.set("spans", crate::json::Json::Array(vec![]));
                    o.set("children", crate::json::Json::Array(vec![]));
                    o.set("rendered", crate::json::Json::Str(text));
                    let s = if opts.pretty_json_err {
                        crate::json::to_pretty(&o)
                    } else {
                        crate::json::to_string(&o)
                    };
                    eprintln!("{}", s);
                }
            }
            ErrorFormat::Human => {
                let single = vec![d];
                let renderer = make_renderer(opts, sources);
                eprint!("{}", crate::render::render_human(&single, &renderer, sources, paths));
            }
        }
    }
}

fn span_json(
    p: &crate::diag::SpanLabel,
    sources: &HashMap<u32, crate::render::SourceText>,
    paths: &HashMap<u32, String>,
    primary: bool,
    label: Option<String>,
) -> crate::json::Json {
    let src = sources.get(&p.span.file);
    let mut o = crate::json::obj();
    o.set(
        "file_name",
        crate::json::Json::Str(paths.get(&p.span.file).cloned().unwrap_or_default()),
    );
    o.set("byte_start", crate::json::Json::Int(p.span.start as i64));
    o.set("byte_end", crate::json::Json::Int(p.span.end as i64));
    match src {
        Some(s) => {
            o.set("line_start", crate::json::Json::Int(s.line_of(p.span.start as usize) as i64 + 1));
            o.set(
                "line_end",
                crate::json::Json::Int(s.line_of(p.span.end.saturating_sub(1) as usize) as i64 + 1),
            );
            o.set(
                "column_start",
                crate::json::Json::Int(p.span.start as i64 - s.lines[s.line_of(p.span.start as usize)] as i64 + 1),
            );
            o.set(
                "column_end",
                crate::json::Json::Int(p.span.end as i64 - s.lines[s.line_of(p.span.start as usize)] as i64 + 1),
            );
            let text = s.line_text(s.line_of(p.span.start as usize)).to_string();
            let mut t = crate::json::obj();
            t.set("text", crate::json::Json::Str(text));
            t.set("highlight_start", crate::json::Json::Int(p.span.start as i64 - s.lines[s.line_of(p.span.start as usize)] as i64 + 1));
            t.set("highlight_end", crate::json::Json::Int(p.span.end as i64 - s.lines[s.line_of(p.span.start as usize)] as i64 + 1));
            o.set("text", crate::json::Json::Array(vec![t]));
        }
        None => {}
    }
    o.set("is_primary", crate::json::Json::Bool(primary));
    o.set(
        "label",
        match label {
            Some(l) => crate::json::Json::Str(l),
            None => crate::json::Json::Null,
        },
    );
    o.set("suggested_replacement", crate::json::Json::Null);
    o
}

fn make_renderer(
    opts: &Options,
    _sources: &HashMap<u32, crate::render::SourceText>,
) -> crate::render::Renderer {
    let color = match opts.color {
        Color::Always => true,
        Color::Never => false,
        Color::Auto => false,
    };
    crate::render::Renderer {
        style: opts.human_style,
        color,
        width: opts.diagnostic_width.unwrap_or(140),
    }
}
