fn run(opts: Options) {
    let mut ctx = source::Context::new(&opts);
    let loaded = ctx.load();
    let mut diags: Vec<crate::diag::Diag> = ctx.diagnostics.clone();
    let units = match loaded {
        Ok(u) => u,
        Err(()) => {
            report(&opts, &diags, &ctx.sources, &ctx.paths, None);
            std::process::exit(1);
        }
    };
    // parse
    let mut parse_diags = vec![];
    let mut parsed = vec![];
    for (i, u) in units.iter().enumerate() {
        let mut lx = lexer::Lexer::new(&u.text, i as u32);
        lx.run();
        for d in &lx.diags {
            parse_diags.push(crate::diag::Diag::error(d.msg.clone()).with_span(d.span));
        }
        let mut p = parser::Parser::new(lx);
        let unit = p.parse();
        parse_diags.extend(p.diags.clone());
        parsed.push((unit, p.docs.clone()));
    }
    diags.extend(parse_diags);
    if diags.iter().any(|d| d.severity == crate::diag::Severity::Error) {
        report(&opts, &diags, &ctx.sources, &ctx.paths, None);
        std::process::exit(1);
    }
    // lowering
    let mut g = lower::Global::new(parsed.iter().map(|(u, _)| u.clone()).collect());
    g.alias_map = ctx.aliases.clone();
    g.import_targets = ctx.import_targets.clone();
    for f in 0..units.len() {
        g.collect_file(f);
    }
    g.resolve_bases();
    let abi_json = g.generate_abi(
        opts.emit.contains(&Emit::Abi),
        opts.emit.contains(&Emit::Hashes),
    );
    diags.extend(g.diagnostics.clone());
    if diags.iter().any(|d| d.severity == crate::diag::Severity::Error) {
        report(&opts, &diags, &ctx.sources, &ctx.paths, None);
        std::process::exit(1);
    }
    // output
    let text = if opts.pretty_json {
        crate::json::to_pretty(&abi_json)
    } else {
        crate::json::to_string(&abi_json)
    };
    match &opts.out_dir {
        Some(dir) => {
            let path = dir.join("combined.json");
            if let Err(e) = std::fs::write(&path, &text) {
                diags.push(crate::diag::Diag::error(format!(
                    "failed to write to output: {}",
                    e
                )));
                report(&opts, &diags, &ctx.sources, &ctx.paths, None);
                std::process::exit(1);
            }
        }
        None => {
            print!("{}", text);
        }
    }
}

