{"command": "cat > src/source.rs <<'RSEOF'
//! Source file loading, import resolution and remappings.

use crate::cli::Options;
use crate::diag::Diag;
use crate::render::SourceText;
use std::collections::HashMap;
use std::path::{Path, PathBuf};

pub struct FileUnit {
    pub display: String,
    pub text: String,
}

#[derive(Clone)]
pub struct Remapping {
    pub context: Option<String>,
    pub prefix: String,
    pub target: String,
}

pub struct Context {
    pub base: PathBuf,
    pub includes: Vec<PathBuf>,
    pub remaps: Vec<Remapping>,
    pub sources: HashMap<u32, SourceText>,
    pub paths: HashMap<u32, String>,
    pub aliases: Vec<HashMap<String, usize>>,
    pub import_targets: Vec<Vec<usize>>,
    pub diagnostics: Vec<Diag>,
    pub files: Vec<PathBuf>,
    pub texts: Vec<String>,
    pub displays: Vec<String>,
    pub loaded: Vec<usize>,
    /// unit index (into files) of the parsed source
    pub yul: Vec<bool>,
}

impl Context {
    pub fn new(opts: &Options) -> Context {
        let mut base = opts.base_path.clone();
        if base.as_os_str().is_empty() {
            base = PathBuf::new();
        } else if base == Path::new(".") {
            base = PathBuf::new();
        }
        let mut remaps = vec![];
        for input in &opts.inputs {
            if input.contains('=') {
                if let Some(r) = parse_remap(input) {
                    remaps.push(r);
                }
            }
        }
        Context {
            base,
            includes: opts.include_paths.clone(),
            remaps,
            sources: HashMap::new(),
            paths: HashMap::new(),
            aliases: vec![],
            import_targets: vec![],
            diagnostics: vec![],
            files: vec![],
            texts: vec![],
            displays: vec![],
            loaded: vec![],
            yul: vec![],
        }
    }

    fn display_of(&self, p: &Path) -> String {
        if let Ok(rel) = p.strip_prefix(&self.base) {
            let s = rel.to_string_lossy().to_string();
            if !s.is_empty() {
                return s;
            }
        }
        p.to_string_lossy().to_string()
    }

    fn norm(p: &Path) -> PathBuf {
        let mut out = PathBuf::new();
        for c in p.components() {
            match c {
                std::path::Component::CurDir => {}
                std::path::Component::ParentDir => {
                    out.pop();
                }
                other => out.push(other.as_os_str()),
            }
        }
        if out.as_os_str().is_empty() {
            PathBuf::from(".")
        } else {
            out
        }
    }

    fn read_file(&self, p: &Path) -> Option<String> {
        match std::fs::read(p) {
            Ok(b) => Some(String::from_utf8_lossy(&b).to_string()),
            Err(_) => None,
        }
    }

    fn register(&mut self, p: PathBuf, text: String, is_yul: bool) -> usize {
        if let Some(i) = self.loaded.iter().position(|x| self.files[*x] == p) {
            return *i;
        }
        let display = self.display_of(&p);
        let idx = self.files.len();
        self.files.push(p.clone());
        self.texts.push(text.clone());
        self.displays.push(display.clone());
        self.loaded.push(idx);
        self.yul.push(is_yul);
        let mut st = SourceText::new(&text);
        st.display_path = display.clone();
        self.sources.insert(idx as u32, st);
        self.paths.insert(idx as u32, display);
        idx
    }

    /// Loads all inputs and their transitive imports.
    pub fn load(&mut self, opts: &Options) -> Result<(), ()> {
        let mut inputs: Vec<(String, bool)> = vec![];
        for input in &opts.inputs {
            if input.contains('=') {
                continue;
            }
            if input == "-" {
                inputs.push(("<stdin>".to_string(), false));
                continue;
            }
            inputs.push((input.clone(), true));
        }
        if inputs.is_empty() {
            self.diagnostics.push(
                Diag::error("no files found")
                    .with_note("if you wish to use the standard input, please specify `-` explicitly".to_string()),
            );
            return Err(());
        }
        let mut queue: Vec<(String, Option<usize>)> = inputs
            .iter()
            .map(|(s, is_file)| {
                if *is_file {
                    (s.clone(), None)
                } else {
                    (String::new(), Some(usize::MAX))
                }
            })
            .collect();
        // handle stdin entries
        let mut pending: Vec<(String, Option<usize>)> = vec![];
        for (s, tag) in inputs.iter().enumerate() {
            let _ = s;
            if tag.0 == "<stdin>" {
                pending.push((String::new(), Some(usize::MAX)));
            } else {
                pending.push((tag.0.clone(), None));
            }
        }
        queue = pending;
        let mut seen: Vec<PathBuf> = vec![];
        while let Some((path, importer)) = queue.pop() {
            if importer == Some(usize::MAX) {
                // stdin
                let text = std::io::read_to_string(std::io::stdin()).unwrap_or_default();
                let display = "<stdin>".to_string();
                if self.displays.contains(&display) {
                    continue;
                }
                let idx = self.files.len();
                self.files.push(PathBuf::from("<stdin>"));
                self.texts.push(text.clone());
                self.displays.push(display.clone());
                self.loaded.push(idx);
                self.yul.push(false);
                let mut st = SourceText::new(&text);
                st.display_path = display.clone();
                self.sources.insert(idx as u32, st);
                self.paths.insert(idx as u32, display);
                while self.import_targets.len() <= idx {
                    self.import_targets.push(vec![]);
                    self.aliases.push(HashMap::new());
                }
                continue;
            }
            let resolved: PathBuf = if Path::new(&path).is_absolute() {
                PathBuf::from(&path)
            } else {
                Self::norm(&self.base.join(&path))
            };
            if seen.contains(&resolved) {
                continue;
            }
            seen.push(resolved.clone());
            let text = match self.read_file(&resolved) {
                Some(t) => t,
                None => {
                    match std::fs::metadata(&resolved) {
                        Ok(_) => {
                            self.diagnostics.push(Diag::error(format!(
                                "couldn't read {}: Is a directory (os error 21)",
                                path
                            )));
                        }
                        Err(_) => {
                            self.diagnostics
                                .push(Diag::error(format!("file {} not found", path)));
                        }
                    }
                    continue;
                }
            };
            let is_yul = resolved.extension().map(|e| e == "yul").unwrap_or(false);
            let idx = self.register(resolved.clone(), text.clone(), is_yul);
            while self.import_targets.len() <= idx {
                self.import_targets.push(vec![]);
                self.aliases.push(HashMap::new());
            }
            // find imports
            let importer_dir = resolved.parent().map(|p| p.to_path_buf()).unwrap_or_default();
            let import_paths = collect_import_paths(&text);
            let alias_map: HashMap<String, usize> = HashMap::new();
            self.aliases[idx] = alias_map;
            for (imp, span_start, span_end) in import_paths {
                match self.resolve_import(&importer_dir, idx, &imp, span_start, span_end) {
                    Some(target) => {
                        self.import_targets[idx].push(target);
                        queue.push((self.files[target].to_string_lossy().to_string(), None));
                    }
                    None => {}
                }
            }
        }
        if self.diagnostics.iter().any(|d| d.severity == crate::diag::Severity::Error) {
            return Err(());
        }
        Ok(())
    }

    fn resolve_import(
        &mut self,
        importer_dir: &Path,
        importer: usize,
        imp: &str,
        span_start: usize,
        span_end: usize,
    ) -> Option<usize> {
        let file = self.decls_file(importer);
        let _ = file;
        // relative or absolute
        let is_relative = imp.starts_with("./") || imp.starts_with("../");
        let is_absolute = Path::new(imp).is_absolute();
        if is_relative || is_absolute {
            let candidate = if is_absolute {
                PathBuf::from(imp)
            } else {
                Self::norm(&importer_dir.join(imp))
            };
            if candidate.is_file() {
                if let Some(i) = self
                    .loaded
                    .iter()
                    .position(|x| self.files[*x] == candidate)
                {
                    return Some(i);
                }
                // need to load it later; push to a pending list
                self.pending_import(importer, candidate);
                return None;
            }
            self.add_import_error(imp, span_start, span_end);
            return None;
        }
        // remapping
        let search = self.remap(imp);
        let mut candidates: Vec<PathBuf> = vec![];
        let mut roots: Vec<PathBuf> = vec![self.base.clone()];
        roots.extend(self.includes.clone());
        for r in &roots {
            let c = if Path::new(&search).is_absolute() {
                PathBuf::from(&search)
            } else {
                Self::norm(&r.join(&search))
            };
            if c.is_file() && !candidates.contains(&c) {
                candidates.push(c);
            }
        }
        if candidates.len() > 1 {
            let keys: Vec<String> = candidates.iter().map(|c| self.display_of(c)).collect();
            self.diagnostics.push(
                Diag::error(format!(
                    "multiple files match {}: {}",
                    imp,
                    keys.join(", ")
                ))
                .with_span(crate::span::Span::new(
                    importer as u32,
                    span_start,
                    span_end,
                )),
            );
            return None;
        }
        if let Some(c) = candidates.first() {
            let c = c.clone();
            if let Some(i) = self.loaded.iter().position(|x| self.files[*x] == c) {
                return Some(i);
            }
            self.pending_import(importer, c);
            return None;
        }
        self.add_import_error(imp, span_start, span_end);
        None
    }

    fn pending_import(&mut self, importer: usize, candidate: PathBuf) {
        self.pending.push((importer, candidate));
    }

    fn add_import_error(&mut self, imp: &str, span_start: usize, span_end: usize) {
        self.diagnostics.push(
            Diag::error(format!("file {} not found", imp)).with_span(crate::span::Span::new(
                0,
                span_start,
                span_end,
            )),
        );
    }

    fn remap(&self, imp: &str) -> String {
        let mut best: Option<(usize, &Remapping)> = None;
        for r in &self.remaps {
            if imp.starts_with(&r.prefix)
                && (imp.len() == r.prefix.len() || imp.as_bytes().get(r.prefix.len()) == Some(&b'/'))
            {
                match best {
                    Some((len, _)) if len >= r.prefix.len() => {}
                    _ => best = Some((r.prefix.len(), r)),
                }
            }
        }
        match best {
            Some((len, r)) => format!("{}{}", r.target, &imp[len..]),
            None => imp.to_string(),
        }
    }
}

fn parse_remap(s: &str) -> Option<Remapping> {
    let (context, rest) = match s.split_once(':') {
        Some((c, r)) if !c.is_empty() && r.contains('=') => (Some(c.to_string()), r),
        _ => (None, s.to_string()),
    };
    let (prefix, target) = rest.split_once('=')?;
    Some(Remapping {
        context,
        prefix: prefix.to_string(),
        target: target.to_string(),
    })
}

/// Extracts the import paths from a source text (cheap pre-pass).
fn collect_import_paths(text: &str) -> Vec<(String, usize, usize)> {
    let mut out = vec![];
    let b = text.as_bytes();
    let mut i = 0usize;
    while i < b.len() {
        if b[i..].starts_with(b"import") {
            let start = i;
            i += 6;
            // skip whitespace
            while i < b.len() && (b[i] as char).is_whitespace() {
                i += 1;
            }
            if i < b.len() && b[i] == b'"' {
                let qs = i;
                i += 1;
                while i < b.len() && b[i] != b'"' && b[i] != b'\n' {
                    i += 1;
                }
                if i < b.len() && b[i] == b'"' {
                    let qe = i + 1;
                    let raw = &text[qs + 1..i];
                    out.push((unescape(raw), qs, qe));
                    i = qe;
                    continue;
                }
            }
            i = start + 6;
        }
        i += 1;
    }
    out
}

fn unescape(s: &str) -> String {
    let mut out = String::new();
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.next() {
                Some('n') => out.push('\n'),
                Some('r') => out.push('\r'),
                Some('t') => out.push('\t'),
                Some('\\') => out.push('\\'),
                Some('"') => out.push('"'),
                Some('x') => {
                    let mut hex = String::new();
                    for _ in 0..2 {
                        if let Some(h) = chars.next() {
                            hex.push(h);
                        }
                    }
                    if let Ok(v) = u8::from_str_radix(&hex, 16) {
                        out.push(v as char);
                    }
                }
                Some('u') => {
                    let mut hex = String::new();
                    for _ in 0..4 {
                        if let Some(h) = chars.next() {
                            hex.push(h);
                        }
                    }
                    if let Ok(v) = u32::from_str_radix(&hex, 16) {
                        if let Some(c) = char::from_u32(v) {
                            out.push(c);
                        }
                    }
                }
                Some(o) => out.push(o),
                None => {}
            }
        } else {
            out.push(c);
        }
    }
    out
}
