                    Some(target_path) => queue.push((target_path, imp.clone())),
                    None => {}
                }
            }
        }
        if self
            .diagnostics
            .iter()
            .any(|d| d.severity == crate::diag::Severity::Error)
        {
            return Err(());
        }
        Ok(())
    }

    fn resolve_import(
        &mut self,
        importer_dir: &Path,
        importer: usize,
        imp: &str,
        s: usize,
        e: usize,
    ) -> Option<PathBuf> {
        let is_relative = imp.starts_with("./") || imp.starts_with("../");
        let is_absolute = Path::new(imp).is_absolute();
        if is_relative || is_absolute {
            let candidate = if is_absolute {
                PathBuf::from(imp)
            } else {
                norm(&importer_dir.join(imp))
            };
            if candidate.is_file() {
                return Some(candidate);
            }
            self.push_err(importer, format!("file {} not found", imp), s, e);
            return None;
        }
        let search = self.remap(imp);
        let mut candidates: Vec<PathBuf> = vec![];
        let mut roots: Vec<PathBuf> = vec![self.base.clone()];
        roots.extend(self.includes.clone());
        for r in &roots {
            let c = if Path::new(&search).is_absolute() {
                PathBuf::from(&search)
            } else {
                norm(&r.join(&search))
            };
            if c.is_file() && !candidates.contains(&c) {
                candidates.push(c);
            }
        }
        if candidates.len() > 1 {
            let keys: Vec<String> = candidates.iter().map(|c| self.display_of(c)).collect();
            self.push_err(
                importer,
                format!("multiple files match {}: {}", imp, keys.join(", ")),
                s,
                e,
            );
            return None;
        }
        if let Some(c) = candidates.first() {
            return Some(c.clone());
        }
        self.push_err(importer, format!("file {} not found", imp), s, e);
        None
    }

    fn push_err(&mut self, importer: usize, msg: String, s: usize, e: usize) {
        self.diagnostics
            .push(Diag::error(msg).with_span(Span::new(importer as u32, s, e)));
    }

    fn remap(&self, imp: &str) -> String {
        let mut best: Option<(usize, &Remapping)> = None;
        for r in &self.remaps {
            if imp.starts_with(&r.prefix)
                && (imp.len() == r.prefix.len()
                    || imp.as_bytes().get(r.prefix.len()) == Some(&b'/'))
            {
                match best {
                    Some((len, _)) if len >= r.prefix.len() => {}
                    _ => best = Some((r.prefix.len(), r)),
                }
            }
        }
        match best {
            Some((len, r)) => format!("{}{}", r.target, &imp[len..]),
            None => imp.to_string(),
        }
    }
}

fn parse_remap(s: &str) -> Option<Remapping> {
    let rest = match s.split_once(':') {
        Some((c, r)) if !c.is_empty() && r.contains('=') => r,
        _ => s,
    };
    let (prefix, target) = rest.split_once('=')?;
    Some(Remapping {
        prefix: prefix.to_string(),
        target: target.to_string(),
    })
}

fn collect_import_paths(text: &str) -> Vec<(String, usize, usize)> {
    let mut out = vec![];
    let b = text.as_bytes();
    let mut i = 0usize;
    while i < b.len() {
        if b[i..].starts_with(b"import") {
            let start = i;
            i += 6;
            while i < b.len() && (b[i] as char).is_whitespace() {
                i += 1;
            }
            if i < b.len() && b[i] == b'"' {
                let qs = i;
                i += 1;
                while i < b.len() && b[i] != b'"' && b[i] != b'\n' {
                    i += 1;
                }
                if i < b.len() && b[i] == b'"' {
                    let qe = i + 1;
                    let raw = &text[qs + 1..i];
                    out.push((unescape(raw), qs, qe));
                    i = qe;
                    continue;
                }
            }
            i = start + 6;
            continue;
        }
        if b[i] == b'/' && i + 1 < b.len() && b[i + 1] == b'/' {
            while i < b.len() && b[i] != b'\n' {
                i += 1;
            }
            continue;
        }
        if b[i] == b'/' && i + 1 < b.len() && b[i + 1] == b'*' {
            i += 2;
            while i + 1 < b.len() && !(b[i] == b'*' && b[i + 1] == b'/') {
                i += 1;
            }
            i += 2;
            continue;
        }
        i += 1;
    }
    out
}

fn unescape(s: &str) -> String {
    let mut out = String::new();
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.next() {
                Some('n') => out.push('\n'),
                Some('r') => out.push('\r'),
                Some('t') => out.push('\t'),
                Some('\\') => out.push('\\'),
                Some('"') => out.push('"'),
                Some(o) => out.push(o),
                None => {}
            }
        } else {
            out.push(c);
        }
    }
    out
}
