                PathBuf::from(input)
            } else {
                norm(&self.base.join(input))
            };
            queue.push((resolved, input.clone()));
        }
        if queue.is_empty() && !use_stdin {
            self.diagnostics.push(
                Diag::error("no files found").with_note(
                    "if you wish to use the standard input, please specify `-` explicitly".to_string(),
                ),
            );
            return Err(());
        }
        if use_stdin {
            let text = std::io::read_to_string(std::io::stdin()).unwrap_or_default();
            let idx = self.register(PathBuf::from("<stdin>"), text, false);
            let _ = idx;
        }
        let mut seen: Vec<PathBuf> = vec![];
        while let Some((resolved, err_path)) = queue.pop() {
            if seen.contains(&resolved) {
                continue;
            }
            seen.push(resolved.clone());
            let text = match Self::read_file(&resolved) {
