        let saved_pos = self.pos;
        let saved_diags = self.diags.len();
        let ok = self.try_var_decl_prefix();
        let mut me = unsafe { &mut *(self as *const Parser as *mut Parser) };
        me.pos = saved_pos;
        me.diags.truncate(saved_diags);
        ok
    }

    fn try_var_decl_prefix(&mut self) -> bool {
        if self.at_punct("(") {
            // tuple destructuring
            let mut p = self.pos;
            let mut depth = 0usize;
            let mut idents = 0usize;
            loop {
                if p >= self.toks.len() {
                    return false;
                }
                let t = &self.toks[p];
                if t.is_punct("(") {
                    depth += 1;
                } else if t.is_punct(")") {
                    depth -= 1;
                    if depth == 0 {
                        p += 1;
                        break;
                    }
