#[derive(Clone, Debug, Default)]
pub struct ResolvedContract {
    pub ctor: Option<(Vec<Json>, bool)>,
    pub errors: Vec<(String, Vec<Json>)>,
    pub events: Vec<(String, Vec<Json>, bool)>,
    pub fallback: Option<String>,
    pub receive: bool,
    pub funcs: Vec<(String, Vec<Json>, Vec<Json>, String)>,
    pub getters: Vec<(String, Vec<Json>, Vec<Json>)>,
}

impl Global {
    pub fn contract_key(&self, cid: usize) -> String {
        let path = self.units[self.contracts[cid].file].display_path.clone();
        format!("{}:{}", path, self.contracts[cid].name)
    }

    /// Resolves the types of a contract's items and checks for duplicates.
    pub fn resolve_contract(&mut self, cid: usize) -> ResolvedContract {
        let items = self.all_items(cid);
        let file = self.contracts[cid].file;
        let mut out = ResolvedContract::default();
        // 1. errors
        let error_decls: Vec<usize> = items
            .iter()
            .cloned()
            .filter(|d| matches!(self.decls[*d].kind, DeclKind::Error(_)))
            .collect();
        for d in error_decls {
            let params = match &self.decls[d].kind {
                DeclKind::Error(p) => p.clone(),
                _ => vec![],
            };
            let inputs = self.resolve_params(file, cid, &params, false);
            let name = self.decls[d].name.clone();
            let sig = format!("{}({})", name, crate::abi::canonical_of_json_list(&inputs));
            if let Some(pos) = out.errors.iter().position(|(n, i)| {
                *n == name && crate::abi::canonical_of_json_list(i) == crate::abi::canonical_of_json_list(&inputs)
            }) {
                let prev = self.error_spans.get(&(cid, pos)).cloned().unwrap_or_default();
                let msg = "event with same name and parameter types declared twice".to_string();
                let _ = msg;
                let mut dg = Diag::error("error with same name and parameter types declared twice")
                    .with_span(self.decls[d].name_span);
                dg.children
                    .push(self.note_child("other declaration", prev));
                self.diagnostics.push(dg);
                continue;
            }
            self.error_spans.insert((cid, out.errors.len()), self.decls[d].name_span);
            out.errors.push((name, inputs));
        }
        // 2. events
        let event_decls: Vec<usize> = items
            .iter()
            .cloned()
            .filter(|d| matches!(self.decls[*d].kind, DeclKind::Event(_, _)))
            .collect();
        for d in event_decls {
            let (params, anonymous) = match &self.decls[d].kind {
                DeclKind::Event(p, a) => (p.clone(), *a),
                _ => (vec![], false),
            };
            let inputs = self.resolve_params(file, cid, &params, true);
            let name = self.decls[d].name.clone();
            let canon = crate::abi::canonical_of_json_list(&inputs);
            if let Some(pos) = out.events.iter().position(|(n, i, _)| {
                *n == name && crate::abi::canonical_of_json_list(i) == canon
            }) {
                let prev = self.event_spans.get(&(cid, pos)).cloned().unwrap_or_default();
                let mut dg = Diag::error("event with same name and parameter types declared twice")
                    .with_span(self.decls[d].name_span);
                dg.children
                    .push(self.note_child("other declaration", prev));
                self.diagnostics.push(dg);
                continue;
            }
            self.event_spans.insert((cid, out.events.len()), self.decls[d].name_span);
            out.events.push((name, inputs, anonymous));
        }
        // 3. state variables
        let var_decls: Vec<usize> = items
            .iter()
            .cloned()
            .filter(|d| matches!(self.decls[*d].kind, DeclKind::Variable(_, _, _, _)))
            .collect();
        for d in var_decls {
            let (ty, vis, mutability, _init) = match &self.decls[d].kind {
                DeclKind::Variable(t, v, m, i) => (t.clone(), *v, *m, i.clone()),
                _ => continue,
            };
            if let Some(prev) = self.var_names.get(&(cid, self.decls[d].name.clone())) {
                let mut dg = Diag::error(format!(
                    "identifier `{}` already declared",
                    self.decls[d].name
                ))
                .with_span(self.decls[d].name_span);
                dg.children
                    .push(self.note_child("previous declaration declared here", *prev));
                self.diagnostics.push(dg);
                continue;
            }
            self.var_names
                .insert((cid, self.decls[d].name.clone()), self.decls[d].name_span);
            if !matches!(vis, Some(Visibility::Public)) {
                continue;
            }
            let resolved = self.resolve_type(&ty, file, Some(cid));
            let Some(t) = resolved else { continue };
            let (idx_types, out_ty, comps) = self.getter_parts(t);
            let name = self.decls[d].name.clone();
            let map = self.ctx_map();
            let ctx = abi::TypeCtx { structs: &map };
            let inputs: Vec<Json> = idx_types
                .iter()
                .map(|it| crate::abi::abi_param_json("", it, None, &ctx, &map))
                .collect();
            let outputs = vec![crate::abi::getter_output(&out_ty, &comps, &ctx, &map)];
            out.getters.push((name, inputs, outputs));
            let _ = mutability;
        }
        // 4. functions
        let fn_decls: Vec<usize> = items
            .iter()
            .cloned()
            .filter(|d| matches!(self.decls[*d].kind, DeclKind::Function(_, _, _)))
            .collect();
        let mut ctor = None;
        let mut fallback = None;
        let mut receive = false;
        let mut plain: Vec<usize> = vec![];
        for d in fn_decls {
            match &self.decls[d].kind {
                DeclKind::Function(FunctionKind::Constructor, h, _) => {
                    let inputs = self.resolve_params(file, cid, &h.params, false);
                    ctor = Some((inputs, matches!(h.mutability, Some(Mutability::Payable))));
                }
                DeclKind::Function(FunctionKind::Fallback, h, _) => {
                    fallback = Some(
                        match h.mutability {
                            Some(Mutability::Payable) => "payable",
                            Some(Mutability::Pure) => "pure",
                            Some(Mutability::View) => "view",
                            _ => "nonpayable",
                        }
                        .to_string(),
                    );
                }
                DeclKind::Function(FunctionKind::Receive, _, _) => receive = true,
                DeclKind::Function(_, h, _) => {
                    let vis = h.visibility.unwrap_or(Visibility::Internal);
                    if !matches!(vis, Visibility::Public | Visibility::External) {
                        continue;
                    }
                    plain.push(d);
                }
                _ => {}
            }
        }
        // deduplicate overrides: the most derived declaration wins
        let mut sigs: Vec<String> = vec![];
        let mut kept: Vec<usize> = vec![];
        for d in plain.iter().rev() {
            let h = match &self.decls[*d].kind {
                DeclKind::Function(_, h, _) => h.clone(),
                _ => continue,
            };
            let name = h.name.as_ref().map(|(s, _)| s.clone()).unwrap_or_default();
            let inputs = self.resolve_params(file, cid, &h.params, false);
            let sig = format!("{}({})", name, crate::abi::canonical_of_json_list(&inputs));
            if sigs.contains(&sig) {
                continue;
            }
            sigs.push(sig);
            kept.push(*d);
        }
        kept.reverse();
        for d in kept {
            let h = match &self.decls[d].kind {
                DeclKind::Function(_, h, _) => h.clone(),
                _ => continue,
            };
            let name = h.name.as_ref().map(|(s, _)| s.clone()).unwrap_or_default();
            let inputs = self.resolve_params(file, cid, &h.params, false);
            let sig = format!("{}({})", name, crate::abi::canonical_of_json_list(&inputs));
            // duplicate detection within the same contract
            if let Some(prev) = self.fn_spans.get(&(cid, sig.clone())) {
                let mut dg = Diag::error(
                    "function with same name and parameter types declared twice",
                )
                .with_span(self.decls[d].name_span);
                dg.children
                    .push(self.note_child("other declaration", *prev));
                self.diagnostics.push(dg);
                continue;
            }
            self.fn_spans.insert((cid, sig.clone()), self.decls[d].name_span);
            let outputs = self.resolve_params(file, cid, &h.returns, false);
            let sm = match h.mutability {
                Some(Mutability::Pure) => "pure",
                Some(Mutability::View) => "view",
                Some(Mutability::Payable) => "payable",
                _ => "nonpayable",
            }
            .to_string();
            out.funcs.push((name, inputs, outputs, sm));
        }
        out.ctor = ctor;
        out.fallback = fallback;
        out.receive = receive;
        out
    }

    fn note_child(&self, note: &str, span: Span) -> Diag {
        Diag {
            severity: crate::diag::Severity::Note,
            code: None,
            message: note.to_string(),
            primary: Some(crate::diag::SpanLabel { span, label: None }),
            secondary: vec![],
            notes: vec![],
            helps: vec![],
            children: vec![],
        }
    }

    pub fn generate_abi(&mut self, emit_abi: bool, emit_hashes: bool) -> Json {
        let struct_ids: Vec<usize> = (0..self.decls.len())
            .filter(|i| matches!(self.decls[*i].kind, DeclKind::Struct(_)))
            .collect();
        for sid in struct_ids {
            self.struct_members(sid);
        }
        let mut entries: Vec<(String, Json)> = vec![];
        for cid in 0..self.contracts.len() {
            let key = self.contract_key(cid);
            let value = self.contract_abi(cid, emit_abi, emit_hashes);
            entries.push((key, value));
        }
        entries.sort_by(|a, b| a.0.cmp(&b.0));
        let mut contracts_json = crate::json::obj();
        for (k, v) in entries {
            contracts_json.set(&k, v);
        }
        let mut out = crate::json::obj();
        if let Json::Object(m) = &contracts_json {
            if !m.is_empty() {
                out.set("contracts", contracts_json);
            }
        }
        out.set("version", Json::Str(crate::cli::VERSION.to_string()));
        out
    }

