            out.getters.push((name, inputs, outputs));
            let _ = mutability;
        }
        // 4. functions
        let fn_decls: Vec<usize> = items
            .iter()
            .cloned()
            .filter(|d| matches!(self.decls[*d].kind, DeclKind::Function(_, _, _)))
            .collect();
        let mut ctor = None;
        let mut fallback = None;
        let mut receive = false;
        let mut plain: Vec<usize> = vec![];
        for d in fn_decls {
            match &self.decls[d].kind {
                DeclKind::Function(FunctionKind::Constructor, h, _) => {
                    let inputs = self.resolve_params(file, cid, &h.params, false);
                    ctor = Some((inputs, matches!(h.mutability, Some(Mutability::Payable))));
                }
                DeclKind::Function(FunctionKind::Fallback, h, _) => {
                    fallback = Some(
                        match h.mutability {
                            Some(Mutability::Payable) => "payable",
                            Some(Mutability::Pure) => "pure",
                            Some(Mutability::View) => "view",
                            _ => "nonpayable",
                        }
                        .to_string(),
                    );
                }
                DeclKind::Function(FunctionKind::Receive, _, _) => receive = true,
                DeclKind::Function(_, h, _) => {
                    let vis = h.visibility.unwrap_or(Visibility::Internal);
