            virtual_: false,
            override_: None,
            modifiers: vec![],
        };
        if kind == FunctionKind::Function || kind == FunctionKind::Free {
            if self.is_ident() {
                let t = self.eat();
                header.name = Some((t.text.clone(), t.span));
            } else if !self.at_punct("(") {
                self.expected(Exp::Desc("identifier"));
                self.bail(&[";", "}"]);
                return Item {
                    span: start.join(self.prev_span()),
                    docs: vec![],
                    kind: ItemKind::Function { kind, header, body: Body::None },
                };
            }
        }
        if self.at_punct("(") {
            header.params = self.parse_param_list(false);
        } else {
            self.expected(Exp::Tok("("));
            self.bail(&[";", "}"]);
            return Item {
                span: start.join(self.prev_span()),
                docs: vec![],
                kind: ItemKind::Function { kind, header, body: Body::None },
            };
        }
        loop {
            if self.at_kw("returns") {
                self.bump();
                if !self.at_punct("(") {
                    self.expected(Exp::Tok("("));
                    self.bail(&[";", "}"]);
                    return Item {
                        span: start.join(self.prev_span()),
                        docs: vec![],
                        kind: ItemKind::Function { kind, header, body: Body::None },
                    };
                }
                header.returns = self.parse_param_list(true);
                continue;
            }
            if self.at_kw("external")
                || self.at_kw("internal")
                || self.at_kw("public")
                || self.at_kw("private")
            {
                let t = self.eat();
                let v = match t.text.as_str() {
                    "external" => Visibility::External,
                    "internal" => Visibility::Internal,
                    "public" => Visibility::Public,
                    _ => Visibility::Private,
                };
                if header.visibility.is_some() {
                    let prev = header.visibility_span.unwrap_or(start);
                    let sp = t.span;
                    let mut d = Diag::error("visibility already specified").with_span(sp);
                    d.secondary
                        .push(crate::diag::SpanLabel { span: prev, label: Some("previous definition".to_string()) });
                    self.diags.push(d);
                } else {
                    header.visibility = Some(v);
                    header.visibility_span = Some(t.span);
                }
                continue;
            }
            if self.at_kw("pure")
                || self.at_kw("view")
                || self.at_kw("payable")
                || self.at_kw("constant")
                || self.at_kw("immutable")
                || self.at_kw("transient")
            {
                let t = self.eat();
                let m = match t.text.as_str() {
                    "pure" => Mutability::Pure,
                    "view" => Mutability::View,
                    "payable" => Mutability::Payable,
                    "constant" => Mutability::Constant,
                    "immutable" => Mutability::Immutable,
                    _ => Mutability::Transient,
                };
                if header.mutability.is_some() {
                    let prev = header.mutability_span.unwrap_or(start);
                    let sp = t.span;
                    let mut d = Diag::error("state mutability already specified").with_span(sp);
                    d.secondary
                        .push(crate::diag::SpanLabel { span: prev, label: Some("previous definition".to_string()) });
                    self.diags.push(d);
                } else {
                    header.mutability = Some(m);
                    header.mutability_span = Some(t.span);
                }
                continue;
            }
            if self.eat_kw("virtual") {
                header.virtual_ = true;
                continue;
            }
            if self.at_kw("override") {
                header.override_ = Some(self.parse_override());
                continue;
            }
            if self.is_ident() {
                let path = self.parse_path();
                let args = if self.at_punct("(") {
                    Some(self.parse_call_args())
                } else {
                    None
                };
                header.modifiers.push((path, args));
                continue;
