                Exp::Tok("external"),
                Exp::Tok("internal"),
                Exp::Tok("override"),
                Exp::Tok("payable"),
                Exp::Tok("private"),
                Exp::Tok("public"),
                Exp::Tok("pure"),
                Exp::Tok("returns"),
                Exp::Tok("view"),
                Exp::Tok("virtual"),
                Exp::Tok("{"),
            ]);
            self.bail(&[";", "}"]);
            return Item {
                span: start.join(self.prev_span()),
                docs: vec![],
                kind: ItemKind::Function { kind, header, body: Body::None },
            };
        }
        header.span = start.join(self.prev_span());
        let body = self.parse_function_body();
        Item {
            span: start.join(self.prev_span()),
            docs: vec![],
            kind: ItemKind::Function { kind, header, body },
        }
    }

