impl Global {
    /// Contract level semantic checks (abstract/override related).
    pub fn semantic_checks(&mut self) {
        let n = self.contracts.len();
        for cid in 0..n {
            let (kind, abstract_, name, name_span, kw_span, file) = {
                let c = &self.contracts[cid];
                (c.kind, c.abstract_, c.name.clone(), c.name_span, c.kw_span, c.file)
            };
            let items = self.all_items(cid);
            // collect function signatures of the bases
            let mut unimplemented: Vec<usize> = vec![];
            let mut own_sigs: Vec<(String, String)> = vec![];
            for &d in &items {
                if let DeclKind::Function(kind_fn, h, body) = &self.decls[d].kind {
                    let sig = function_sig(h);
                    let is_own = self.decls[d].contract == Some(cid);
                    if is_own {
                        own_sigs.push((sig.clone(), format!("{:?}", d)));
                    }
                    match kind_fn {
                        FunctionKind::Constructor
                        | FunctionKind::Fallback
                        | FunctionKind::Receive => {}
                        _ => {
                            if matches!(body, Body::None) {
                                unimplemented.push(d);
                            }
                        }
                    }
                }
            }
            // override checks
            for &d in &items {
                if let DeclKind::Function(kind_fn, h, body) = &self.decls[d].kind {
                    let is_own = self.decls[d].contract == Some(cid);
                    if !is_own {
                        continue;
                    }
                    let sig = function_sig(h);
                    let has_base = items.iter().any(|&b| {
                        b != d
                            && self.decls[b].contract != Some(cid)
                            && matches!(&self.decls[b].kind, DeclKind::Function(k2, h2, _)
                                if function_sig(h2) == sig && !matches!(k2, FunctionKind::Constructor|FunctionKind::Fallback|FunctionKind::Receive))
                    });
                    match kind_fn {
                        FunctionKind::Constructor
                        | FunctionKind::Fallback
                        | FunctionKind::Receive => {}
                        _ => {
                            if h.override_.is_some() && !has_base {
                                let mut dg = Diag::error(
                                    "Function has override specified but does not override anything",
                                )
                                .with_code("7792")
                                .with_span(self.decls[d].span);
                                self.diagnostics.push(dg);
                            } else if h.override_.is_none()
                                && has_base
                                && !matches!(body, Body::None)
                            {
                                let base = items
                                    .iter()
                                    .cloned()
                                    .find(|&b| {
                                        b != d
                                            && self.decls[b].contract != Some(cid)
                                            && matches!(&self.decls[b].kind, DeclKind::Function(_, h2, _)
                                                if function_sig(h2) == sig)
                                    });
                                let mut dg = Diag::error(
                                    "overriding function is missing `override` specifier",
                                )
                                .with_code("9456")
                                .with_span(self.decls[d].span);
                                if let Some(b) = base {
                                    let mut note = self.note_child("overridden function is here", self.decls[b].span);
                                    note.helps
                                        .push(("add `override` to the function signature".to_string(), None));
                                    dg.children.push(note);
                                }
                                self.diagnostics.push(dg);
                            }
                        }
                    }
                }
                if let DeclKind::Variable(_, _, _, _) = &self.decls[d].kind {
                    let is_own = self.decls[d].contract == Some(cid);
                    if !is_own {
                        continue;
                    }
                    // public state variable override checks
                    if let DeclKind::Variable(_, vis, _, _) = &self.decls[d].kind {
                        if matches!(vis, Some(Visibility::Public)) {
                            let has_base_var = items.iter().any(|&b| {
                                b != d
                                    && self.decls[b].contract != Some(cid)
                                    && matches!(&self.decls[b].kind, DeclKind::Variable(_, Some(Visibility::Public), _, _))
                            });
                            let has_override = matches!(&self.decls[d].kind, DeclKind::Variable(_, _, _, _));
                            let _ = has_override;
                            if has_base_var {
                                // missing override
                                let base = items
                                    .iter()
                                    .cloned()
                                    .find(|&b| {
                                        b != d
                                            && self.decls[b].contract != Some(cid)
                                            && matches!(&self.decls[b].kind, DeclKind::Variable(_, Some(Visibility::Public), _, _))
                                    });
                                let mut dg = Diag::error(
                                    "public state variable overriding function is missing `override` specifier",
                                )
                                .with_span(self.decls[d].span);
                                if let Some(b) = base {
                                    dg.children
                                        .push(self.note_child("overridden function is here", self.decls[b].span));
                                }
                                self.diagnostics.push(dg);
                            }
                        }
                    }
                }
            }
            // unimplemented functions
            if kind == ContractKind::Contract
                && !abstract_
                && !unimplemented.is_empty()
            {
                let mut dg = Diag::error(format!(
                    "contract `{}` has unimplemented functions",
                    name
                ))
                .with_code("3656")
                .with_span(name_span);
                dg.helps.push((
                    "mark the contract as abstract: `abstract contract`".to_string(),
                    Some(kw_span),
                ));
                for &d in &unimplemented {
                    let fname = match &self.decls[d].kind {
                        DeclKind::Function(_, h, _) => {
                            h.name.as_ref().map(|(s, _)| s.clone()).unwrap_or_default()
                        }
                        _ => String::new(),
                    };
                    dg.children.push(self.note_child(
                        &format!("unimplemented function `{}` defined in `{}`", fname, name),
                        self.decls[d].span,
                    ));
                }
                self.diagnostics.push(dg);
            }
            // modifiers must have a `_;` placeholder
            for &d in &items {
                if let DeclKind::Modifier(h, body) = &self.decls[d].kind {
                    let is_own = self.decls[d].contract == Some(cid);
                    if !is_own {
                        continue;
                    }
                    if !has_placeholder(body) {
                        let sp = h
                            .params_span
                            .unwrap_or(self.decls[d].span);
                        self.diagnostics.push(
                            Diag::error("modifier must have a `_;` placeholder statement")
                                .with_span(Span::new(sp.file, sp.start, sp.start + 1)),
                        );
                    }
                }
            }
            let _ = file;
        }
    }
}

fn function_sig(h: &FunctionHeader) -> String {
    let name = h.name.as_ref().map(|(s, _)| s.clone()).unwrap_or_default();
    let params: Vec<String> = h
        .params
        .iter()
        .map(|p| match &p.ty {
            Some(t) => type_text(t),
            None => String::new(),
        })
        .collect();
    format!("{}({})", name, params.join(","))
}

fn type_text(t: &Type) -> String {
    match &*t.kind {
        TypeKind::Elementary(e) => crate::abi::elementary_canonical(*e),
        TypeKind::UserDefined(p) => p.to_string(),
        TypeKind::Mapping(k, v) => format!("mapping({} => {})", type_text(k), type_text(v)),
        TypeKind::Array(e, size) => match size {
            Some(s) => format!("{}[{}]", type_text(e), crate::lower::eval_const(s).map(|v| v.to_string()).unwrap_or_default()),
            None => format!("{}[]", type_text(e)),
        },
        TypeKind::Function(_, _, _, _) => "function".to_string(),
    }
}

fn has_placeholder(body: &Body) -> bool {
    match body {
        Body::None => false,
        Body::Block(stmts) => stmts.iter().any(|s| matches!(s.kind, StmtKind::Placeholder)),
    }
}
