        for d in fn_decls {
            let header = match &self.decls[d].kind {
                DeclKind::Function(_, h, _) => h.clone(),
                _ => continue,
            };
            match &self.decls[d].kind {
                DeclKind::Function(FunctionKind::Constructor, _, _) => {
                    let inputs = self.resolve_params(file, cid, &header.params, false);
                    ctor = Some((inputs, matches!(header.mutability, Some(Mutability::Payable))));
                }
                DeclKind::Function(FunctionKind::Fallback, _, _) => {
                    fallback = Some(
                        match header.mutability {
                            Some(Mutability::Payable) => "payable",
                            Some(Mutability::Pure) => "pure",
                            Some(Mutability::View) => "view",
                            _ => "nonpayable",
                        }
                        .to_string(),
                    );
                }
                DeclKind::Function(FunctionKind::Receive, _, _) => receive = true,
                DeclKind::Function(_, _, _) => {
                    let vis = header.visibility.unwrap_or(Visibility::Internal);
                    let public = matches!(vis, Visibility::Public | Visibility::External);
                    let inputs = self.resolve_params(file, cid, &header.params, false);
                    let outputs = self.resolve_params(file, cid, &header.returns, false);
                    let name = header.name.as_ref().map(|(s, _)| s.clone()).unwrap_or_default();
                    let sig = format!("{}({})", name, crate::abi::canonical_of_json_list(&inputs));
                    let sm = match header.mutability {
                        Some(Mutability::Pure) => "pure",
                        Some(Mutability::View) => "view",
                        Some(Mutability::Payable) => "payable",
