                    out.funcs.push((f.name.clone(), f.inputs.clone(), f.outputs.clone(), f.sm.clone()));
                    out.sigs.push(f.sig.clone());
                }
            }
        }
        out.ctor = ctor;
        out.fallback = fallback;
        out.receive = receive;
        out
    }

